        },
        Content_Batt02_01_01 = {
          ContentDE = "Alerta por su presa, la grandiosa Matriz de Caza de las Mil Trampas emerge del suelo con un estruendo ensordecedor. Te encuentras atrapado en un antiguo dispositivo mecánico.\nSeparado accidentalmente del Sr. Qiu, de repente ves a un hombre desconocido en tu camino. Ve a hablar con él para entender lo que está pasando.",
          TextMapId = "Content_Batt02_01_01"
        },
        Content_Batt02_01_02 = {
          ContentDE = "Alerta por su presa, la grandiosa Matriz de Caza de las Mil Trampas emerge del suelo con un estruendo ensordecedor. Te encuentras atrapado en un antiguo dispositivo mecánico.\nSeparado accidentalmente del Sr. Qiu, de repente ves a un hombre desconocido en tu camino. Ve a hablar con él para entender lo que está pasando.",
          TextMapId = "Content_Batt02_01_02"
        },
        Content_Batt02_01_03 = {
          ContentDE = "Alerta por su presa, la grandiosa Matriz de Caza de las Mil Trampas emerge del suelo con un estruendo ensordecedor. Te encuentras atrapado en un antiguo dispositivo mecánico.\nSeparado accidentalmente del Sr. Qiu, conoces a un hombre llamado Kezhou. Con vuestros destinos ahora entrelazados, avanzad juntos para encontrar una salida.",
          TextMapId = "Content_Batt02_01_03"
        },
