        DUNGEON_RESCUE_101 = {
          ContentDE = "Finde die <H>Geheimzelle</>, die das Ziel enthält, knacke den Mechanismus und sichere das Ziel.",
          TextMapId = "DUNGEON_RESCUE_101"
        },
        DUNGEON_RESCUE_102 = {
          ContentDE = "Versuche zu vermeiden, dass dich die gegnerischen <H>Patrouillen</> in der Nähe der <H>Geheimzellen</> entdecken. Wenn du entdeckt wirst, besiege sie schnell, um zu verhindern, dass sie den Alarm auslösen.",
          TextMapId = "DUNGEON_RESCUE_102"
        },
        DUNGEON_RESCUE_103 = {
          ContentDE = "Wenn du nicht verhindern kannst, dass die Patrouillen den Alarm auslösen, ist das Ziel in Gefahr. Finde das Ziel, bevor der <H>Countdown</> abläuft, sonst scheitert die Mission.",
          TextMapId = "DUNGEON_RESCUE_103"
        },
        DUNGEON_RESCUE_104 = {
          ContentDE = "Nachdem du das Ziel gerettet hast, eskortiere es zum Evakuierungspunkt. Achte während der gesamten Reise sorgfältig auf die Sicherheit.",
          TextMapId = "DUNGEON_RESCUE_104"
        },
        DUNGEON_RESCUE_105 = {
          ContentDE = "Die Mission gilt als abgeschlossen, sobald das Ziel sicher zum Evakuierungspunkt eskortiert wurde.",
          TextMapId = "DUNGEON_RESCUE_105"
        },
        DUNGEON_SABOTAGEPRO_100 = {
          ContentDE = "Zerlegen",
          TextMapId = "DUNGEON_SABOTAGEPRO_100"
        },
        DUNGEON_SABOTAGEPRO_101 = {
          ContentDE = "Zerlege drei Geräte",
          TextMapId = "DUNGEON_SABOTAGEPRO_101"
        },
        DUNGEON_SABOTAGEPRO_102 = {
          ContentDE = "Knacke den Mechanismus, um den Kern des Geräts freizulegen",
          TextMapId = "DUNGEON_SABOTAGEPRO_102"
        },
        DUNGEON_SABOTAGEPRO_103 = {
          ContentDE = "Zerlege alle drei Geräte innerhalb des Zeitlimits",
          TextMapId = "DUNGEON_SABOTAGEPRO_103"
        },
        DUNGEON_SABOTAGE_100 = {
          ContentDE = "Knacke den Mechanismus, um den Zünder des „Großen Feuerwerks“ freizulegen.",
          TextMapId = "DUNGEON_SABOTAGE_100"
        },
        DUNGEON_SABOTAGE_101 = {
          ContentDE = "Zusätzliche Mission",
          TextMapId = "DUNGEON_SABOTAGE_101"
        },
        DUNGEON_SABOTAGE_102 = {
          ContentDE = "(Optional) Finde und besiege die Mitglieder der Verlassenen",
          TextMapId = "DUNGEON_SABOTAGE_102"
        },
        DUNGEON_SABOTAGE_103 = {
          ContentDE = "Zerstöre den Zünder des „Großen Feuerwerks“, um die Explosion zu verhindern",
          TextMapId = "DUNGEON_SABOTAGE_103"
        },
        DUNGEON_SABOTAGE_104 = {
          ContentDE = "Der „Sprengfanatiker“ wurde besiegt. Der Zünder des „Großen Feuerwerks“ ist jetzt anfälliger.",
          TextMapId = "DUNGEON_SABOTAGE_104"
        },
        DUNGEON_SABOTAGE_105 = {
          ContentDE = "Der „Spielzeugmacher“ wurde besiegt. Entlang der Rückzugsroute gibt es jetzt Sprungpads.",
          TextMapId = "DUNGEON_SABOTAGE_105"
        },
        DUNGEON_SABOTAGE_106 = {
          ContentDE = "Der „Betrüger“ wurde besiegt. Bei dieser Mission erscheinen keine Elitegegner mehr.",
          TextMapId = "DUNGEON_SABOTAGE_106"
        },
        DUNGEON_SABOTAGE_107 = {
          ContentDE = "Countdown für die Missionseinreichung",
          TextMapId = "DUNGEON_SABOTAGE_107"
        },
        DUNGEON_SABOTAGE_108 = {
          ContentDE = "„Großes Feuerwerk“",
          TextMapId = "DUNGEON_SABOTAGE_108"
        },
        DUNGEON_SABOTAGE_109 = {
          ContentDE = "Leg den Zünder frei",
          TextMapId = "DUNGEON_SABOTAGE_109"
        },
        DUNGEON_SABOTAGE_110 = {
          ContentDE = "Finde den Zünder des „Großen Feuerwerks“ und lege ihn frei",
          TextMapId = "DUNGEON_SABOTAGE_110"
        },
        DUNGEON_SABOTAGE_111 = {
          ContentDE = "Das <Highlight>Sprungpad</> hilft dir dabei, dich schneller zurückzuziehen.",
          TextMapId = "DUNGEON_SABOTAGE_111"
        },
        DUNGEON_SABOTAGE_112 = {
          ContentDE = "Bevor du den Zünder des „Großen Feuerwerks“ freilegst, kannst du zuerst einmal den Anführer der Verlassenen in der Arena besiegen, um die nächste Herausforderung einfacher zu gestalten.",
          TextMapId = "DUNGEON_SABOTAGE_112"
        },
        DUNGEON_SABOTAGE_113 = {
          ContentDE = "Sobald der <Highlight>Zünder</> des „Großen Feuerwerks“ freigelegt ist, solltest du ihn schnell zerstören, um den Mechanismus auszuschalten.",
          TextMapId = "DUNGEON_SABOTAGE_113"
        },
        DUNGEON_SABOTAGE_114 = {
          ContentDE = "Nachdem du den Zünder des „Großen Feuerwerks“ zerstört hast, begib dich so schnell wie möglich zum Evakuierungspunkt.",
          TextMapId = "DUNGEON_SABOTAGE_114"
        },
        DUNGEON_SABOTAGE_115 = {
          ContentDE = "Der „Sprengfanatiker“ wurde besiegt. Der Zünder des „Großen Feuerwerks“ ist jetzt anfälliger.",
          TextMapId = "DUNGEON_SABOTAGE_115"
        },
        DUNGEON_SABOTAGE_116 = {
          ContentDE = "Spielzeugmacher wurde besiegt. Der Wasserstand geht in allen Bereichen zurück.",
          TextMapId = "DUNGEON_SABOTAGE_116"
        },
        DUNGEON_SABOTAGE_117 = {
          ContentDE = "Löse das Puzzle, um den Zünder des „Großen Feuerwerks“ freizulegen und ihn zu zerstören.",
          TextMapId = "DUNGEON_SABOTAGE_117"
        },
        DUNGEON_SABOTAGE_118 = {
          ContentDE = "„Großes Feuerwerk“ zerstört – begib dich zum Evakuierungspunkt.",
          TextMapId = "DUNGEON_SABOTAGE_118"
        },
        DUNGEON_STEAMWARN_101 = {
          ContentDE = "Halte dich vom Dampf fern!",
          TextMapId = "DUNGEON_STEAMWARN_101"
        },
        DUNGEON_SURVIVALMINIPRO_100 = {
          ContentDE = "Begib dich zur Trankstation",
          TextMapId = "DUNGEON_SURVIVALMINIPRO_100"
        },
        DUNGEON_SURVIVALMINIPRO_101 = {
          ContentDE = "Besiege Gegner in der Nähe der Trankstation, um Serum zu sammeln",
          TextMapId = "DUNGEON_SURVIVALMINIPRO_101"
        },
        DUNGEON_SURVIVALMINIPRO_102 = {
          ContentDE = "Aktiviere das Gerät, um die Mission zu starten",
          TextMapId = "DUNGEON_SURVIVALMINIPRO_102"
        },
        DUNGEON_SURVIVALMINIPRO_103 = {
          ContentDE = "Lokalisiere die Trankstation und besiege Gegner in der Nähe, um Serum zu erhalten",
          TextMapId = "DUNGEON_SURVIVALMINIPRO_103"
        },
        DUNGEON_SURVIVALMINIPRO_104 = {
          ContentDE = "Die Mission ist abgeschlossen, sobald das Serum der Trankstation <Highlight>100 %</> erreicht",
          TextMapId = "DUNGEON_SURVIVALMINIPRO_104"
        },
        DUNGEON_SURVIVALMINIPRO_106 = {
          ContentDE = "Serum nimmt schneller ab. Eliminiere Primarch –Korrosion unverzüglich.",
          TextMapId = "DUNGEON_SURVIVALMINIPRO_106"
        },
        DUNGEON_SURVIVALMINIPRO_107 = {
          ContentDE = "Serum-Abnahme verlangsamt",
          TextMapId = "DUNGEON_SURVIVALMINIPRO_107"
        },
        DUNGEON_SURVIVALMINIPRO_108 = {
          ContentDE = "Serum-Verarbeitung abgeschlossen – begib dich zum Evakuierungspunkt",
          TextMapId = "DUNGEON_SURVIVALMINIPRO_108"
        },
        DUNGEON_SURVIVALPRO_100 = {
          ContentDE = "In den Bereich der Trankstation eingetreten",
          TextMapId = "DUNGEON_SURVIVALPRO_100"
        },
        DUNGEON_SURVIVALPRO_101 = {
          ContentDE = "Trankstation zu weit weg. Buff läuft ab",
          TextMapId = "DUNGEON_SURVIVALPRO_101"
        },
        DUNGEON_SURVIVALPRO_102 = {
          ContentDE = "Wähle eine Trankstation und begib dich dorthin",
          TextMapId = "DUNGEON_SURVIVALPRO_102"
        },
        DUNGEON_SURVIVALPRO_104 = {
          ContentDE = "Besiege den Primarch – Korrosion",
          TextMapId = "DUNGEON_SURVIVALPRO_104"
        },
        DUNGEON_SURVIVALPRO_108 = {
          ContentDE = "Serum voll",
          TextMapId = "DUNGEON_SURVIVALPRO_108"
        },
        DUNGEON_SURVIVALPRO_109 = {
          ContentDE = "In der Trankstation gibt es kein Serum mehr.",
          TextMapId = "DUNGEON_SURVIVALPRO_109"
        },
        DUNGEON_SURVIVALPRO_110 = {
          ContentDE = "Die Trankstation sammelt Serum von besiegten Gegnern in der Nähe. Je mehr Serum in der Trankstation gespeichert ist, desto stärkere Buffs bietet sie.",
          TextMapId = "DUNGEON_SURVIVALPRO_110"
        },
        DUNGEON_SURVIVALPRO_111 = {
          ContentDE = "Ein Primarch – Korrosion wird bald erscheinen!",
          TextMapId = "DUNGEON_SURVIVALPRO_111"
        },
        DUNGEON_SURVIVALPRO_112 = {
          ContentDE = "Nicht genug Serum!",
          TextMapId = "DUNGEON_SURVIVALPRO_112"
        },
        DUNGEON_SURVIVALPRO_113 = {
          ContentDE = "Serum wird ständig verbraucht",
          TextMapId = "DUNGEON_SURVIVALPRO_113"
        },
        DUNGEON_SURVIVALPRO_114 = {
          ContentDE = "Serumkonzentration beginnt bei <Highlight>0 %</>. Aktiviere das Gerät und steigere es dann auf verschiedene Arten.",
          TextMapId = "DUNGEON_SURVIVALPRO_114"
        },
        DUNGEON_SURVIVALPRO_115 = {
          ContentDE = "Wenn Gegner besiegt werden, lassen sie manchmal Serum fallen. Wenn du es aufhebst, steigt dein Serum um <Highlight>5 %</>.",
          TextMapId = "DUNGEON_SURVIVALPRO_115"
        },
        DUNGEON_SURVIVALPRO_116 = {
          ContentDE = "Finde Serum-Lager – jedes davon erhöht das Serum um <Highlight>15 %</>. Das Symbol links zeigt die Anzahl der entdeckten Serum-Lager.",
          TextMapId = "DUNGEON_SURVIVALPRO_116"
        },
        DUNGEON_SURVIVALPRO_117 = {
          ContentDE = "Wenn die Serumkonzentration <Highlight>100 %</> erreicht, kannst du dich zurückziehen oder weitermachen. Wenn du weitermachst, wird das Serum auf 0 % zurückgesetzt.",
          TextMapId = "DUNGEON_SURVIVALPRO_117"
        },
        DUNGEON_SURVIVALPRO_118 = {
          ContentDE = "Nachdem du mit dem Gerät interagiert hast, sinkt das Serum kontinuierlich; wenn der Wert auf <Highlight>0 %</> fällt, ist die Mission gescheitert. Finde schnell eine Trankstation und extrahiere Serum.",
          TextMapId = "DUNGEON_SURVIVALPRO_118"
        },
        DUNGEON_SURVIVALPRO_119 = {
          ContentDE = "Eine Trankstation bietet <Highlight>Ressourcen</> oder gewährt <Highlight>Heilung</>- oder <Highlight>Angriff</>-Buffs. Verschiedene Trankstationen haben unterschiedliche Funktionen.",
          TextMapId = "DUNGEON_SURVIVALPRO_119"
        },
        DUNGEON_SURVIVALPRO_120 = {
          ContentDE = "Die Trankstation sammelt Serum von besiegten Gegnern in der Nähe. Je mehr Serum in der Trankstation gespeichert ist, desto stärkere Buffs bietet sie.",
          TextMapId = "DUNGEON_SURVIVALPRO_120"
        },
        DUNGEON_SURVIVALPRO_121 = {
          ContentDE = "Nähere dich der Trankstation und <Highlight>halte die Interaktionstaste gedrückt, um Serum zu extrahieren, das dir beim Überleben hilft</>.",
          TextMapId = "DUNGEON_SURVIVALPRO_121"
        },
        DUNGEON_SURVIVALPRO_122 = {
          ContentDE = "Nach <Highlight>drei Minuten</> kannst du wählen, ob du dich zurückziehst oder den Kampf fortsetzt, um mehr Belohnungen zu erhalten.",
          TextMapId = "DUNGEON_SURVIVALPRO_122"
        },
        DUNGEON_SURVIVALPRO_123 = {
          ContentDE = "Während dieser Phase erscheinen keine neuen Gegner oder Serum-Lager im Kampf. Entdecktes Serum und gefundene Serum-Lager verschwinden ebenfalls. Wenn du den Evakuierungspunkt nicht innerhalb von <Highlight>zwei Minuten</> erreichst, scheitert die Mission.",
          TextMapId = "DUNGEON_SURVIVALPRO_123"
        },
        DUNGEON_SURVIVALPRO_124 = {
          ContentDE = "Von der Trankstation gewährter Buff:",
          TextMapId = "DUNGEON_SURVIVALPRO_124"
        },
        DUNGEON_SURVIVALPRO_125 = {
          ContentDE = "Ein Primarch – Korrosion ist erschienen!",
          TextMapId = "DUNGEON_SURVIVALPRO_125"
        },
        DUNGEON_SURVIVAL_100 = {
          ContentDE = "Serum",
          TextMapId = "DUNGEON_SURVIVAL_100"
        },
        DUNGEON_SYNTHESIS_100 = {
          ContentDE = "Verfolgung",
          TextMapId = "DUNGEON_SYNTHESIS_100"
        },
        DUNGEON_SYNTHESIS_101 = {
          ContentDE = "Suchfortschritt",
          TextMapId = "DUNGEON_SYNTHESIS_101"
        },
        DUNGEON_SYNTHESIS_102 = {
          ContentDE = "Gesetzter Spieler gefunden",
          TextMapId = "DUNGEON_SYNTHESIS_102"
        },
        DUNGEON_SYNTHESIS_103 = {
          ContentDE = "Nächstes Zusammenstellen hat angefangen. Begib dich bitte zur Arena.",
          TextMapId = "DUNGEON_SYNTHESIS_103"
        },
        DUNGEON_SYNTHESIS_104 = {
          ContentDE = "Fortschritt der Preistruhe （%d/%d）",
          TextMapId = "DUNGEON_SYNTHESIS_104"
        },
        DUNGEON_SYNTHESIS_105 = {
          ContentDE = "Preistruhe",
          TextMapId = "DUNGEON_SYNTHESIS_105"
        },
        DUNGEON_SYNTHESIS_106 = {
          ContentDE = "Preistruhe wird gleich zerstört",
          TextMapId = "DUNGEON_SYNTHESIS_106"
        },
        DUNGEON_SYNTHESIS_107 = {
          ContentDE = "Haltbarkeit der Preistruhe",
          TextMapId = "DUNGEON_SYNTHESIS_107"
        },
        DUNGEON_SYNTHESIS_108 = {
          ContentDE = "Preistruhe zerstört",
          TextMapId = "DUNGEON_SYNTHESIS_108"
        },
        DUNGEON_SYNTHESIS_109 = {
          ContentDE = "Der beste Spieler aus „Möge das Heilige Licht dich beschützen“ betritt die Arena – verhindere, dass die Preistruhe zerstört wird!",
          TextMapId = "DUNGEON_SYNTHESIS_109"
        },
        DUNGEON_SYNTHESIS_110 = {
          ContentDE = "Preistruhe kann freigeschaltet werden",
          TextMapId = "DUNGEON_SYNTHESIS_110"
        },
        DUNGEON_SYNTHESIS_111 = {
          ContentDE = "Zone gesichert",
          TextMapId = "DUNGEON_SYNTHESIS_111"
        },
        DUNGEON_SYNTHESIS_112 = {
          ContentDE = "Turnierabschluss",
          TextMapId = "DUNGEON_SYNTHESIS_112"
        },
        DUNGEON_SYNTHESIS_113 = {
          ContentDE = "Gesetzte Spieler aus anderen Teams gefunden （%d/%d）",
          TextMapId = "DUNGEON_SYNTHESIS_113"
        },
        DUNGEON_SYNTHESIS_114 = {
          ContentDE = "Eliminiere die gesetzten Spieler der Gegner",
          TextMapId = "DUNGEON_SYNTHESIS_114"
        },
        DUNGEON_SYNTHESIS_115 = {
          ContentDE = "Markierte Zonen gesichert （%d/%d）",
          TextMapId = "DUNGEON_SYNTHESIS_115"
        },
        DUNGEON_SYNTHESIS_116 = {
          ContentDE = "Fahre mit der nächsten Arena fort",
          TextMapId = "DUNGEON_SYNTHESIS_116"
        },
        DUNGEON_SYNTHESIS_117 = {
          ContentDE = "Verteidige die Preistruhe und sammle die Schlüssel",
          TextMapId = "DUNGEON_SYNTHESIS_117"
        },
        DUNGEON_SYNTHESIS_118 = {
          ContentDE = "Öffne die Preistruhe und warte auf den Abschluss des Turniers",
          TextMapId = "DUNGEON_SYNTHESIS_118"
        },
        DUNGEON_SYNTHESIS_119 = {
          ContentDE = "Dieses Turnier besteht aus drei Matches, in denen die Fähigkeiten in den Bereichen Verfolgung, Verteidigung und Kampfkunst getestet werden.",
          TextMapId = "DUNGEON_SYNTHESIS_119"
        },
        DUNGEON_SYNTHESIS_120 = {
          ContentDE = "Sammle im ersten Match Hinweise aus Hinweistruhen oder von Rivalen, um die gesetzten Spieler der anderen Teams zu finden und zu eliminieren.",
          TextMapId = "DUNGEON_SYNTHESIS_120"
        },
        DUNGEON_SYNTHESIS_121 = {
          ContentDE = "Das Zerstören von Hinweistruhen kann Überraschungen enthüllen, die die Organisatoren vorbereitet haben.",
          TextMapId = "DUNGEON_SYNTHESIS_121"
        },
        DUNGEON_SYNTHESIS_122 = {
          ContentDE = "Im zweiten Match musst du dich gegen die anderen Teams behaupten und in den markierten Zonen bleiben, um sie zu sichern.",
          TextMapId = "DUNGEON_SYNTHESIS_122"
        },
        DUNGEON_SYNTHESIS_123 = {
          ContentDE = "Im dritten Match kämpfen alle Teams um die Preistruhe. Verteidige sie und sammle alle 6 Schlüssel!",
          TextMapId = "DUNGEON_SYNTHESIS_123"
