        Event_Des_103005 = {
          ContentDE = "Como {性别:un Phoxcazador experimentado|una Phoxcazadora experimentada} , se te ha recomendado ayudarla a prepararse. Recolecta lo que necesita y gana generosas recompensas.",
          TextMapId = "Event_Des_103005"
