        },
        FeinaEvent_DungeonDes_1 = {
          ContentDE = "Fina entra en un mundo de cuentos y llega como invitada a la casa del Gran Mago, pero él parece haber partido... Sigue las huellas que dejó y encuentra la salida de la cueva.",
          TextMapId = "FeinaEvent_DungeonDes_1"
        },
        FeinaEvent_DungeonDes_2 = {
          ContentDE = "Al salir de la cueva oscura, Fina emerge en un vasto laberinto. No temáis los trampas y desvíos: con la ayuda de {性别:Señor|Señora} Unicornio, ella sabrá resolver cada uno de los enigmas que se presenten en su camino.",
          TextMapId = "FeinaEvent_DungeonDes_2"
        },
        FeinaEvent_DungeonDes_3 = {
          ContentDE = "El camino se interrumpe por un lago resplandeciente, pero tal pequeño obstáculo no detendrá a Fina. Con la ayuda de Señorita Mariposa para despejar el camino espinoso, sube a la barca y cruza al otro lado.",
          TextMapId = "FeinaEvent_DungeonDes_3"
