        HomePianoAcc_1013001 = {
          ContentDE = "Fuente: Disponible para compra en el Lunoeggy de Primavera Eterna tras completar la misión principal “Un visitante de Haojing”.",
          TextMapId = "HomePianoAcc_1013001"
