        MESSAGE_LOADING_101_PC = {
          ContentDE = "Un puerto bullicioso en Puerto de las Brumas, con barcos que entran y salen durante todo el año.\nSirve como el primer puerto de escala para los Tejestrellas que parten a cruzar el continente de Atlasia.",
          TextMapId = "MESSAGE_LOADING_101_PC"
        },
        MESSAGE_LOADING_102_PC = {
          ContentDE = "Grandes tablillas de piedra grabadas con las amonestaciones de los Nueve Capítulos de Dafeng, se alzan en lugares bien visibles por todo Huaxu, recordando sin descanso sus preceptos a los vivos.",
          TextMapId = "MESSAGE_LOADING_102_PC"
        },
        MESSAGE_LOADING_103_PC = {
          ContentDE = "Una extensa llanura del Puerto de las Brumas, cubierta de juncos pálidos, donde a menudo se pueden ver Pinzones esmeralda deslizándose entre los tallos ondulantes.",
          TextMapId = "MESSAGE_LOADING_103_PC"
        },
        MESSAGE_LOADING_104_PC = {
          ContentDE = "Un gran gremio mercantil establecido en las llanuras del Puerto de las Brumas, que actúa como asociación profesional de los Tejestrellas.\nSe alza al pie de un árbol colosal, coronada por un dispositivo circular semejante a una luna resplandeciente, impulsado por la combustión de incienso.",
          TextMapId = "MESSAGE_LOADING_104_PC"
        },
        MESSAGE_LOADING_105_PC = {
          ContentDE = "Una caverna costera situada al oeste de las llanuras del Puerto de las Brumas. El estruendo incesante de las olas resuena allí sin cesar, dando origen al nombre de Caverna de Mareas.",
          TextMapId = "MESSAGE_LOADING_105_PC"
        },
        MESSAGE_LOADING_106_PC = {
          ContentDE = "El mercado negro del Puerto de las Brumas, oculto en una costa occidental cubierta de naufragios.\nProtegido por el relieve natural y abandonado por la población, el lugar atrajo a mercaderes sin escrúpulos, convirtiéndose en un centro de intercambios ilícitos.",
          TextMapId = "MESSAGE_LOADING_106_PC"
        },
        MESSAGE_LOADING_107_PC = {
          ContentDE = "Vestigios del antiguo campo de batalla de la Batalla de Shuli, situado al noroeste del Puerto de las Brumas, aislado en plena mar.\nAntes del conflicto, la isla servía como un importante centro de investigación para la Secta Jishu. Aunque la mayoría de los mecanismos fueron destruidos durante la guerra, algunos aún conservan su estructura intacta y siguen funcionando.",
          TextMapId = "MESSAGE_LOADING_107_PC"
        },
        MESSAGE_LOADING_108_PC = {
          ContentDE = "Altiplano situado al noroeste del Puerto de las Brumas. Bajo el efecto de las fugas de poder de Zhuyin, el suelo está ahora cubierto por una vasta extensión de Polvo corrompido, estéril y desolado. La vegetación cristalizada y las rocas desgarradas le dieron a este lugar el nombre de Mar de Polvo.",
          TextMapId = "MESSAGE_LOADING_108_PC"
        },
        MESSAGE_LOADING_109_PC = {
          ContentDE = "Una vasta llanura del Puerto de las Brumas, invadida por juncos pálidos, donde a menudo se ven Pinzones esmeralda deslizándose entre los tallos ondulantes.",
          TextMapId = "MESSAGE_LOADING_109_PC"
        },
        MESSAGE_LOADING_10_PC = {
          ContentDE = "Una isla aislada, erguida sobre alta mar en la frontera entre Hiperbórea y Elysium. Los Elysianos construyeron allí un santuario hace un milenio, pero ahora solo las ruinas susurran su antigua gloria.",
          TextMapId = "MESSAGE_LOADING_10_PC"
        },
        MESSAGE_LOADING_110_PC = {
          ContentDE = "Una isla situada en el corazón del lago central del Puerto de las Brumas, tranquila y profunda, rodeada de una vegetación exuberante. Se rumorea que los Wishen han elegido esta isla como su morada.",
          TextMapId = "MESSAGE_LOADING_110_PC"
        },
        MESSAGE_LOADING_111_PC = {
          ContentDE = "La clínica ancestral del linaje Fu, transmitida de generación en generación entre los Zhuyou. Situada en un huerto de albaricoqueros al norte del Puerto de las Brumas, sigue siendo un lugar al que se acude en busca de remedio y salvación.",
          TextMapId = "MESSAGE_LOADING_111_PC"
        },
        MESSAGE_LOADING_112_PC = {
