          TextMapId = "MESSAGE_LOADING_112_PC"
        },
        MESSAGE_LOADING_113_PC = {
          ContentDE = "Un dominio singular nacido de la corrupción del Manantial de Yu por el Azote de Zhuyin. En la Grieta del Olvido, las almas pierden poco a poco todo vínculo con el mundo presente, vagando sin jamás encontrar su camino.",
          TextMapId = "MESSAGE_LOADING_113_PC"
        },
        MESSAGE_LOADING_114_PC = {
