        Mon_DesDetail_10001001 = {
          ContentDE = "En Huaxu, algunas personas del Clan Dragón han sellado un pacto con los Nueve Capítulos de Dafeng, convirtiéndose en Guardias de Yingtian, protectores del reino. Reforzados por el Mandato del Cielo, castigan a los malvados en su nombre. Para muchos son héroes imponentes; para otros, una pesadilla viva.\nComo ocurrió con los Bi’an Sable, varios Guardias sucumbieron a la locura bajo la influencia del Flagelo de Zhuyin, y sus ataques ahora ponen en peligro a la población.",
          TextMapId = "Mon_DesDetail_10001001"
        },
        Mon_DesDetail_10002001 = {
          ContentDE = "Los verdugos superiores de Huaxu. En Huaxu, algunas personas del Clan Dragón han sellado un pacto con los Nueve Capítulos de Dafeng, convirtiéndose en Magistrados de Yingtian. Reforzados por el Mandato del Cielo, castigan a los malvados en su nombre. Para muchos son héroes imponentes; para otros, una pesadilla viva.",
          TextMapId = "Mon_DesDetail_10002001"
        },
        Mon_DesDetail_10003001 = {
          ContentDE = "En otro tiempo fueron guardianes de Huaxu, pero ahora deambulan fuera de control, similares a los Bi’an, aunque cubiertos de negro de la cabeza a la cola. Aparecieron junto al Flagelo de Zhuyin, con la mente velada y violenta, convirtiéndose en una amenaza constante para la vida cotidiana de Huaxu.\nAlgunos eruditos sospechan que, en realidad, podrían ser Filthoids.",
          TextMapId = "Mon_DesDetail_10003001"
        },
        Mon_DesDetail_10004001 = {
          ContentDE = "Guardianes de Huaxu y ejecutores de la voluntad de los Nueve Capítulos de Dafeng. Surgen de los vientos cortantes para castigar a quienes quebrantan los edictos sagrados de los Nueve Capítulos de Dafeng.\nAlgunos eruditos sospechan que, en realidad, podrían ser Filthoids.",
          TextMapId = "Mon_DesDetail_10004001"
        },
        Mon_DesDetail_10005001 = {
          ContentDE = "En Huaxu, algunas personas del Clan Dragón han sellado un pacto con los Nueve Capítulos de Dafeng, convirtiéndose en Guardias de Yingtian, protectores del reino. Reforzados por el Mandato del Cielo, castigan a los malvados en su nombre. Para muchos son héroes imponentes; para otros, una pesadilla viva.\nComo ocurrió con los Bi’an Sable, varios Guardias sucumbieron a la locura bajo la influencia del Flagelo de Zhuyin, y sus ataques ahora ponen en peligro a la población.",
          TextMapId = "Mon_DesDetail_10005001"
        },
        Mon_DesDetail_115 = {
          ContentDE = "En su carácter de soldados de élite, los Halcones Patrullas dirigen a las tropas regulares y transmiten las señales de alarma cuando detectan intrusos aproximándose.",
          TextMapId = "Mon_DesDetail_115"
        },
        Mon_DesDetail_6001001 = {
          ContentDE = "Uno de los Filthoids más comunes. Sobresalen por lanzarse a toda velocidad contra su objetivo y destrozarlo en cuestión de segundos. Sus extremidades especiales le permiten aferrarse sin esfuerzo a muros y techos. Sus fauces y garras implacables, fueron consideradas una amenaza significativa para los viajeros. Si el aullido de un lobo da tiempo para poder escapar, el rugido ronco de un Filthoid solo es el aviso de una muerte anunciada para quienes van desarmados.",
          TextMapId = "Mon_DesDetail_6001001"
        },
        Mon_DesDetail_6002001 = {
          ContentDE = "Uno de los Filthoids más comunes. Sobresalen por la supresión a distancia. En lugar de munición convencional, disparan fragmentos de materia inorgánica dura desde sus brazos con forma de arma. Nadie comprende del todo el origen de su mutación, pero su adaptación a la era contemporánea es evidente.",
          TextMapId = "Mon_DesDetail_6002001"
        },
        Mon_DesDetail_6003001 = {
          ContentDE = "Uno de los Filthoids más comunes. Sobresalen por el apoyo a distancia. Suelen flotar en el aire y, Con sus tentáculos delgados y flexibles, han hecho que más de uno los considere, equivocadamente, “adorables”. Algunos audaces aventureros culinarios incluso intentaron convertirlos en manjares… normalmente pagando un alto precio por tal imprudencia.",
          TextMapId = "Mon_DesDetail_6003001"
        },
        Mon_DesDetail_6004001 = {
          ContentDE = "Uno de los Filthoids grandes más comunes. Sobresalen por destruir objetivos usando la fuerza bruta de su propio cuerpo. Aunque aparentan ser lentos y adorables, esconden un poder destructivo capaz de perforar las armaduras de última generación.",
          TextMapId = "Mon_DesDetail_6004001"
        },
        Mon_DesDetail_6005001 = {
          ContentDE = "Uno de los Filthoids más comunes. Sobresalen por perturbar a distancia. Estas criaturas se camuflan con capas rígidas, semejantes a pétalos endurecidos, y utilizan secreciones pegajosas y corrosivas. Acechan desde la distancia, tejiendo una pesadilla persistente de la que sus víctimas no pueden librarse ni escapar.",
          TextMapId = "Mon_DesDetail_6005001"
        },
        Mon_DesDetail_6006001 = {
          ContentDE = "Uno de los Filthoids más comunes. Sobresalen por recolectar objetos. A menudo se les confunde con los Filthoids Flotantes mutados. Estas criaturas deambulan libremente, engullendo todo lo que desean. Nadie sabe si son esclavos de su hambre fantasmal e insaciable, o si solo reproducen la gula inherente en toda criatura viva.",
          TextMapId = "Mon_DesDetail_6006001"
        },
        Mon_DesDetail_6007001 = {
          ContentDE = "Uno de los Filthoids más comunes. Sobresalen por contener enemigos. Es posible que en el pasado fueran unos titanes del pensamiento, capaces de plasmar ideas brillantes sobre la página… no de convertir sus “inspiraciones” en llamas reales.",
          TextMapId = "Mon_DesDetail_6007001"
        },
        Mon_DesDetail_6011001 = {
          ContentDE = "Uno de los Filthoids mutantes más comunes. Sobresalen por lanzarse a toda velocidad contra su objetivo y destrozarlo en cuestión de segundos. Sus extremidades especiales le permiten aferrarse sin esfuerzo a muros y techos. Sus fauces y garras implacables, fueron consideradas una amenaza significativa para los viajeros. Si el aullido de un lobo da tiempo para poder escapar, el rugido ronco de un Filthoid solo es el aviso de una muerte anunciada para quienes van desarmados.",
          TextMapId = "Mon_DesDetail_6011001"
        },
        Mon_DesDetail_6012001 = {
          ContentDE = "Uno de los Filthoids mutantes más comunes. Sobresalen por la supresión a distancia. En lugar de munición convencional, disparan fragmentos de materia inorgánica dura desde sus brazos con forma de arma. Nadie comprende del todo el origen de su mutación, pero su adaptación a la era contemporánea es evidente.",
          TextMapId = "Mon_DesDetail_6012001"
        },
        Mon_DesDetail_6013001 = {
          ContentDE = "Uno de los Filthoids mutantes más comunes. Sobresalen por la supresión a distancia. Suelen flotar en el aire y, Con sus tentáculos delgados y flexibles, han hecho que más de uno los considere, equivocadamente, “adorables”. Algunos audaces aventureros culinarios incluso intentaron convertirlos en manjares… normalmente pagando un alto precio por tal imprudencia.",
          TextMapId = "Mon_DesDetail_6013001"
        },
        Mon_DesDetail_6014001 = {
          ContentDE = "Los Filthoids grandes mutados más comunes. Sobresalen por destruir objetivos usando la fuerza bruta de su propio cuerpo. Aunque aparentan ser lentos y adorables, esconden un poder destructivo capaz de perforar las armaduras de última generación.",
          TextMapId = "Mon_DesDetail_6014001"
        },
        Mon_DesDetail_6015001 = {
          ContentDE = "Es un tipo de Filthoid Quemaalmas, mutado por el aire impregnado de Incienso en Huaxu. Son especialistas en estorbar y contener. A veces, los transeúntes los confunden con unas inocentes plantas aromáticas. Algunas criaturas tocadas por el Flagelo de Zhuyin, lograron escapar de los designios de los Nueve Capítulos de Dafeng y se transformaron en calamidades peligrosas.",
          TextMapId = "Mon_DesDetail_6015001"
        },
        Mon_DesDetail_6016001 = {
          ContentDE = "Es un tipo de Filthoid Guerrillero, mutado por el aire impregnado de Incienso en Huaxu. Sobresalen por la supresión a distancia. De las grietas en sus antebrazos osificados brotan ramas delgadas rematadas por pequeños capullos. Esto les da a sus proyectiles un inquietante perfume. \nAlgunas criaturas tocadas por el Flagelo de Zhuyin, lograron escapar de los designios de los Nueve Capítulos de Dafeng y se transformaron en calamidades peligrosas.",
          TextMapId = "Mon_DesDetail_6016001"
        },
        Mon_DesDetail_6017001 = {
          ContentDE = "Es un tipo de Filthoid Veloz, mutado por el aire impregnado de Incienso en Huaxu. Su cabeza se ha transformado en una enorme estructura semejante a un estigma, capaz de engullir y desgarrar presas enteras. Algunas criaturas tocadas por el Flagelo de Zhuyin, lograron escapar de los designios de los Nueve Capítulos de Dafeng y se transformaron en calamidades peligrosas. Sus extremidades especiales le permiten aferrarse sin esfuerzo a muros y techos. Sus fauces y garras implacables, fueron consideradas una amenaza significativa para los viajeros.",
          TextMapId = "Mon_DesDetail_6017001"
        },
        Mon_DesDetail_7001001 = {
          ContentDE = "Los francotiradores estándar de las Legiones de Hiperbórea. Sobresalen por la supresión a distancia. Brindan apoyo de fuego a distancia a sus alianzas. Las francotiradoras constituyen la mayoría de la Legión. Brindan apoyo de fuego a distancia con una resistencia, vigilancia y estabilidad notables. Sus camuflajes a medida no solo les permiten ocultarse con eficacia, también son distintivo de su destreza extraordinaria.",
          TextMapId = "Mon_DesDetail_7001001"
        },
        Mon_DesDetail_7001005 = {
          ContentDE = "El objetivo de este encargo.\nPueden entrar en el estado de Sigilo, lo que dificulta que los enemigos los detecten. Cuando sus PV son bajos, pueden invocar señuelos para confundir a sus oponentes.",
          TextMapId = "Mon_DesDetail_7001005"
        },
        Mon_DesDetail_7002001 = {
          ContentDE = "Las tropas de asalto estándar de las Legiones de Hiperbórea. Sobresalen por el combate cuerpo a cuerpo. Reconocibles por los grabados distintivos en su coraza, empuñan sus imponentes espadas con destreza, destruyendo todo lo que se interpone en su camino.",
          TextMapId = "Mon_DesDetail_7002001"
        },
        Mon_DesDetail_7002005 = {
          ContentDE = [[
El objetivo de este encargo.
Pueden utilizar robots como ayuda durante el combate.]],
          TextMapId = "Mon_DesDetail_7002005"
        },
        Mon_DesDetail_7003001 = {
          ContentDE = "Las tropas exploradoras estándar de las Legiones de Hiperbórea. Competentes en distintos rangos de combate, portan armaduras pesadas fabricadas a medida ofrecen una protección formidable y un soporte vital en entornos hostiles. Se rumorea que estas tropas aparecen incluso en las zonas más remotas del Imperio.",
          TextMapId = "Mon_DesDetail_7003001"
        },
        Mon_DesDetail_7003005 = {
          ContentDE = "El objetivo de este encargo.\nEl objetivo de este encargo. Pueden dejar minas terrestres para entorpecer a los enemigos mientras huyen de la persecución.",
          TextMapId = "Mon_DesDetail_7003005"
        },
        Mon_DesDetail_7004001 = {
          ContentDE = "Las tropas de asalto estándar de las Legiones de Hiperbórea, guardianes en la vanguardia. Sobresalen por el reconocimiento cercano y en la defensa contra ataques enemigos. Sus pesados escudos, un emblema que ha perdurado por siglos, es símbolo de su rol en la vanguardia.",
          TextMapId = "Mon_DesDetail_7004001"
        },
        Mon_DesDetail_7006001 = {
          ContentDE = "Los dispositivos de apoyo estándar de las Legiones de Hiperbórea. Son capaces de flotar alrededor del campo de batalla y curar a los soldados heridos. Su diseño modular les permite operar de forma lógica y autónoma. Su uso generalizado confirma uno de los principios fundamentales de la Academia de Alquimia: incluso los procesos repetitivos y tediosos pueden dar lugar a unos milagros extraordinarios.",
          TextMapId = "Mon_DesDetail_7006001"
        },
        Mon_DesDetail_7007001 = {
          ContentDE = "Los dispositivos de apoyo estándar de las Legiones de Hiperbórea. Son capaces de detener y restringir brevemente a los enemigos. Su diseño modular les permite operar de forma lógica y autónoma. Su uso generalizado confirma uno de los principios fundamentales de la Academia de Alquimia: incluso los procesos repetitivos y tediosos pueden dar lugar a unos milagros extraordinarios.",
          TextMapId = "Mon_DesDetail_7007001"
        },
        Mon_DesDetail_7007002 = {
          ContentDE = "Estos dispositivos pueden detener y suprimir a los enemigos por un momento. Su diseño modular les permite operar de forma lógica y autónoma. Su uso generalizado confirma uno de los principios fundamentales de la Academia de Alquimia: incluso los procesos repetitivos y tediosos pueden dar lugar a unos milagros extraordinarios.",
          TextMapId = "Mon_DesDetail_7007002"
        },
        Mon_DesDetail_7008001 = {
          ContentDE = "Los comandantes estándar de las Legiones de Hiperbórea. Diestros tanto en el combate individual como en el liderazgo estratégico. Han demostrado un talento excepcional en batalla, investigación o mando. Sus armas hechas a medida, versátiles en varios rangos, reflejan su habilidad y su posición. Aunque sus habilidades varían, su lealtad al Imperio se mantiene inquebrantable.",
          TextMapId = "Mon_DesDetail_7008001"
        },
        Mon_DesDetail_7009001 = {
          ContentDE = "Los soldados mejorados estándar de las Legiones de Hiperbórea. Sobresalen por romper las líneas enemigas con su eficiencia despiadada. Visten el armamento más avanzado del Imperio, otorgado por la gracia inagotable del Emperador, con el cual penetran las defensas más resistentes. No hay campo de batalla demasiado adverso ni sacrificio demasiado grande: siempre se abrirán paso hacia otra victoria por la gloria del Imperio.",
          TextMapId = "Mon_DesDetail_7009001"
        },
        Mon_DesDetail_7010001 = {
          ContentDE = "Los Alquimistas Spathatoi se despliegan con las Legiones de Hiperbórea. Aparte de su usar su magia en la batalla, ayudan a mantener el armamento, atender a los heridos y forjar las armas más mortíferas. Son el aceite del engranaje de la máquina que es la conquista imperial, asegurando que su motor jamás se detenga.",
          TextMapId = "Mon_DesDetail_7010001"
        },
        Mon_DesDetail_7011001 = {
          ContentDE = "Los francotiradores especializados de las Legiones de Hiperbórea. Sobresalen por la supresión a distancia. Brindan apoyo de fuego a distancia a sus alianzas. Las francotiradoras constituyen la mayoría de la Legión. Brindan apoyo de fuego a distancia con una resistencia, vigilancia y estabilidad notables. Sus camuflajes a medida no solo les permiten ocultarse con eficacia, también son distintivo de su destreza extraordinaria.",
          TextMapId = "Mon_DesDetail_7011001"
        },
        Mon_DesDetail_7012001 = {
          ContentDE = "Las tropas de asalto especializadas de las Legiones de Hiperbórea. Sobresalen por el combate cuerpo a cuerpo. Reconocibles por los grabados distintivos en su coraza, empuñan sus imponentes espadas con destreza, destruyendo todo lo que se interpone en su camino.",
          TextMapId = "Mon_DesDetail_7012001"
        },
        Mon_DesDetail_7013001 = {
          ContentDE = "Las tropas exploradoras especializadas de las Legiones de Hiperbórea. Competentes en distintos rangos de combate, portan armaduras pesadas fabricadas a medida ofrecen una protección formidable y un soporte vital en entornos hostiles. Se rumorea que estas tropas aparecen incluso en las zonas más remotas del Imperio.",
          TextMapId = "Mon_DesDetail_7013001"
        },
        Mon_DesDetail_7014001 = {
          ContentDE = "Las tropas de asalto especializadas de las Legiones de Hiperbórea, guardianes en la vanguardia. Sobresalen por el reconocimiento cercano y en la defensa contra ataques enemigos. Sobresalen por el reconocimiento cercano y en la defensa contra ataques enemigos. Sus pesados escudos, un emblema que ha perdurado por siglos, es símbolo de su rol en la vanguardia.",
          TextMapId = "Mon_DesDetail_7014001"
        },
        Mon_DesDetail_7015001 = {
          ContentDE = "Son dispositivos de apoyo estándar diseñados para contener a los enemigos Son una variante mejorada de los Drones magnéticos, basados en el Filthoid Quemaalmas, que tiene un diseño modular que les permite operar de forma lógica y autónoma. Su uso generalizado confirma uno de los principios fundamentales de la Academia de Alquimia: incluso los procesos repetitivos y tediosos pueden dar lugar a unos milagros extraordinarios.",
          TextMapId = "Mon_DesDetail_7015001"
        },
        Mon_DesDetail_7016001 = {
          ContentDE = "La aeronave estándar de las Legiones de Hiperbórea. Los avances pioneros en ingeniería militar dieron paso a una nueva era de armamento no convencional. Diseñado por la Aeolipile, el Ojo de la Legión simboliza la determinación del Imperio por dominar los cielos.",
          TextMapId = "Mon_DesDetail_7016001"
        },
        Mon_DesDetail_7018001 = {
          ContentDE = "Agente del orden de la Estación de las Cien Flores. Para no alarmar a los pasajeros, no lleva armas equipadas. Pero los guanteletes forjados en acero son igual de letales. Un solo puñetazo basta para hacer chillar incluso a un soldado bien entrenado.",
          TextMapId = "Mon_DesDetail_7018001"
        },
        Mon_DesDetail_7019001 = {
          ContentDE = "Agente del orden de la Estación de las Cien Flores. Su uniforme reglamentario rojo es vistoso y fácil de identificar. Si te pierdes en la estación, puedes pedirles ayuda. Pero si intentas robar o causar problemas mayores, no dudarán en abrir fuego con sus armas cortas.",
          TextMapId = "Mon_DesDetail_7019001"
        },
        Mon_DesDetail_8001001 = {
          ContentDE = "Los artilleros estándar de la Iglesia Elysiana. Sobresalen por la supresión a distancia. Sobresalen por la supresión a distancia, y prefieren enfrentarse sus enemigos, de forma ordenada y precisa, antes que ocultarse en las sombras para disparar. Forman fila, abriendo fuego bajo las órdenes de su líder, entregando su propia carne y sangre a Dios mientras ejecutan Su justicia.",
          TextMapId = "Mon_DesDetail_8001001"
        },
        Mon_DesDetail_8002001 = {
          ContentDE = "Las tropas de asalto estándar de la Iglesia Elysiana. Sobresalen por el combate cuerpo a cuerpo, empuñan unas espadas de plata para desatar la ira divina a corta distancia. Visten cotas de malla bendita, cuya protección parece reforzada por la fuerza misma de su fe. Algunos alquimistas intentaron descifrar el misterio de su resistencia extraordinaria… pero descubrieron que estaban hechos de hierro común.",
          TextMapId = "Mon_DesDetail_8002001"
        },
        Mon_DesDetail_8003001 = {
          ContentDE = "Los sacerdotes estándar de la Iglesia Elysiana. Sobresalen por el apoyo a distancia. Los versos que recitan sin cesar envuelven el campo de batalla cuando resuenan a través de sus máscaras, inspirando a los fieles de Elysium. Se dice que hasta un mudo podría ser escuchado por Dios al usar estas máscaras, siempre que su fe sea lo suficientemente férrea.",
          TextMapId = "Mon_DesDetail_8003001"
        },
        Mon_DesDetail_8500001 = {
          ContentDE = "La Comandante de la 13.ª Legión del Imperio. Una fuerza imponente, movida por motivos desconocidos y una determinación implacable por Berenica.",
          TextMapId = "Mon_DesDetail_8500001"
        },
        Mon_DesDetail_8501001 = {
          ContentDE = "Cuenta con una resistencia extraordinaria, y ha sobrevivido a incontables batallas y heridas letales. Lejos de ser doblegado, cada cicatriz y cada corte recibido solo han fortalecido su poder, y lo han vuelto una máquina de matar.",
          TextMapId = "Mon_DesDetail_8501001"
        },
        Mon_DesDetail_8502001 = {
          ContentDE = "La semilla que cayó en tierra helada y echó raíces en la fría oscuridad de la noche.",
          TextMapId = "Mon_DesDetail_8502001"
        },
        Mon_DesDetail_8503001 = {
          ContentDE = "Un Filthoid colosal que acecha en las profundidades de la Mina de Glevum, y cuyo cuerpo mecánico solo se mueve para excavar y devorar cualquier cosa que brille.",
          TextMapId = "Mon_DesDetail_8503001"
        },
        Mon_DesDetail_8505001 = {
          ContentDE = "La Carcelera de la Prisión Militar Imperial, que agita sus cadenas para castigar el mal y que enciende sus llamas para defender lo que es justo.",
          TextMapId = "Mon_DesDetail_8505001"
        },
        Mon_DesDetail_8509001 = {
          ContentDE = "El paño escarlata ondea mientras la brisa helada entona un lamento del Yermo Nevado.",
          TextMapId = "Mon_DesDetail_8509001"
        },
        Mon_DesDetail_8510001 = {
          ContentDE = "Ley nacida del corazón. Las arenas tapan el cielo con su manto de oscuridad.",
          TextMapId = "Mon_DesDetail_8510001"
        },
        Mon_DesDetail_8511001 = {
          ContentDE = "Ley guiada por la razón. Una luz fría que atraviesa los incontables reinos.",
          TextMapId = "Mon_DesDetail_8511001"
        },
        Mon_DesDetail_8512001 = {
          ContentDE = "Es la Bestia del Campo de Nieve, que arrasa con los hogares de los niños y acaba con los sueños de las hadas.",
          TextMapId = "Mon_DesDetail_8512001"
        },
        Mon_DesDetail_8513001 = {
          ContentDE = "Para implorar por la misericordia divina, los Heraldo Divinos graban palabras sagradas en su piel. A la luz de la fe, el sufrimiento se vuelve gracia.",
          TextMapId = "Mon_DesDetail_8513001"
        },
        Mon_DesDetail_8514001 = {
          ContentDE = "Para algunos Heraldos Divinos, predicar la verdad y purificar la fe es un llamado sagrado. Incluso el fuego y el plomo, cuando se empuñan con devoción, se convierten en extensiones de la gracia divina.",
          TextMapId = "Mon_DesDetail_8514001"
        },
        Mon_DesDetail_8515001 = {
          ContentDE = "El Devorador no es un solo Filthoid, sino una amalgama grotesca: una masa retorcida de carne fusionada que consume animales, plantas, Filthoids e incluso humanos. Con fuerza bruta, une todo esto en un cuerpo deformado y siempre creciente, y deambula hambriento por la próxima presa que se le unirá.",
          TextMapId = "Mon_DesDetail_8515001"
        },
        Mon_DesDetail_8518001 = {
          ContentDE = "Forjado con un armazón de bronce oscuro, sus mecanismos ocultan un filo letal.\nCon un poder que ruge como mil truenos, estremece los cielos y la tierra.",
          TextMapId = "Mon_DesDetail_8518001"
        },
        Mon_DesDetail_8519001 = {
          ContentDE = "Cañón de Phoxichor montado en la locomotora.\nCalibre 210 mm. Cañón de ánima lisa con gran capacidad perforante.\nEn combinación con las demás armas del tren, puede eliminar a cualquier enemigo dentro del campo de visión.",
          TextMapId = "Mon_DesDetail_8519001"
        },
        Mon_DesDetail_8521001 = {
          ContentDE = "Misterioso miembro de Los Abandonados que manipuló al personal de la Estación de las Cien Flores y planeó el atentado con explosivos.",
          TextMapId = "Mon_DesDetail_8521001"
        },
        Mon_DesDetail_9001001 = {
          ContentDE = "Un miembro de Los Abandonados, con el grado de \"Enjambre Salvaje\". Sobresalen por el combate cuerpo a cuerpo. Gente común de Charon convertida en guerreros; sus técnicas carecen de refinamiento, pero su furia, templada en la sangre de los suyos, es el filo que rompe cadenas y deshace hasta el golpe más contundente del enemigo.",
          TextMapId = "Mon_DesDetail_9001001"
        },
        Mon_DesDetail_9002001 = {
          ContentDE = "Un miembro de Los Abandonados, con el grado de \"Enjambre Salvaje\". Sobresalen por la supresión a distancia. Son capaces de suprimir a larga distancia y hostigar. Quienes se atrevan a cruzar su territorio no solo se enfrentarán a unas miradas frías, sino a una lluvia de flechas, golpeando allí donde la vigilancia flaquea.",
          TextMapId = "Mon_DesDetail_9002001"
        },
        Mon_DesDetail_9003001 = {
          ContentDE = "Un miembro de Los Abandonados, con el grado de \"El Cuervo\". Son expertos en alterar el entorno y en tender trampas. Para estos \"Jugueteros\", la vida es un juego, una carrera letal contra la destrucción, sin importar que sus vidas estén en juego. Transforman el campo de batalla en su “patio de juegos”, sembrando trampas por doquier y observando a los combatientes, de los cuales solo unos pocos pueden escapar. Suelen colaborar con los Engañadores y los Bombadictos en sus ofensivas.",
          TextMapId = "Mon_DesDetail_9003001"
        },
        Mon_DesDetail_9005001 = {
          ContentDE = "Un miembro de Los Abandonados, con el grado de \"El Cuervo\". Altamente diestros en manipular explosivos. Estos Bombadictos, obsesionados con la perfección, ajustan cada bomba hasta el instante previo a su detonación. Esa compulsión explica por qué sus artefactos suelen ser más vulnerables justo antes de su violenta explosión. Suelen colaborar con los \"Engañadores\" y los \"Jugueteros\" en sus ofensivas.",
          TextMapId = "Mon_DesDetail_9005001"
        },
        Mon_DesDetail_9006001 = {
          ContentDE = "Un miembro de Los Abandonados, con el grado de \"El Cuervo\". Son expertos en desordenar formaciones y sembrar caos en el campo de batalla. Los llamados \"Engañadores\" son maestros de la manipulación y el engaño. Explotan la desinformación para enfrentar a los enemigos entre sí, alimentando el caos con cada movimiento. Se deleitan con el caos que causan, con una sonrisa burlona que a menudo les cuesta la vida… y la de otros. Suelen colaborar con los \"Bombadictos\" y los \"Jugueteros\" en sus ofensivas.",
          TextMapId = "Mon_DesDetail_9006001"
        },
        Mon_DesDetail_9007001 = {
          ContentDE = "Un miembro de Los Abandonados, con el grado de \"Enjambre Salvaje\". Sobresalen por el apoyo a distancia. Ninguna operación de Los Abandonados se lleva a cabo sin las órdenes de estos agentes, que susurran como fantasmas, y que regresan con información del campo de batalla, como si de halcones mensajeros se tratara. Se mueven por los callejones más oscuros del Imperio, tejiendo una red invisible de murmullos que conecta a todos los Abandonados.",
          TextMapId = "Mon_DesDetail_9007001"
        },
        Mon_DesDetail_9500001 = {
          ContentDE = "¡Un bandido maestro, infame y escurridizo!",
          TextMapId = "Mon_DesDetail_9500001"
        },
        Mon_DesDetail_9501001 = {
          ContentDE = "Ese joven sospechoso de adelante es el ladrón que robó la bolsa de Margie. ¡Ve y atrápalo ahora!",
          TextMapId = "Mon_DesDetail_9501001"
        },
        Mon_DesDetail_9801001 = {
          ContentDE = "La subespecie norteña de los lobos salvajes ha adaptado su cuerpo a los páramos helados, con un pelaje invernal pálido y extremidades alargadas. Cuando veas “montículos de nieve moviéndose” en plena naturaleza, sabrás que ya estás rodeado por estos depredadores únicos.",
          TextMapId = "Mon_DesDetail_9801001"
        },
        Mon_DesDetail_9802001 = {
          ContentDE = "Una especie ancestral y escasa; las leyendas cuentan que estas criaturas han visto pasar eras enteras con la serenidad de su mirada. Sus astas, teñidas con la sangre de guerras olvidadas, cargan el peso de continentes que nacieron y cayeron.",
          TextMapId = "Mon_DesDetail_9802001"
        },
        Mon_DesDetail_9803001 = {
          ContentDE = "Estos roedores se adaptan y mutan más rápido de lo que las ciudades son capaces de olvidar. Prosperan en los rincones oscuros del mundo urbano, royendo los secretos que escondemos bajo el concreto.",
          TextMapId = "Mon_DesDetail_9803001"
        },
        Mon_DesDetail_9804001 = {
          ContentDE = "Un ave cantora común de Huaxu, de canto suave y figura redonda. Suele verse saltando entre las ramas o correteando por el suelo. Los habitantes locales adoran estos aves profundamente.",
          TextMapId = "Mon_DesDetail_9804001"
        },
        Mon_DesDetail_9805001 = {
          ContentDE = "Un ave acuática exclusiva de Huaxu, reconocible por las largas plumas que adornan su cabeza. Se alimenta de peces, cazando inmóvil sobre una sola pata en los bajíos, asestando un picotazo en el instante en que la presa se acerca demasiado. Su nombre proviene de su parecido con un pescador esperando el tirón de su caña.",
          TextMapId = "Mon_DesDetail_9805001"
        },
        Mon_DesDetail_9806001 = {
          ContentDE = "Un ave terrestre que solo existe en Huaxu. Aunque sus alas son demasiado cortas para un vuelo prolongado, puede planear distancias sorprendentes. En la temporada adecuada, los machos despliegan la cola en un gesto de cortejo… aunque ambos sexos comparten el mismo y vívido plumaje esmeralda.",
          TextMapId = "Mon_DesDetail_9806001"
        },
        Mon_DesDetail_9807001 = {
          ContentDE = "Un pequeño jabalí salvaje, llamado así por su cuerpo compacto. Su carne es tierna y suave, sin el sabor fuerte típico de los jabalíes grandes. Es un manjar con el que los habitantes de Huaxu honran a sus invitados.",
          TextMapId = "Mon_DesDetail_9807001"
        },
        Mon_DesDetail_9808001 = {
          ContentDE = "Si oyes un largo “yip...yaaah” después del anochecer, en Huaxu, casi con certeza es un zorro. Los cuidadores de gallinas salen a revisar sus gallineros; los cazadores se internan en la oscuridad. Pero los zorros son maestros del engaño y la distracción… atraparlos nunca es seguro.",
          TextMapId = "Mon_DesDetail_9808001"
        },
        Mon_DesDetail_9809001 = {
          ContentDE = "Un ciervo de gran tamaño que solo habita en Huaxu, a menudo visto recorriendo llanuras y laderas boscosas. La melena suave como una nube en su cuello le da su nombre. Es dócil por naturaleza… pero mejor no provocarlo, a menos que tus costillas soporten el embate de esos cuernos.",
          TextMapId = "Mon_DesDetail_9809001"
        },
        Mon_DesDetail_9810001 = {
          ContentDE = "Una especie de gaviota que se encuentra con frecuencia en los puertos de Huaxu. De temperamento agresivo, alberga una obsesión incomprensible por las patatas. Aprovechando el viento marino, se lanza a toda velocidad para robar cualquier patata que entre en su campo de visión. Los trabajadores del puerto la apodan irónicamente la “Gaviota-Patata”.",
          TextMapId = "Mon_DesDetail_9810001"
        },
        Mon_DesDetail_AutoChess_1 = {
          ContentDE = "Mecatíteres creados por el Maestro Gongshang e inspirados en unidades de distintas facciones",
          TextMapId = "Mon_DesDetail_AutoChess_1"
        },
        Mon_FirstSeen_Label = {
          ContentDE = "Nuevo enemigo",
          TextMapId = "Mon_FirstSeen_Label"
        },
        Mon_Guide_115_01 = {
          ContentDE = "Los <Highlight>Halcones Patrullas</> son soldados de élite seleccionados de entre las Patrullas. Los Halcones Patrullas vigilan cuando el enemigo se aproxima y bajan su alerta cuando la amenaza se aleja.",
          TextMapId = "Mon_Guide_115_01"
        },
        Mon_Guide_115_02 = {
          ContentDE = "Si un <Highlight>Halcón Patrulla</> permanece en estado de vigilancia por demasiado tiempo, emitirá una <Highlight>alarma</> e iniciará una <Highlight>cuenta regresiva</> de ejecución de rehenes.",
          TextMapId = "Mon_Guide_115_02"
        },
        Mon_Guide_6006001_01 = {
          ContentDE = "Al ser derrotado, el <Highlight>Filthoid Portador</> dejará caer un <Highlight>Módulo de excavación</>, necesario para mantener en funcionamiento la Excavadora.",
          TextMapId = "Mon_Guide_6006001_01"
        }
      }
    end
  },
  {
    MinKey = "Mon_Guide_6007001_01",
    MaxKey = "Mon_Name_6011020",
    Loader = function()
      return {
        Mon_Guide_6007001_01 = {
          ContentDE = "El <Highlight>Filthoid Quemaalmas</> explota al morir, infligiendo daño en área tanto a aliados como a enemigos dentro del rango.",
          TextMapId = "Mon_Guide_6007001_01"
        },
        Mon_Guide_6015001_01 = {
          ContentDE = "El <Highlight>Filthoid Flor de Ceniza</> explota al morir, infligiendo daño en área tanto a aliados como a enemigos dentro del rango.",
          TextMapId = "Mon_Guide_6015001_01"
        },
        Mon_Guide_7001005_01 = {
          ContentDE = "<Highlight>Soldado Francotirador – Sigilo</> entra periódicamente en el modo [Sigilo], aumentando su Velocidad de Movimiento durante #1 s.",
          TextMapId = "Mon_Guide_7001005_01"
        },
        Mon_Guide_7001005_02 = {
          ContentDE = "Cuando el <Highlight>Soldado Francotirador - Sigilo</> recibe daño estando por debajo del 80% de su PV Máx., activa el modo [Sigilo] y invoca varios [Señuelos] idénticos.\n[Señuelos]: Tienen la misma apariencia que <Highlight>Soldado Francotirador - Sigilo</>, pero reciben más daño.\nCuando uno de los [Señuelos] es derrotado, el <Highlight>Soldado Francotirador – Sigilo</> queda afectado por [Ralentización]. \n[Ralentización]: Reduce la Velocidad de Movimiento durante #2 s.",
          TextMapId = "Mon_Guide_7001005_02"
        },
        Mon_Guide_7002005_01 = {
          ContentDE = "Al aparecer en combate, el <Highlight>Soldado Hendedor – Belicoso</> invoca un <Highlight>[Dron curativo]</> y de forma periódica, un <Highlight>[Dron magnético]</> para asistirlo en batalla.",
          TextMapId = "Mon_Guide_7002005_01"
        },
        Mon_Guide_7002005_02 = {
          ContentDE = "<Highlight>Dron curativo</>: Permanece vinculado de manera continua a <Highlight>Soldado Hendedor – Belicoso</>.\nEl objetivo vinculado recibe aumentos de Velocidad de Movimiento y ATQ, además de recuperar sus PV de forma constante.",
          TextMapId = "Mon_Guide_7002005_02"
        },
        Mon_Guide_7002005_03 = {
          ContentDE = "<Highlight>Dron magnético</>: Persigue al objetivo hostil, se autodestruye y luego crea una [Tormenta Magnética] centrada en sí mismo.\n[Tormenta Magnética]: Inflige daño e impone [Ralentización] a los objetivos hostiles dentro del rango. \n[Ralentización]: Reduce la Velocidad de Movimiento durante #1 s. Causa daño e inflige [Parálisis] a los objetivos dentro del rango. \n[Parálisis]: Incapaz de moverse o atacar durante #2 s.",
          TextMapId = "Mon_Guide_7002005_03"
        },
        Mon_Guide_7003005_01 = {
          ContentDE = "<Highlight>Soldado Explorador - Asalto Armado</> coloca periódicamente una [Mina Terrestre] en su posición actual.",
          TextMapId = "Mon_Guide_7003005_01"
        },
        Mon_Guide_7003005_02 = {
          ContentDE = "Las [Minas Terrestres] se activan cuando un enemigo entra en su radio y detonan tras un breve retraso, infligiendo daño y aplicando [Lentitud] a las unidades hostiles cercanas. [Lentitud]: Pierdes Velocidad de Movimiento durante #1 s.",
          TextMapId = "Mon_Guide_7003005_02"
        },
        Mon_Guide_7007002_01 = {
          ContentDE = "Algunos <Highlight>Drones Magnéticos Ⅱ</> se aproximarán a vehículos y se autodestruirán, causando un daño considerable tanto a los vehículos como a otros objetivos hostiles dentro del rango.",
          TextMapId = "Mon_Guide_7007002_01"
        },
        Mon_Guide_7008001_01 = {
          ContentDE = "El Sargento de Élite puede usar <Highlight>Mejora de Moral</> para inspirar a los aliados cercanos.",
          TextMapId = "Mon_Guide_7008001_01"
        },
        Mon_Guide_7008001_02 = {
          ContentDE = "Los aliados inspirados obtienen [Moral Alta]. [Moral Alta]: Aumenta la Velocidad de Movimiento, el daño infligido y reduce el daño recibido.",
          TextMapId = "Mon_Guide_7008001_02"
        },
        Mon_Guide_7008001_03 = {
          ContentDE = "Cuando el Sargento de Élite es <Highlight>derrotado</>, los aliados pierden el efecto de [Moral Alta].",
          TextMapId = "Mon_Guide_7008001_03"
        },
        Mon_Guide_7015001_01 = {
          ContentDE = "El <Highlight>Dron Patrullero</> explota al ser derrotado, infligiendo daño en área a aliados y enemigos dentro del rango.",
          TextMapId = "Mon_Guide_7015001_01"
        },
        Mon_Guide_8501002_01 = {
          ContentDE = "Ferozmente implacables, los <Highlight>Maestro de Batalla</> usan sus habilidades aberrantes para perseguir a sus objetivos una vez iniciado el combate.",
          TextMapId = "Mon_Guide_8501002_01"
        },
        Mon_Guide_8515001_01 = {
          ContentDE = "Cuando el <Highlight>Devorador</> libera <Highlight>Explosión de Esporas</> o <Highlight>Aliento Abrasador</>, apunta a su <Highlight>cabeza brillante</> para \ninmovilizarlo brevemente.",
          TextMapId = "Mon_Guide_8515001_01"
        },
        Mon_Guide_9003001_01 = {
          ContentDE = "Los <Highlight>Jugueteros</> pertenecen a los \"Soldados\" de Los Abandonados. Son expertos en alterar el entorno y en tender trampas.\nEn <Highlight>“Encargo: Mediación”</>, cuando un Juguetero es derrotado, aparecen <Highlight>Plataformas de Rebote</> en la ruta de retirada para facilitar tu escape.",
          TextMapId = "Mon_Guide_9003001_01"
        },
        Mon_Guide_9005001_01 = {
          ContentDE = "Los <Highlight>Bombadictos</> pertenecen a los \"Soldados\" de Los Abandonados. Altamente diestros en manipular explosivos.\nEn <Highlight>“Encargo: Mediación”</>, cuando un Bombadicto es derrotado, los PV Máx. de <Highlight>Destello final</> se reduce en un 30%.",
          TextMapId = "Mon_Guide_9005001_01"
        },
        Mon_Guide_9006001_01 = {
          ContentDE = "Los <Highlight>Engañadores</> pertenecen a los \"Soldados\" de Los Abandonados. Son expertos en desordenar formaciones y sembrar caos en el campo de batalla.\nEn <Highlight>“Encargo: Mediación”</>, cuando un Engañador es derrotado, los enemigos de élite dejan de aparecer.",
          TextMapId = "Mon_Guide_9006001_01"
        },
        Mon_Guide_9500001_01 = {
          ContentDE = "<Highlight>Lunosaqueadora</> aparece por un periodo corto antes de escapar. Derrótala antes de que huya garantiza un botín considerable.",
          TextMapId = "Mon_Guide_9500001_01"
        },
        Mon_Guide_Strong_Blood_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Putrefacción</> crea periódicamente un [Pantano Putrefacto] a su alrededor.",
          TextMapId = "Mon_Guide_Strong_Blood_01"
        },
        Mon_Guide_Strong_Blood_02 = {
          ContentDE = "[Pantano Putrefacto]: Inflige daño periódico a los enemigos dentro de su radio, mientras cura a los aliados adentro.",
          TextMapId = "Mon_Guide_Strong_Blood_02"
        },
        Mon_Guide_Strong_Burst_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Explosión</> desencadena periódicamente una explosión centrada en su propio cuerpo, lanzando por los aires a las unidades hostiles cercanas.",
          TextMapId = "Mon_Guide_Strong_Burst_01"
        },
        Mon_Guide_Strong_Fade_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Marchitar</> libera periódicamente 3 [Rayos Marchitos] que rotan a su alrededor. \n[Rayo Marchito]: Dura 10 s. Orbita alrededor del Comandante, causa daño al contacto y reduce la Cordura del objetivo.",
          TextMapId = "Mon_Guide_Strong_Fade_01"
        },
        Mon_Guide_Strong_Frozen_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\nCuando <Highlight>Comandante – Congelación</> recibe el impacto de un arma a distancia, contraataca lanzando carámbanos hacia el agresor, infligiendo daño y aplicando 1 acumulación de [Ralentización]. \n[Ralentización]: Reduce la Velocidad de Ataque y la Velocidad de Movimiento durante #1 s, hasta #2 acumulaciones.",
          TextMapId = "Mon_Guide_Strong_Frozen_01"
        },
        Mon_Guide_Strong_IceOrb_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Infierno Gélido</> invoca periódicamente un [Infierno Gélido] bajo los objetivos enemigos. \n[Infierno Gélido]: Ralentiza a los blancos dentro de su radio y, luego detona después de #1, infligiendo daño en área a todos los objetivos hostiles cercanos.",
          TextMapId = "Mon_Guide_Strong_IceOrb_01"
        },
        Mon_Guide_Strong_Kamikaze_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Sacrificio</> explota al ser derrotado, infligiendo daño a todos los objetivos hostiles dentro del rango.",
          TextMapId = "Mon_Guide_Strong_Kamikaze_01"
        },
        Mon_Guide_Strong_Multiple_01 = {
          ContentDE = "Algunos Comandantes poseen varias <Highlight>habilidades de Comandante</> al mismo tiempo.",
          TextMapId = "Mon_Guide_Strong_Multiple_01"
        },
        Mon_Guide_Strong_Poison_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Corrosión</> genera de forma periódica un charco de [Veneno] bajo sus pies. \n[Veneno]: Inflige una reducción de DEF del objetivo y causa daño periódico dentro de su zona.\nAdemás, mientras permanezca con vida, <Highlight>Comandante – Corrosión</> acelerará la descomposición del Suero.",
          TextMapId = "Mon_Guide_Strong_Poison_01"
        },
        Mon_Guide_Strong_Reflect_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Destello</> se aplica periódicamente [Destello] a sí mismo. \n[Destello]: Dura #1 s; mientras está activo, recibir daño desencadena una explosión que inflige daño en área a los enemigos dentro del rango.",
          TextMapId = "Mon_Guide_Strong_Reflect_01"
        },
        Mon_Guide_Strong_Revenge_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Venganza</> otorga poder a sus aliados cercanos al morir. \n[Reforzado]: Aumenta el ATQ, la DEF, la Velocidad de Movimiento y la Velocidad de Ataque durante #1 s.",
          TextMapId = "Mon_Guide_Strong_Revenge_01"
        },
        Mon_Guide_Strong_Shield_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Guardián</> invoca periódicamente un [Campo Guardián] a su alrededor. \n[Campo Guardián]: Dura #1 s y bloquea todas las balas y proyectiles hostiles.",
          TextMapId = "Mon_Guide_Strong_Shield_01"
        },
        Mon_Guide_Strong_Threefold_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Fantasma</> invoca #1 [Fantasma(s)] al inicio del combate. \n[Fantasma]: Recibe más daño de lo normal, pero replica las habilidades de combate de su invocador.",
          TextMapId = "Mon_Guide_Strong_Threefold_01"
        },
        Mon_Guide_Strong_ThunderLaser_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Tormenta Eléctrica</> invoca periódicamente [Infiernos de Trueno] a su alrededor. \n[Infierno de Trueno]: Gira sin descanso por el campo, causando daño a cualquier objetivo hostil que toque.",
          TextMapId = "Mon_Guide_Strong_ThunderLaser_01"
        },
        Mon_Guide_Strong_Thunder_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Trueno</> libera periódicamente [Orbes Eléctricos] que se expanden hacia afuera. \n[Orbe Eléctrico]: Descarga electricidad cada #1 s, infligiendo daño a los enemigos cercanos. Desaparece al recibir un ataque.",
          TextMapId = "Mon_Guide_Strong_Thunder_01"
        },
        Mon_Guide_Strong_Vampire_01 = {
          ContentDE = "Los Comandantes son entidades poderosas dentro de las fuerzas hostiles, capaces de emplear habilidades únicas conocidas como las <Highlight>habilidades de Comandante</>.\n<Highlight>Comandante – Baño de Sangre</> restaura sus propios PV cada vez que inflige daño.",
          TextMapId = "Mon_Guide_Strong_Vampire_01"
        },
        Mon_Guide_Title_115 = {
          ContentDE = "Halcón Patrulla",
          TextMapId = "Mon_Guide_Title_115"
        },
