        Mon_Name_AutoChess_9 = {
          ContentDE = "Soldado Hendedor Mecatítere I",
          TextMapId = "Mon_Name_AutoChess_9"
        },
        MonsterRushEvent_Wuyou_DungeonDes01 = {
          ContentDE = "Un Wishen misterioso, espada en mano, aparece de la nada y bloquea tu camino. Tal vez haya sentido tu talento excepcional, porque parece dispuesto a enseñarte uno o dos movimientos. \n“Mira bien... solo lo mostraré una vez.”",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes01"
        },
        MonsterRushEvent_Wuyou_DungeonDes02 = {
          ContentDE = "La luz del sol se filtra entre las hojas. Una brisa acaricia tu cabello. Como si recordara una tarde perdida, el pequeño Wishen suelta un largo bostezo.\n...Espera, ¿los Wishen también bostezan?",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes02"
        },
        MonsterRushEvent_Wuyou_DungeonDes03 = {
          ContentDE = "El diligente espadachín y el perezoso pastor: su discusión continúa sin cesar. Esperemos que no decidan unirse contra ti, {性别:un viajero solitario atrapado|una viajera solitaria atrapada} en su alegre disputa.",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes03"
        },
        MonsterRushEvent_Wuyou_DungeonDes04 = {
          ContentDE = "Una hoja... luego dos... luego tres... Ves cómo el Wishen saca talismán tras talismán de detrás de su espalda, como un mago de escenario sacando infinitas cartas de sus mangas.\n“¡Este no... ni ese... ¡¿Dónde está mi talismán de trueno!?”",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes04"
        },
        MonsterRushEvent_Wuyou_DungeonDes05 = {
          ContentDE = "Sin prisa, un Wishen coloca su sombrero de paja entre tus manos y te pide que lo guardes con cuidado.\nAl siguiente instante, crees ver una figura en traje surgir de su sombra, empuñando un hacha y gritando: “¡¿Quién más quiere probarlo!?”",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes05"
        },
        MonsterRushEvent_Wuyou_DungeonDes06 = {
          ContentDE = "Se dice que los Wishen nacen de deseos no cumplidos. Miras al compañero que flota tranquilamente a tu lado.\n¿Qué deseo persistente, te preguntas, lo mantiene atado a este mundo?",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes06"
        },
        MonsterRushEvent_Wuyou_DungeonDes07 = {
          ContentDE = "Si desvanecerse significa finalmente dejar ir, entonces no existen las despedidas dolorosas en el mundo de los Wishen.\nColoreados con los tonos del alma, estos espíritus caprichosos se reúnen aquí y mañana, como siempre, rebosará de ruido y maravillas.",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes07"
        },
        MonsterRushEvent_Wuyou_DungeonName01 = {
          ContentDE = "La lección del espadachín anónimo",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName01"
        },
        MonsterRushEvent_Wuyou_DungeonName02 = {
          ContentDE = "El bostezo del joven pastor",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName02"
        },
        MonsterRushEvent_Wuyou_DungeonName03 = {
          ContentDE = "Una farsa entretenida",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName03"
        },
        MonsterRushEvent_Wuyou_DungeonName04 = {
          ContentDE = "El mago de los talismanes infinitos",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName04"
        },
        MonsterRushEvent_Wuyou_DungeonName05 = {
          ContentDE = "El maníaco tranquilo",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName05"
        },
        MonsterRushEvent_Wuyou_DungeonName06 = {
          ContentDE = "La prueba de los deseos persistentes",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName06"
        },
        MonsterRushEvent_Wuyou_DungeonName07 = {
          ContentDE = "Un mañana sin preocupaciones",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName07"
        },
        MonsterRushEvent_Wuyou_PetDesc_1 = {
          ContentDE = "Ein Wishen, der zerstörerische Talismane mühelos einsetzt – das eigentliche Rätsel ist allerdings, woher er sie überhaupt hervorzieht.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_1"
        },
        MonsterRushEvent_Wuyou_PetDesc_2 = {
          ContentDE = "Er wirkt ruhig und gefasst – doch wehe dem, der ihn reizt: Die Folgen könnten weit über das Erwartete hinausgehen.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_2"
        },
        MonsterRushEvent_Wuyou_PetDesc_3 = {
          ContentDE = "Ein Meister des Schwertflugs. Seine Klingen treiben und wirbeln mit müheloser Anmut – die perfekte Kulisse für ein Foto, wenn er sie nur ausleihen würde.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_3"
        },
        MonsterRushEvent_Wuyou_PetDesc_4 = {
          ContentDE = "Er gleitet stets mit leichter, unbeschwerter Grazie dahin, und wenn du dich niedergeschlagen fühlst, könnte eine sanfte Berührung von ihm deine Stimmung heben.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_4"
        },
        MonsterRushEvent_Wuyou_PetName_1 = {
          ContentDE = "Talismanführender Wishen",
          TextMapId = "MonsterRushEvent_Wuyou_PetName_1"
        },
        MonsterRushEvent_Wuyou_PetName_2 = {
          ContentDE = "Asketischer Wishen",
          TextMapId = "MonsterRushEvent_Wuyou_PetName_2"
        },
        MonsterRushEvent_Wuyou_PetName_3 = {
          ContentDE = "Klingengetragener Wishen",
          TextMapId = "MonsterRushEvent_Wuyou_PetName_3"
        },
