        PET_412_PASSIVE = {
          ContentDE = "Aumenta el ATQ Hydro para el personaje principal y los Compañeros de combate en #1, y las estadísticas proporcionadas por Cuñas Demoníacas con el prefijo [Fénix] en #2.",
          TextMapId = "PET_412_PASSIVE"
        },
        PET_412_SKILL = {
          ContentDE = "Aumenta el ATQ de todas las [Invocaciones] aliadas en #1 durante #2 s.",
          TextMapId = "PET_412_SKILL"
        },
        PET_413_PASSIVE = {
          ContentDE = "Aumenta el ATQ Pyro para el personaje principal y los Compañeros de combate en #1, y las estadísticas proporcionadas por Cuñas Demoníacas con el prefijo [Fénix] en #2.",
          TextMapId = "PET_413_PASSIVE"
        },
        PET_413_SKILL = {
          ContentDE = "Genera 1 [Sal volátil activada], 1 [Gota de tranquilizante] y 1 [Caja de suministros de munición]. Aumenta la Duración de Habilidad para sí mismo y sus aliados en #1 durante #2 s.",
