        PartyReward_Description_110101 = {
          ContentDE = "Debajo de su cáscara amarga e incomestible se encuentran los granos dulces y ácidos del recuerdo.",
          TextMapId = "PartyReward_Description_110101"
        },
        PartyReward_Description_110102 = {
          ContentDE = "Una pluma rota, teñida con el sabor salado del mar y un leve rastro de sangre: evidencia de la ingenuidad y el coraje de una joven.",
          TextMapId = "PartyReward_Description_110102"
        },
        PartyReward_Description_110103 = {
          ContentDE = "Incluso desde dentro de una jaula, todavía hay quienes miran el horizonte.",
          TextMapId = "PartyReward_Description_110103"
        },
        PartyReward_Description_110104 = {
          ContentDE = "Los fugaces momentos de felicidad se han ido para siempre. Pero afortunadamente siempre hay un mañana.",
          TextMapId = "PartyReward_Description_110104"
        },
        PartyReward_Description_110201 = {
          ContentDE = "La doncella toma un libro de cuentos e intenta narrar una historia para que la princesa pueda quedarse dormida.",
          TextMapId = "PartyReward_Description_110201"
        },
        PartyReward_Description_110202 = {
          ContentDE = "Un broche de rosa, el objeto que Hilda siempre lleva consigo como su tesoro más preciado.",
          TextMapId = "PartyReward_Description_110202"
        },
        PartyReward_Description_110203 = {
          ContentDE = "Un traje blanco para actuar en escena que parece un pájaro de nieve extendiendo las alas hacia el cielo libre.",
          TextMapId = "PartyReward_Description_110203"
        },
        PartyReward_Description_110204 = {
          ContentDE = "Ambas sacrificaron lo más importante por la otra, pero solo obtuvieron un puñado de ilusiones. Pero eso no es el final de la historia.",
          TextMapId = "PartyReward_Description_110204"
        },
        PartyReward_Description_110301 = {
          ContentDE = "Diseñado meticulosamente en tamaño y forma, cubre a la perfección los cuernos cortados, permitiendo que cualquier joven parezca una persona ordinaria.",
          TextMapId = "PartyReward_Description_110301"
        },
        PartyReward_Description_110302 = {
          ContentDE = "Un periodista con grandilocuencia narra la vida legendaria de un rico comerciante, ensalzando su sabiduría, elegancia y generosidad… como si agitara de forma tentadora una pajita dorada ante el mundo.",
          TextMapId = "PartyReward_Description_110302"
        },
        PartyReward_Description_110303 = {
          ContentDE = "El número “47” grabado en el frío metal se ha desgastado hasta volverse casi ilegible, y desde entonces, el verdadero nombre de esta alma permanecerá desconocido para todos.",
          TextMapId = "PartyReward_Description_110303"
        },
        PartyReward_Description_110304 = {
          ContentDE = "Una luz brillante, cálida y a la vez suave llama a los niños para que regresen a casa. Sin embargo, para una bestia perdida en las sombras, esa luz siempre estará fuera de su alcance.",
          TextMapId = "PartyReward_Description_110304"
        },
        PartyReward_Description_150201 = {
          ContentDE = "El líquido carmesí oscuro sobre los fragmentos transparentes se solidificó desde hace mucho tiempo. Alguna vez, fue un milagro que una joven buscó desesperadamente.",
          TextMapId = "PartyReward_Description_150201"
        },
        PartyReward_Description_150202 = {
          ContentDE = "Un pergamino que guarda los sueños inconclusos de un joven y una muchacha. Es un legado, atemporal y puro, que fue confiado a las generaciones futuras.",
          TextMapId = "PartyReward_Description_150202"
        },
        PartyReward_Description_150203 = {
          ContentDE = "Hecha con carne fresca y verduras, esta sopa calentó una vez a un corazón, que había dejado de latir por un momento, en una noche gélida de invierno.",
          TextMapId = "PartyReward_Description_150203"
        },
        PartyReward_Description_150204 = {
          ContentDE = "En este sueño, no hay sufrimiento ni muerte, no hay arrepentimientos ni errores. Solo el sol y el arroyo, a su lado.",
          TextMapId = "PartyReward_Description_150204"
        }
      }
    end
  },
  {
    MinKey = "PartyReward_Description_150301",
