    Loader = function()
      return {
        PartyReward_Description_150301 = {
          ContentDE = "Una espada puede matar — pero también puede cumplir otro propósito.",
          TextMapId = "PartyReward_Description_150301"
        },
        PartyReward_Description_150302 = {
          ContentDE = "Entre sueño y memoria, la errancia permanece libre; entre alegría y tristeza, una sonrisa melancólica ante el mundo.",
          TextMapId = "PartyReward_Description_150302"
        },
        PartyReward_Description_150303 = {
          ContentDE = "El menú amarillento de este puesto está lleno de platos de rara maestría, difíciles de encontrar en otro lugar.",
          TextMapId = "PartyReward_Description_150303"
        },
        PartyReward_Description_150304 = {
          ContentDE = "Una recopilación de relatos a medio camino entre la verdad y la ficción, antaño muy popular. Cuántos pasados atormentados y cuántas hojas cruzadas yacen en sus páginas, nadie podría decirlo.",
          TextMapId = "PartyReward_Description_150304"
        },
        PartyReward_Description_150401 = {
          ContentDE = "Un ave rechoncha de nombre desconocido, del tamaño de medio brazo. Al abrazarla, puedes hundirte en su suave barriga y borrar el cansancio del día.",
          TextMapId = "PartyReward_Description_150401"
        },
        PartyReward_Description_150402 = {
          ContentDE = "Obra esmerada de una joven artesana. El sistema de poleas mejorado y el motor de empuje añadido reducen enormemente el esfuerzo humano, ideal para irse de casa.",
          TextMapId = "PartyReward_Description_150402"
        },
        PartyReward_Description_150403 = {
          ContentDE = "Una carta escondida durante años en el interior de un “Pájaro abrazable”, llena de pliegues y de añoranza.",
          TextMapId = "PartyReward_Description_150403"
        },
        PartyReward_Description_180101 = {
          ContentDE = "Un montón de casquillos usados ​​que, con un toque de imaginación, se transforman en pistolas, cañones, dirigibles y poderosos robots: claves para abrir un mundo de sueños.",
          TextMapId = "PartyReward_Description_180101"
        },
        PartyReward_Description_180102 = {
          ContentDE = "Los cuentos de hadas no siempre terminan en felicidad. Después de que el pájaro se convirtió en una estrella ardiente, ¿todavía llora en el cielo nocturno?",
          TextMapId = "PartyReward_Description_180102"
        },
        PartyReward_Description_180103 = {
          ContentDE = "Aunque las frías lluvias del pasado aún no han cesado, ella todavía siente el calor de la palma de otra persona.",
          TextMapId = "PartyReward_Description_180103"
        },
        PartyReward_Description_180104 = {
          ContentDE = "¿Hasta dónde deberá viajar antes de poder escribir un bello final para este cuento?",
          TextMapId = "PartyReward_Description_180104"
        },
        PartyReward_Description_210101 = {
          ContentDE = "Bébela. Traga la amargura del vaso y abraza la dulzura del amor.",
          TextMapId = "PartyReward_Description_210101"
        },
        PartyReward_Description_210102 = {
          ContentDE = "La medusa gira en el cristal bajo la luz, hundiéndose silenciosamente en las profundidades, sin encontrar compañía antes de disiparse al llegar al fondo del mar.",
          TextMapId = "PartyReward_Description_210102"
        },
        PartyReward_Description_210103 = {
          ContentDE = "Las relaciones a menudo reflejan esta bebida: comienzan con calidez, siguen con amargura y terminan con escalofríos. Al igual que el agua y el fuego, algunas cosas nunca estuvieron destinadas a mezclarse.",
          TextMapId = "PartyReward_Description_210103"
        },
        PartyReward_Description_210104 = {
          ContentDE = "Esta bebida es sencilla en apariencia y directa en sabor, porque el amor verdadero no necesita adornos: existe en la mirada de la persona amada.",
          TextMapId = "PartyReward_Description_210104"
        },
        PartyReward_Description_230101 = {
          ContentDE = "¡De un trago! La dulzura ácida irrumpe en tu lengua como la risa de un niño, crepitando y estallando en el porche.",
          TextMapId = "PartyReward_Description_230101"
        },
        PartyReward_Description_230102 = {
          ContentDE = "Lo dulce y lo salado no son opuestos, así como la inocencia y la travesura pueden coexistir.",
          TextMapId = "PartyReward_Description_230102"
        },
        PartyReward_Description_230103 = {
          ContentDE = "La acidez inicial te frunce el ceño, pero a medida que tus papilas gustativas se adaptan, florece una dulzura suave, muy parecido a entender el mundo: la esperanza siempre sigue a la tormenta.",
          TextMapId = "PartyReward_Description_230103"
        },
        PartyReward_Description_230104 = {
          ContentDE = "%*$^&!@#%*^^Y&!#(%^%???!!",
          TextMapId = "PartyReward_Description_230104"
        },
        PartyReward_Description_240101 = {
          ContentDE = "Un compendio que cataloga 1.890 sustancias medicinales, casi la mitad de ellas hierbas. El nombre del autor se lee: Fufeng.",
          TextMapId = "PartyReward_Description_240101"
        },
        PartyReward_Description_240102 = {
          ContentDE = "Casi idéntico en apariencia a Onírihierba, pero se sabe que induce alucinaciones. Si las alucinaciones son sueños despiertos, entonces su semejanza empieza a tener sentido.",
          TextMapId = "PartyReward_Description_240102"
        },
        PartyReward_Description_240103 = {
          ContentDE = "De apariencia extraña, en Huaxu es un preciado símbolo de longevidad.",
          TextMapId = "PartyReward_Description_240103"
        },
        PartyReward_Description_240104 = {
          ContentDE = "Aunque la lámpara de plata aún arde, temo que nuestro reencuentro no fue más que un sueño fugaz.",
          TextMapId = "PartyReward_Description_240104"
        },
        PartyReward_Description_310101 = {
          ContentDE = "Una bebida atrevida y picante para quienes buscan un impulso más fuerte. El primer sorbo abre el apetito y el segundo enciende el ánimo: una bebida perfecta para romper el hielo.",
          TextMapId = "PartyReward_Description_310101"
        },
        PartyReward_Description_310102 = {
          ContentDE = "Lo que pasa en el bar se queda en el bar: una regla tácita de cualquier buena sesión de bebidas.",
          TextMapId = "PartyReward_Description_310102"
        },
        PartyReward_Description_310103 = {
          ContentDE = "Puede que Lago Glacial sea pequeño (un punto diminuto en el mapa del Imperio); sin embargo, Lago Glacial es enorme: los recuerdos de él perduran sin importar lo lejos que uno viaje.",
          TextMapId = "PartyReward_Description_310103"
        },
        PartyReward_Description_310201 = {
          ContentDE = "Debajo de los pétalos hay espinas, ¿y debajo del dobladillo del vestido de una criada? Balas.",
          TextMapId = "PartyReward_Description_310201"
        },
        PartyReward_Description_310202 = {
          ContentDE = "Los disfraces no son magia sino una forma de arte, capaz de transformar no solo tu apariencia, sino también tu estado de ánimo.",
          TextMapId = "PartyReward_Description_310202"
        },
        PartyReward_Description_310203 = {
          ContentDE = "Menos mal que las tijeras en la mano de la criada sólo apunten a flores marchitas.",
          TextMapId = "PartyReward_Description_310203"
        },
        PartyReward_Description_310204 = {
          ContentDE = "Una taza de té de flores, el voto solemne de una criada.",
          TextMapId = "PartyReward_Description_310204"
        },
        PartyReward_Description_310301 = {
          ContentDE = "Aunque los nombres de los juguetes pueden variar, cada uno de ellos puede estallar en un hermoso espectáculo de fuegos artificiales.",
          TextMapId = "PartyReward_Description_310301"
        },
        PartyReward_Description_310302 = {
          ContentDE = "Una bebida energética poderosa, capaz de borrar la fatiga de los viajeros. Con la mente finalmente clara, el corazón puede entonces ver lo que realmente desea.",
          TextMapId = "PartyReward_Description_310302"
        },
        PartyReward_Description_310303 = {
          ContentDE = "Una bebida de potente efecto calmante, ideal para aliviar los nervios de quienes esperan con ansiedad. Solo mediante la paciencia, el corazón descubre lo que realmente anhela.",
          TextMapId = "PartyReward_Description_310303"
        },
        PartyReward_Description_310304 = {
          ContentDE = "El enorme baúl lleno de juguetes explosivos: Dirigibles Bum, Cohetes Silbadores, Carruseles Explosivos… fue testigo de un nuevo comienzo en la Juguetería ¡Pum-pum!",
          TextMapId = "PartyReward_Description_310304"
        },
        PartyReward_Description_320101 = {
          ContentDE = "“Atiende bien a esta clienta.”",
          TextMapId = "PartyReward_Description_320101"
        },
        PartyReward_Description_320102 = {
          ContentDE = "Nunca imaginaste que algo así se podría beber.",
          TextMapId = "PartyReward_Description_320102"
        },
        PartyReward_Description_320103 = {
          ContentDE = "Un jarabe espeso y delicioso, cuya dulzura se aferra al paladar durante mucho tiempo.",
          TextMapId = "PartyReward_Description_320103"
        },
        PartyReward_Description_320104 = {
          ContentDE = "Un alcohol barato, para algunos un estimulante, para otros un anestésico. Cuando brindamos, saludamos “Por el Inquebrantable, por aquellos que nunca ceden”",
          TextMapId = "PartyReward_Description_320104"
        },
        PartyReward_Description_320201 = {
          ContentDE = "La verdad cambia según lo que la gente esté dispuesta a creer. No existe una “verdad absoluta”. Lo mismo ocurre con las personas: no hay enemigos eternos, solo intereses.",
          TextMapId = "PartyReward_Description_320201"
        },
        PartyReward_Description_320202 = {
          ContentDE = "Pan que entra sin esfuerzo, y miel todavía tibia y líquida: esa es su idea de una vida decente. Los niños Charon se atragantan con su pan duro y fingen que sabe igual.",
          TextMapId = "PartyReward_Description_320202"
        },
        PartyReward_Description_320203 = {
          ContentDE = "Un trago cálido baja con facilidad. Por un momento, casi crees que puedes dejar atrás los arrepentimientos de ayer.",
          TextMapId = "PartyReward_Description_320203"
        },
        PartyReward_Description_330101 = {
          ContentDE = "Después de un largo día recorriendo la mansión de los Kossak, Margie y tú han reunido un verdadero tesoro. Esperemos que valga la pena el esfuerzo y el dolor de brazos.",
          TextMapId = "PartyReward_Description_330101"
        },
        PartyReward_Description_330102 = {
          ContentDE = "Enterradas en la oscuridad, unas partituras escritas para el pueblo de Charon permanecieron olvidadas, hasta que Margie las hizo sonar en Lago Glacial, y fue entonces cuando volvieron a encontrar su verdadero propósito.",
          TextMapId = "PartyReward_Description_330102"
        },
        PartyReward_Description_330103 = {
          ContentDE = "Un regalo de cumpleaños pensado por un padre amoroso para su hija: muy funcional y con una pequeña sorpresa.",
          TextMapId = "PartyReward_Description_330103"
        },
        PartyReward_Description_330104 = {
          ContentDE = "Una bola de pelo gris, salpicada con manchas negras, evoca la imagen de una gatita con cola frondosa que camina con orgullo por la nieve.",
          TextMapId = "PartyReward_Description_330104"
        },
        PartyReward_Description_410101 = {
          ContentDE = "La columna “tareas diarias” siempre está repleta de nimiedades, que a veces se extienden hasta una segunda página. Así era la vida de Rhythm en la Escolta.",
          TextMapId = "PartyReward_Description_410101"
        },
        PartyReward_Description_410102 = {
          ContentDE = "Un álbum de recortes ordenado lleno de recortes de periódicos: limpiador, ayudante de cocina, escriba, pescador, camarero, albañil... ¿y hasta un entrenador de animales?",
          TextMapId = "PartyReward_Description_410102"
        },
        PartyReward_Description_410103 = {
          ContentDE = "Cada pasaje complicado está claramente marcado, con notas cuidadosas en los márgenes. Está claro que pertenece a un intérprete diligente, aunque aún no experimentado. Mira más de cerca y verás un lindo y pequeño rayo en la esquina.",
          TextMapId = "PartyReward_Description_410103"
        },
        PartyReward_Description_410201 = {
          ContentDE = "Los Nueve Capítulos de Dafeng siguen su ciclo señalado, inmutables desde la Antigüedad hasta el presente. Tal es el Camino del Cielo.",
          TextMapId = "PartyReward_Description_410201"
        },
        PartyReward_Description_410202 = {
          ContentDE = "Los agravios y los rencores silenciados que alguna vez fueron profundos se han vuelto apenas murmullos, sepultados bajo rumores y difamaciones.",
          TextMapId = "PartyReward_Description_410202"
        },
        PartyReward_Description_410203 = {
          ContentDE = "Lo que se fue pertenece al ayer, y el ayer no puede retenerse; lo que hoy turba mi corazón llena este día de inquietud.",
          TextMapId = "PartyReward_Description_410203"
        },
        PartyReward_Description_410204 = {
          ContentDE = "El tiempo quebranta todas las cosas, pero hay voluntades que permanecen iguales y nunca vacilan.",
          TextMapId = "PartyReward_Description_410204"
        },
        PartyReward_Description_420101 = {
          ContentDE = "Una flauta de bambú en cuyo cuerpo aún se adivinan las marcas de una rotura y su posterior reparación. Nadie sabe qué cambios dejaron esas huellas en su sonido.",
          TextMapId = "PartyReward_Description_420101"
        },
        PartyReward_Description_420102 = {
          ContentDE = "Un fajín del atuendo oficial de los Magistrados de Yingtian. Poetas y trovadores lo comparan con un vínculo con el Camino Celestial, pero en realidad es una atadura.",
          TextMapId = "PartyReward_Description_420102"
        },
        PartyReward_Description_420103 = {
          ContentDE = "Un broche de jade para el cinturón. Una vez roto, fue recompuesto y conservado durante años. Pero la gran grieta del centro nunca terminó de sanar.",
          TextMapId = "PartyReward_Description_420103"
        },
        PartyReward_Description_420104 = {
          ContentDE = "Tres jóvenes ataron una vez esta campanita a un zorro salvaje y le dijeron: “Este es tu hogar ahora”. Hoy, un viajero que ha vagado demasiado tiempo siente al fin el impulso de volver.",
          TextMapId = "PartyReward_Description_420104"
        },
        PartyReward_Description_420201 = {
          ContentDE = "Olvídate de la rutina y olvídate del cansancio: ¡comienza tu merecido descanso con un capricho dulce y relajado!",
          TextMapId = "PartyReward_Description_420201"
        },
        PartyReward_Description_420202 = {
          ContentDE = "“Triunfo”, una bebida de alta gama añejada durante 20 años, se ha convertido en un símbolo de refinamiento y prestigio entre la élite Hiperbórea. Sin embargo, debajo del lujoso envoltorio, la amargura es difícil de ocultar.",
          TextMapId = "PartyReward_Description_420202"
        },
        PartyReward_Description_420203 = {
          ContentDE = "La pistola sirve como símbolo de responsabilidad, que pesa mucho sobre los hombros de un padre, y como insignia de honor que se transmite de generación en generación.",
          TextMapId = "PartyReward_Description_420203"
        },
        PartyReward_Description_420204 = {
          ContentDE = "A veces, las mejores ideas surgen mientras estamos duchándonos, durmiendo o tomando un té. Las acciones emprendidas en busca de tal inspiración podrían parecer un poco... excéntricas para el mundo exterior.",
          TextMapId = "PartyReward_Description_420204"
        },
        PartyReward_Description_430101 = {
          ContentDE = "La 13.ª Legión es un símbolo de autoridad, el vehículo de la voluntad y la violencia del emperador.",
          TextMapId = "PartyReward_Description_430101"
        },
        PartyReward_Description_430102 = {
          ContentDE = "El hábito es algo poderoso. Nos hace aceptar lo anormal y alejarnos aún más de la norma.",
          TextMapId = "PartyReward_Description_430102"
        },
        PartyReward_Description_430103 = {
          ContentDE = "Bajo la gloria de esta medalla se esconde un camino sembrado de espinas.",
          TextMapId = "PartyReward_Description_430103"
        },
        PartyReward_Description_510101 = {
          ContentDE = "Esta bebida clásica nació de un accidente, pero se convirtió en una bebida habitual en Atlasia por su encanto versátil. Después de generaciones de refinamiento, ha trascendido su propósito original de saciar la sed y calmar el hambre, convirtiéndose en un símbolo de nuestra búsqueda del deleite culinario.",
          TextMapId = "PartyReward_Description_510101"
        },
        PartyReward_Description_510102 = {
          ContentDE = "Maduradas por el tiempo y revestidas de un blanco nevado, las Torcinueces esperan tranquilamente la cosecha, ofreciendo la generosidad de la naturaleza.",
          TextMapId = "PartyReward_Description_510102"
        },
        PartyReward_Description_510103 = {
          ContentDE = "Jugo de bayas boreales recién exprimido, con la acidez filtrada, dejando solo una rica dulzura. ¿El secreto para hacerlo aún mejor? Compartirlo con tu mejor amiga.",
          TextMapId = "PartyReward_Description_510103"
        },
        PartyReward_Description_510104 = {
          ContentDE = "Una avellana por pregunta: ese es el trato que hiciste con la chica. Así que cuando tengas dudas, ¿por qué no preguntarle a la avellana mágica?",
          TextMapId = "PartyReward_Description_510104"
        },
        PartyReward_Description_510201 = {
          ContentDE = "No hacen falta palabras, un trago lo dice todo.",
          TextMapId = "PartyReward_Description_510201"
        },
        PartyReward_Description_510202 = {
          ContentDE = "Después de un arduo día de trabajo, nada mejor que una buena bebida, y no es solo por su sabor, si no por la frescura y el hecho de poder disfrutarla con amigos.",
          TextMapId = "PartyReward_Description_510202"
        },
        PartyReward_Description_510203 = {
          ContentDE = "Sumerge esos recuerdos insoportables en la bebida. Luego bébela de un solo trago.",
          TextMapId = "PartyReward_Description_510203"
        },
        PartyReward_Description_510204 = {
          ContentDE = "Todo problema tiene solución. Mientras más te preocupes, más difícil se volverá el camino por delante.",
          TextMapId = "PartyReward_Description_510204"
        },
        PartyReward_Description_530101 = {
          ContentDE = "Los niños se acurrucan juntos, soñando con un futuro que está más allá de su alcance.",
          TextMapId = "PartyReward_Description_530101"
        },
        PartyReward_Description_530102 = {
          ContentDE = "“Por favor mira el mundo a través de tus ojos para mí.”",
          TextMapId = "PartyReward_Description_530102"
        },
        PartyReward_Description_530103 = {
          ContentDE = "La moneda ha sido lanzada. Nadie puede predecir el resultado: cara o cruz, muerte o renacimiento.",
          TextMapId = "PartyReward_Description_530103"
        },
        PartyReward_Description_540101 = {
          ContentDE = "Un ramo de flores cubierto con el rocío de la mañana y destinado a visitar a los enfermos. Pero el dolor verdadero no desaparece solo por un buen gesto.",
          TextMapId = "PartyReward_Description_540101"
        },
        PartyReward_Description_540102 = {
          ContentDE = "Un bisturí aún manchado de sangre, testigo de una tragedia catalogada como “accidente”. Pero ella sabe que no fue un accidente. El verdadero culpable no fue una sola persona… o quizás lo fueron todos.",
          TextMapId = "PartyReward_Description_540102"
        },
        PartyReward_Description_540103 = {
          ContentDE = "Una grabadora de voz que conserva su determinación al momento de su partida.",
          TextMapId = "PartyReward_Description_540103"
        },
