        },
        PartyTopic_Name_150203 = {
          ContentDE = "El paisaje a lo largo del camino equivocado",
          TextMapId = "PartyTopic_Name_150203"
        },
        PartyTopic_Name_150204 = {
          ContentDE = "La historia de ella",
          TextMapId = "PartyTopic_Name_150204"
        },
        PartyTopic_Name_150301 = {
          ContentDE = "Dúo del bosque profundo – Hojas en Juego",
          TextMapId = "PartyTopic_Name_150301"
        },
        PartyTopic_Name_150302 = {
          ContentDE = "El vagabundo del arrepentimiento — más allá de montañas y ríos",
          TextMapId = "PartyTopic_Name_150302"
        },
        PartyTopic_Name_150303 = {
          ContentDE = "De flautas de jade y vino nocturno",
          TextMapId = "PartyTopic_Name_150303"
        },
        PartyTopic_Name_150304 = {
          ContentDE = "Juventud marchita bajo la nieve del tiempo",
          TextMapId = "PartyTopic_Name_150304"
        },
        PartyTopic_Name_150401 = {
          ContentDE = "Ya no más a la deriva",
