        },
        PartyTopic_Name_230103 = {
          ContentDE = "La línea entre el bien y el mal",
          TextMapId = "PartyTopic_Name_230103"
        },
        PartyTopic_Name_230104 = {
          ContentDE = "El sexto tentáculo de Tabethe",
          TextMapId = "PartyTopic_Name_230104"
        },
        PartyTopic_Name_240101 = {
          ContentDE = "Insomnio",
          TextMapId = "PartyTopic_Name_240101"
        },
        PartyTopic_Name_240102 = {
          ContentDE = "Sueños inquietantes",
