        },
        PartyTopic_Name_240103 = {
          ContentDE = "Ecos del pasado",
          TextMapId = "PartyTopic_Name_240103"
        },
        PartyTopic_Name_240104 = {
          ContentDE = "Regresando a la paz",
          TextMapId = "PartyTopic_Name_240104"
        },
        PartyTopic_Name_310101 = {
          ContentDE = "Visitante de la Legión",
          TextMapId = "PartyTopic_Name_310101"
        },
        PartyTopic_Name_310102 = {
          ContentDE = "¿Zas? ¡Zas!",
          TextMapId = "PartyTopic_Name_310102"
        },
        PartyTopic_Name_310103 = {
          ContentDE = "La patria perdida para siempre",
          TextMapId = "PartyTopic_Name_310103"
        },
        PartyTopic_Name_310201 = {
          ContentDE = "Los múltiples roles de una criada",
          TextMapId = "PartyTopic_Name_310201"
        },
        PartyTopic_Name_310202 = {
          ContentDE = "El arte de la moda",
