        PhantomTalk_1101_Chest = {
          ContentDE = "Hay un cofre aquí. ¿Quieres abrirlo juntos?",
          TextMapId = "PhantomTalk_1101_Chest"
        },
        PhantomTalk_1102_Chest = {
          ContentDE = "Una fortuna inesperada... Tal vez sea la recompensa que te mereces.",
          TextMapId = "PhantomTalk_1102_Chest"
        },
        PhantomTalk_1103_Chest = {
          ContentDE = "No todas las sorpresas se esconden tras el telón. Algunas están justo bajo la luz.",
          TextMapId = "PhantomTalk_1103_Chest"
        },
        PhantomTalk_1104_Chest = {
          ContentDE = "Puede haber un tesoro aquí. Adelante, {性别:joven amigo|joven amiga}, añádelo a tu colección.",
          TextMapId = "PhantomTalk_1104_Chest"
        },
        PhantomTalk_1501_Chest = {
          ContentDE = "¿Un cofre? ¡Destózalo, Samael! No, espera... tranquilízate, hoy no.",
          TextMapId = "PhantomTalk_1501_Chest"
        },
        PhantomTalk_1502_Chest = {
          ContentDE = "Un recuerdo... tal vez dejado por un alma que se fue hacia el Mar Nebuloso.",
          TextMapId = "PhantomTalk_1502_Chest"
        },
        PhantomTalk_1503_Chest = {
          ContentDE = "Sería una lástima dejar este tesoro enterrado en la tierra. Adelante, tómalo.",
          TextMapId = "PhantomTalk_1503_Chest"
        },
        PhantomTalk_160101_Chest = {
          ContentDE = "Vaya, qué sorpresa agradable.",
          TextMapId = "PhantomTalk_160101_Chest"
        },
        PhantomTalk_1601_Chest = {
          ContentDE = "Vaya, qué sorpresa agradable.",
          TextMapId = "PhantomTalk_1601_Chest"
        },
        PhantomTalk_1801_Chest = {
          ContentDE = "Los amigos de Fina dicen... ¡que huelen el tesoro del Rey!",
          TextMapId = "PhantomTalk_1801_Chest"
        },
        PhantomTalk_2101_Chest = {
          ContentDE = "El romance florece con sorpresas... y aquí hay una ahora.",
          TextMapId = "PhantomTalk_2101_Chest"
        },
        PhantomTalk_2301_Chest = {
          ContentDE = "¡Oh! Un bonito botín. Jiji... ¿quieres adivinar qué hay dentro?",
          TextMapId = "PhantomTalk_2301_Chest"
        },
        PhantomTalk_2401_Chest = {
          ContentDE = "Fortuna inesperada en la naturaleza... Tal vez sea suficiente para comprar algo de curación.",
          TextMapId = "PhantomTalk_2401_Chest"
        },
        PhantomTalk_3101_Chest = {
          ContentDE = "Bueno, eso es una sorpresa. Parece que la suerte comienza a cambiar.",
          TextMapId = "PhantomTalk_3101_Chest"
        },
        PhantomTalk_3102_Chest = {
          ContentDE = "Como dije: la limpieza viene con alguna que otra sorpresa.",
          TextMapId = "PhantomTalk_3102_Chest"
        },
        PhantomTalk_3103_Chest = {
          ContentDE = "Eh... Oliver dice que hay algo br-brillante cerca.",
          TextMapId = "PhantomTalk_3103_Chest"
        },
        PhantomTalk_3201_Chest = {
          ContentDE = "¿Un bien sin dueño? Guárdalo, no es un crimen contra la justicia.",
          TextMapId = "PhantomTalk_3201_Chest"
        },
        PhantomTalk_3202_Chest = {
          ContentDE = "La suerte también es parte de la riqueza. Adelante, no hay vergüenza en aceptarlo.",
          TextMapId = "PhantomTalk_3202_Chest"
        },
        PhantomTalk_3301_Chest = {
          ContentDE = "¡Hueles a tesoro! ¡Qué buen día para la cosecha!",
          TextMapId = "PhantomTalk_3301_Chest"
        },
        PhantomTalk_4101_Chest = {
          ContentDE = "Perímetro despejado. Encontré algunos suministros abandonados.",
          TextMapId = "PhantomTalk_4101_Chest"
        },
        PhantomTalk_4102_Chest = {
          ContentDE = "Tierra abajo, fuego arriba, el oro nace del esfuerzo. Los signos no me engañaron.",
          TextMapId = "PhantomTalk_4102_Chest"
        },
        PhantomTalk_4201_Chest = {
          ContentDE = "Esas cosas mundanas no me sirven. Son tuyas.",
          TextMapId = "PhantomTalk_4201_Chest"
        },
        PhantomTalk_4202_Chest = {
          ContentDE = "¿Tesoro? Bien. ¿Crees que me dejarán cambiarlo por un día libre?",
          TextMapId = "PhantomTalk_4202_Chest"
        },
        PhantomTalk_4301_Chest = {
          ContentDE = "¿Un tesoro, tirado por ahí? Hmpf. No me interesa la presa que no resiste.",
          TextMapId = "PhantomTalk_4301_Chest"
        },
        PhantomTalk_5101_Chest = {
          ContentDE = "¿Encontraste algo, Filbert? Espera, ¡esto no es comida! ¡Escúpelo!",
          TextMapId = "PhantomTalk_5101_Chest"
        },
        PhantomTalk_5102_Chest = {
          ContentDE = "¡Mira lo que he encontrado! ¿Como siempre, a medias?",
          TextMapId = "PhantomTalk_5102_Chest"
        },
        PhantomTalk_5301_Chest = {
          ContentDE = "Este cofrecito... ¿contendrá también los recuerdos de alguien?",
          TextMapId = "PhantomTalk_5301_Chest"
        },
        PhantomTalk_5401_Chest = {
          ContentDE = "Encontré algunos suministros. ¿Reabastecemos antes de irnos otra vez?",
          TextMapId = "PhantomTalk_5401_Chest"
        },
