        QUEST_INSPECIALQUEST_MSG = {
          ContentDE = "Actualmente en misión especial",
          TextMapId = "QUEST_INSPECIALQUEST_MSG"
        },
        QuestDesc_10020101 = {
          ContentDE = "En ese fatídico día en la Isla del Purgatorio, la suerte te favoreció y viviste para ver otro día. Al despertar de nuevo, Berenica ya no estaba, dejándote en medio de un paisaje nevado desconocido.\nUna dama vestida de rojo, que se presentó como Camilla, junto con una niña llamada Snow, te invitaron a ir con ellas a Lago Glacial.\nDespués de pensarlo mucho, decidiste unirse a ellas...",
          TextMapId = "QuestDesc_10020101"
        },
        QuestDesc_10020102 = {
          ContentDE = "En ese fatídico día en la Isla del Purgatorio, la suerte te favoreció y viviste para ver otro día. Al despertar de nuevo, Berenica ya no estaba, dejándote en medio de un paisaje nevado desconocido.\nUna dama vestida de rojo, que se presentó como Camilla, junto con una niña llamada Snow, te invitaron a ir con ellas a Lago Glacial.\nDespués de pensarlo mucho, decidiste unirse a ellas...",
          TextMapId = "QuestDesc_10020102"
        },
        QuestDesc_10020103 = {
          ContentDE = "El vehículo volcado y la carga esparcida en el puente han atraído a los Filthoids. Repele a estos visitantes no deseados.",
          TextMapId = "QuestDesc_10020103"
        },
        QuestDesc_10020104 = {
          ContentDE = "Después de haber expulsado con éxito a los Filthoids, tú y Snow continúan su viaje hacia Lago Glacial.",
          TextMapId = "QuestDesc_10020104"
        },
        QuestDesc_10020105 = {
          ContentDE = "A pesar de un pequeño contratiempo con el guardia que verificaba los permisos de viaje, las inteligentes negociaciones de la Sra. Camilla aseguraron tu entrada a Lago Glacial.",
          TextMapId = "QuestDesc_10020105"
        },
        QuestDesc_10020106 = {
          ContentDE = "La señorita Camilla sugiere que te alojes en la Casa de Hypnos.\nA pesar de sus inquietantes historias, decides profundizar...",
          TextMapId = "QuestDesc_10020106"
        },
        QuestDesc_10020107 = {
          ContentDE = "La señorita Camilla sugiere que te alojes en la Casa de Hypnos.\nA pesar de sus inquietantes historias, decides profundizar...",
          TextMapId = "QuestDesc_10020107"
        },
        QuestDesc_10020108 = {
          ContentDE = "Henrik, el dueño de la Casa de Hypnos, es un hombre melancólico y distante.\nPersuadido por una joven llena de energía, le ofrece a regañadientes refugio para pasar la noche.\nEs hora de dirigirte a la casa mencionada por la chica.",
          TextMapId = "QuestDesc_10020108"
        },
        QuestDesc_10020109 = {
          ContentDE = "Henrik, el dueño de la Casa de Hypnos, es un hombre melancólico y distante.\nPersuadido por una joven llena de energía, le ofrece a regañadientes refugio para pasar la noche.\nEs hora de dirigirte a la casa mencionada por la chica.",
          TextMapId = "QuestDesc_10020109"
        },
        QuestDesc_10020110 = {
          ContentDE = "Un raro momento de descanso. Es hora de poner en orden tus preguntas y la situación en cuestión.",
          TextMapId = "QuestDesc_10020110"
        },
        QuestDesc_10020111 = {
          ContentDE = "Tienes algunas preguntas para Psyche.",
          TextMapId = "QuestDesc_10020111"
        },
        QuestDesc_10020112 = {
          ContentDE = "Antes de embarcarte en tu búsqueda para encontrar Berenica, necesitas reunir algunos fondos y obtener un permiso de viaje.\nPsyche revela que “Los Asfódelos”, una taberna dirigida por Camilla, ofrece una forma de ganar dinero a través de encargos sin necesidad de permisos de viaje.",
          TextMapId = "QuestDesc_10020112"
        },
        QuestDesc_10020201 = {
          ContentDE = "Antes de embarcarte en tu búsqueda para encontrar Berenica, necesitas reunir algunos fondos y obtener un permiso de viaje.\nPsyche revela que “Los Asfódelos”, una taberna dirigida por Camilla, ofrece una forma de ganar dinero a través de encargos sin necesidad de permisos de viaje.",
          TextMapId = "QuestDesc_10020201"
        },
        QuestDesc_10020202 = {
          ContentDE = "Antes de embarcarte en tu búsqueda para encontrar Berenica, necesitas reunir algunos fondos y obtener un permiso de viaje.\nPsyche revela que “Los Asfódelos”, una taberna dirigida por Camilla, ofrece una forma de ganar dinero a través de encargos sin necesidad de permisos de viaje.",
          TextMapId = "QuestDesc_10020202"
        },
        QuestDesc_10020203 = {
          ContentDE = "En la plaza fuiste testigo de una atrocidad: es lo habitual para los “Charons” con cuernos y espinas únicas.\nPara evitar meter en problemas a la señorita Camilla, quien había respondido por ti, guardaste silencio.\nContinúa hacia “Los Asfódelos”.",
          TextMapId = "QuestDesc_10020203"
        },
        QuestDesc_10020204 = {
          ContentDE = "La chica recicladora llamada Margie se ha topado con algunas dificultades.\nPregúntale sobre su situación.",
          TextMapId = "QuestDesc_10020204"
        },
        QuestDesc_10020205 = {
          ContentDE = "La chica recicladora llamada Margie se ha topado con algunas dificultades.\nPregúntale sobre su situación.",
          TextMapId = "QuestDesc_10020205"
        },
        QuestDesc_10020206 = {
          ContentDE = "Un ladrón le robó a Margie, una joven recicladora.\nAyúdala a recuperar su bolsa de dinero. No sólo para ayudarla, sino también para pasar la prueba de Camilla.",
          TextMapId = "QuestDesc_10020206"
        },
        QuestDesc_10020207 = {
          ContentDE = "Un ladrón le robó a Margie, una joven recicladora.\nDespués de salir de Los Asfódelos, intenta preguntar en la plaza para ver si alguien ha visto al ladrón.",
          TextMapId = "QuestDesc_10020207"
        },
        QuestDesc_10020208 = {
          ContentDE = "Un anciano llamado Badi, que vive cerca de la plaza, afirma haber visto al ladrón.\nÉl sugiere buscar alrededor del basurero #3.",
          TextMapId = "QuestDesc_10020208"
        },
        QuestDesc_10020209 = {
          ContentDE = "Cerca del basurero, descubres efectivamente huellas del ladrón; conducen hasta los tejados.\nSube al tejado y continúa tu investigación.",
          TextMapId = "QuestDesc_10020209"
        },
        QuestDesc_10020210 = {
          ContentDE = "Estás en el tejado. Registra los alrededores en busca del ladrón.",
          TextMapId = "QuestDesc_10020210"
        },
        QuestDesc_10020211 = {
          ContentDE = "Por fin encuentras al ladrón que robó la bolsa de Margie. Tras un breve enfrentamiento, huye de repente.\n¡No hay tiempo que perder: persíguelo! Espera… algo parece extraño cerca de la boca de alcantarilla.",
          TextMapId = "QuestDesc_10020211"
        },
        QuestDesc_10020212 = {
          ContentDE = "Siguiendo el rastro hacia las alcantarillas, el ladrón ha dejado trampas para ralentizarte.\nEncuentra una manera de desactivar estos mecanismos y continuar la persecución.",
          TextMapId = "QuestDesc_10020212"
        },
        QuestDesc_10020213 = {
          ContentDE = "Has conseguido accionar los interruptores y bajar con éxito el nivel del agua.\nEs hora de reanudar la persecución.",
          TextMapId = "QuestDesc_10020213"
        },
        QuestDesc_10020213_1 = {
          ContentDE = "El ladrón te tendió una emboscada con una serie de trampas preparadas de antemano. Margie y Snow fueron tomadas por sorpresa y recibieron algunos golpes.\nSigue buscando por la zona: no puede haber ido muy lejos.",
          TextMapId = "QuestDesc_10020213_1"
        },
        QuestDesc_10020214 = {
          ContentDE = "El ladrón utilizó un pequeño dispositivo para liberar una espesa niebla y desapareció en ella. Necesitarás una llave de repuesto para continuar la persecución.",
          TextMapId = "QuestDesc_10020214"
        },
        QuestDesc_10020215 = {
          ContentDE = "Por fin, has visto al ladrón de nuevo. Esta vez no se escapará.\nDerrota al ladrón y captúralo.",
          TextMapId = "QuestDesc_10020215"
        },
        QuestDesc_10020221 = {
          ContentDE = "Has completado el encargo de Margie. Regresa a Los Asfódelos para recibir tu recompensa.",
          TextMapId = "QuestDesc_10020221"
        },
        QuestDesc_10020222 = {
          ContentDE = "Todas los encargos para Phoxcazadores están en el tablón de anuncios de Los Asfódelos. Ve a comprobarlo.",
          TextMapId = "QuestDesc_10020222"
        },
        QuestDesc_10020223 = {
          ContentDE = "Wells te entendió mal y se avergonzó. Decidió comprarte una bebida para expresar sus disculpas...",
          TextMapId = "QuestDesc_10020223"
        },
        QuestDesc_10020224 = {
          ContentDE = "El sistema de Geniemons ahora está desbloqueado. Captura un Geniemon para que te ayude en tu próximo viaje.",
          TextMapId = "QuestDesc_10020224"
        },
        QuestDesc_10020301 = {
          ContentDE = "Henrik, dueño de la Casa de Hypnos, ha ofrecido una lucrativa recompensa a los Phoxcazadores para recuperar el Cristal estelar de la Mina de Glevumm.\nLa recompensa cubre perfectamente tus gastos de viaje al sur, así que decides arriesgarte...",
          TextMapId = "QuestDesc_10020301"
        },
        QuestDesc_10020302 = {
          ContentDE = [[
Psyche decide unirse a nuestro viaje para mostrarnos el camino hacia la Mina de Glevum.
Partimos con Psyche hacia la Mina de Glevum.]],
          TextMapId = "QuestDesc_10020302"
        },
        QuestDesc_10020303 = {
          ContentDE = "Parece que Psyche ha tomado una decisión: va contigo en esta pequeña “aventura”.\nPartimos con Psyche hacia la Mina de Glevum.",
          TextMapId = "QuestDesc_10020303"
        },
        QuestDesc_10020304 = {
          ContentDE = [[
Las puertas de la Mina de Glevum han estado cerradas durante mucho tiempo.
Busca un pasaje alternativo.]],
          TextMapId = "QuestDesc_10020304"
        },
        QuestDesc_10020305 = {
          ContentDE = "Al atravesar los túneles desiertos, has entrado en las profundidades de la Mina de Glevum.\nDonde una vez estuvo un majestuoso Árbol Celestial, solo quedan pequeños restos de sus raíces después de años de explotación, haciendo eco de una era pasada de abundancia.\nExplora las profundidades de esta Mina abandonada para encontrar el Cristal estelar buscado por Henrik.",
          TextMapId = "QuestDesc_10020305"
        },
        QuestDesc_10020306 = {
          ContentDE = "Al atravesar los túneles desiertos, has entrado en las profundidades de la Mina de Glevum.\nDonde una vez estuvo un majestuoso Árbol Celestial, solo quedan pequeños restos de sus raíces después de años de explotación, haciendo eco de una era pasada de abundancia.\nExplora las profundidades de esta Mina abandonada para encontrar el Cristal estelar buscado por Henrik.",
          TextMapId = "QuestDesc_10020306"
        },
        QuestDesc_10020307 = {
          ContentDE = "Has logrado entrar en la Mina de Glevum, pero una puerta sellada bloquea el camino.\nBusca en el área cercana: podría haber una forma de abrirlo.\n\n....\nUn Phoxcazador mencionó una vez lámparas de túnel y señales en su diario.\nSi tienes tiempo libre, considera restaurarlos: podrían iluminar el camino para quienes vengan después de ti.",
          TextMapId = "QuestDesc_10020307"
        },
        QuestDesc_10020308 = {
          ContentDE = "Al atravesar los túneles desiertos, has entrado en las profundidades de la Mina de Glevum.\nDonde una vez estuvo un majestuoso Árbol Celestial, solo quedan pequeños restos de sus raíces después de años de explotación, haciendo eco de una era pasada de abundancia.\nHay Filthoids que se interponen en el camino. Derrotalos y sigue adelante.",
          TextMapId = "QuestDesc_10020308"
        },
        QuestDesc_10020309 = {
          ContentDE = "Al atravesar los túneles desiertos, has entrado en las profundidades de la Mina de Glevum.\nDonde una vez estuvo un majestuoso Árbol Celestial, solo quedan pequeños restos de sus raíces después de años de explotación, haciendo eco de una era pasada de abundancia.\nOpera el dispositivo para abrir la puerta y explora las profundidades de esta Mina abandonada para encontrar el Cristal estelar buscado por Henrik.",
          TextMapId = "QuestDesc_10020309"
        },
        QuestDesc_10020310 = {
          ContentDE = "Al atravesar los túneles desiertos, has entrado en las profundidades de la Mina de Glevum.\nDonde una vez estuvo un majestuoso Árbol Celestial, solo quedan pequeños restos de sus raíces después de años de explotación, haciendo eco de una era pasada de abundancia.\nExplora las profundidades de esta Mina abandonada para encontrar el Cristal estelar buscado por Henrik.",
          TextMapId = "QuestDesc_10020310"
        },
        QuestDesc_10020311 = {
          ContentDE = "Al atravesar los túneles desiertos, has entrado en las profundidades de la Mina de Glevum.\nDonde una vez estuvo un majestuoso Árbol Celestial, solo quedan pequeños restos de sus raíces después de años de explotación, haciendo eco de una era pasada de abundancia. Sin embargo, las rocas sueltas y los cristales afilados y dentados esparcidos por todas partes insinúan peligros que se avecinan.\nExplora las profundidades de esta Mina abandonada para encontrar el Cristal estelar buscado por Henrik.",
          TextMapId = "QuestDesc_10020311"
        },
        QuestDesc_10020312 = {
          ContentDE = "Al atravesar los túneles desiertos, has entrado en las profundidades de la Mina de Glevum.\nDonde una vez estuvo un majestuoso Árbol Celestial, solo quedan pequeños restos de sus raíces después de años de explotación, haciendo eco de una era pasada de abundancia. Sin embargo, las rocas sueltas y los cristales afilados y dentados esparcidos por todas partes insinúan peligros que se avecinan.\nExplora las profundidades de esta Mina abandonada para encontrar el Cristal estelar buscado por Henrik.",
          TextMapId = "QuestDesc_10020312"
        },
        QuestDesc_10020313 = {
          ContentDE = "Tu llegada ha despertado al Filthoid gigante que habita en las profundidades de la Mina de Glevum.\nAhora que hemos llegado a esta situación, el primer paso es derrotarlo.",
          TextMapId = "QuestDesc_10020313"
        },
        QuestDesc_10020314 = {
          ContentDE = "Debajo del temible cadáver del Filthoid gigante yace una gema resplandeciente con la luz de las estrellas.\nRecógela y llévala contigo.",
          TextMapId = "QuestDesc_10020314"
        },
        QuestDesc_10020315 = {
          ContentDE = "Tu primera aventura en la Mina de Glevum concluye exitosamente, a pesar de las desagradables complicaciones con Outsider.\nOutsider tomó el Cristal estelar. Parece ansioso por hablar contigo. Has aceptado reunirte con él en su residencia.",
          TextMapId = "QuestDesc_10020315"
        },
        QuestDesc_10020316 = {
          ContentDE = "Tu primera aventura en la Mina de Glevum concluye exitosamente, a pesar de las desagradables complicaciones con Outsider.\nOutsider tomó el Cristal estelar. Parece ansioso por hablar contigo. Has aceptado reunirte con él en su residencia.\nMientras tanto, alguien espera en las puertas de Lago Glacial, y no parece muy contento...",
          TextMapId = "QuestDesc_10020316"
        },
        QuestDesc_10020401 = {
          ContentDE = "Outsider solicitó una reunión exclusiva, por lo que Snow se fue primero.\nSegún Outsider, su casa está en los barrios marginales, marcada por un pájaro en la puerta.",
          TextMapId = "QuestDesc_10020401"
        },
        QuestDesc_10020402 = {
          ContentDE = "Fuiste invitado a una modesta pero dulce “fiesta de té” con Outsider y su hermana Fina.\nDespués de la comida, Outsider quería discutir contigo algunos asuntos serios en privado.",
          TextMapId = "QuestDesc_10020402"
        },
        QuestDesc_10020403 = {
          ContentDE = "Fuiste invitado a una modesta pero dulce “fiesta de té” con Outsider y su hermana Fina.\nDespués de la comida, Outsider quería discutir contigo algunos asuntos serios en privado.",
          TextMapId = "QuestDesc_10020403"
        },
        QuestDesc_10020404 = {
          ContentDE = "A cambio de un permiso de viaje, Outsider te solicitó que investigaras la Casa de Hypnos con el pretexto de entregar el Cristal estelar.\nPero primero, un merecido descanso.",
          TextMapId = "QuestDesc_10020404"
        },
        QuestDesc_10020405 = {
          ContentDE = "Según Outsider, la Casa de Hypnos dirigida por Henrik puede albergar secretos horribles,\nse dice que un Phoxcazador llamado Hunt desapareció dentro de sus muros.\nDecidiste investigar esta posada.",
          TextMapId = "QuestDesc_10020405"
        },
        QuestDesc_10020406 = {
          ContentDE = "Henrik abrió la puerta a regañadientes debido al Cristal estelar.\ns hora de adentrarse para investigar.",
          TextMapId = "QuestDesc_10020406"
        },
        QuestDesc_10020407 = {
          ContentDE = "Henrik regresó a su oficina para verificar la autenticidad del Cristal estelar. Ahora es la oportunidad de explorar la posada.\nPsyche acaba de saludarte; atiéndela primero.",
          TextMapId = "QuestDesc_10020407"
        },
        QuestDesc_10020408 = {
          ContentDE = "Recibiste un regalo de Psyche. Ella dijo que las flores traerían buena suerte.\nTambién has aprendido que todos los huéspedes de la Casa de Hypnos sufren algún tipo de enfermedad, y Henrik parece estar investigando algo en secreto.\nSerá mejor investigar otras áreas de la posada.",
          TextMapId = "QuestDesc_10020408"
        },
        QuestDesc_10020409 = {
          ContentDE = "Los huéspedes de la Casa de Hypnos parecen ser un grupo inusual. Pregunta y descubre lo que saben sobre Henrik.",
          TextMapId = "QuestDesc_10020409"
        },
        QuestDesc_10020410 = {
          ContentDE = "Has aprendido que la oficina cerrada de Henrik está restringida dentro del edificio.\nHas aprendido que Henrik sale sistemáticamente a las cinco en punto de la tarde el día 20 de cada mes.\nHas confirmado que Hunt, el Phoxcazador desaparecido, de hecho se alojó aquí una vez,\nHenrik debería regresar en cualquier momento.",
          TextMapId = "QuestDesc_10020410"
        },
        QuestDesc_10020411 = {
          ContentDE = "Aunque no pudiste entrar en la oficina, lograste reunir información útil.\nRegresa y comparte tus hallazgos con Outsider.",
          TextMapId = "QuestDesc_10020411"
        },
        QuestDesc_10020412 = {
          ContentDE = "Aunque no pudiste entrar en la oficina, lograste reunir información útil.\nRegresa y comparte tus hallazgos con Outsider.",
          TextMapId = "QuestDesc_10020412"
        },
        QuestDesc_10020501 = {
          ContentDE = "Aún queda mucho tiempo antes de que llegue el día 20.\nConsulta el tablón de anuncios de Los Asfódelos y completa un Encargo: Mediación para ganar experiencia.",
          TextMapId = "QuestDesc_10020501"
        },
        QuestDesc_10020502 = {
          ContentDE = "A medida que te vayas instalando poco a poco en la ciudad y aprendas las habilidades de {性别:un Phoxcazador|una Phoxcazadora} ...\nEn Dismania, la Capital Imperial, la Legión está tramando algo.",
          TextMapId = "QuestDesc_10020502"
        },
        QuestDesc_10020503 = {
          ContentDE = "Afuera de Lago Glacial, Outsider está ocupado colocando trampas en un claro en las afueras mientras te espera.\nQuizás quieras ver qué está haciendo.",
          TextMapId = "QuestDesc_10020503"
        },
        QuestDesc_10020504 = {
          ContentDE = "Siguiendo las instrucciones de Outsider, derrota a los Filthoids que se acercan para completar tu entrenamiento de combate.",
          TextMapId = "QuestDesc_10020504"
        },
        QuestDesc_10020504_1 = {
          ContentDE = "Has derrotado a todos los Filthoids. Habla con Outsider.",
          TextMapId = "QuestDesc_10020504_1"
        },
        QuestDesc_10020505 = {
          ContentDE = "De alguna manera, Outsider ha atraído a una multitud de Filthoids.\nBueno, no tiene sentido quejarse: simplemente ayúdalo a derrotarlos.",
          TextMapId = "QuestDesc_10020505"
        },
        QuestDesc_10020505_1 = {
          ContentDE = "Aceptaste encontrarte con Outsider para el entrenamiento de combate de Phoxcazador en las afueras, pero Outsider de alguna manera ha atraído a una multitud de Filthoids.\nAhora que te has encargado de los Filthoids, ve a ver qué está haciendo.",
          TextMapId = "QuestDesc_10020505_1"
        },
        QuestDesc_10020506 = {
          ContentDE = "Según Outsider, la siguiente ronda de entrenamiento de combate implica proteger este dispositivo ruidoso.\nSimplemente derrota a los Filthoids y evita que lo dañen.",
          TextMapId = "QuestDesc_10020506"
        },
        QuestDesc_10020507 = {
          ContentDE = "Henrik debería salir de casa pronto.\nÚnete a Snow cerca de la Casa de Hypnos, a quien se le ha encomendado la tarea de vigilar secretamente a Henrik.",
          TextMapId = "QuestDesc_10020507"
        },
        QuestDesc_10020601 = {
          ContentDE = "Henrik debería salir de casa pronto.\nÚnete a Snow cerca de la Casa de Hypnos, a quien se le ha encomendado la tarea de vigilar secretamente a Henrik.",
          TextMapId = "QuestDesc_10020601"
        },
        QuestDesc_10020602 = {
          ContentDE = "Parece que Henrik se dirige fuera de la ciudad.\nSíguelo para ver qué está haciendo.",
          TextMapId = "QuestDesc_10020602"
        },
        QuestDesc_10020603 = {
          ContentDE = "Henrik pasa por una floristería, compra un ramo y continúa su camino.\nSíguelo.",
          TextMapId = "QuestDesc_10020603"
        },
        QuestDesc_10020604 = {
          ContentDE = "Outsider se ha infiltrado en la habitación cerrada a través de la chimenea.\nExplora los secretos de esta habitación.",
          TextMapId = "QuestDesc_10020604"
        },
        QuestDesc_10020605 = {
          ContentDE = "Tú y Snow descubrieron la caja de Henrik escondida bajo el agua.\nEl contenido parece haberse disuelto.\nRegresa y mira lo que Outsider ha descubierto.",
          TextMapId = "QuestDesc_10020605"
        },
        QuestDesc_10020606 = {
          ContentDE = "Outsider se coló en la oficina de Henrik y descubrió un documento titulado “El Proyecto del Sueño”.\nEl documento contiene una lista de nombres de personas que han desaparecido, y el nombre de Psyche también está en la lista.\nParece que Henrik podría hacerle daño a Psyche. Preocupado por su seguridad, decides intervenir y dirigirte a la Casa de Hypnos para realizar una investigación más profunda.",
          TextMapId = "QuestDesc_10020606"
        },
        QuestDesc_10020607 = {
          ContentDE = "Se oyen sollozos silenciosos que vienen de la habitación de Psyche. Ve a revisarla.",
          TextMapId = "QuestDesc_10020607"
        },
        QuestDesc_10020608 = {
          ContentDE = "Por alguna razón, Psyche parece molesta, aunque Henrik afirma que simplemente se siente un poco indispuesta.\nSintiendo la necesidad de una conversación privada, la invitas a dar un paseo por el Lago Lamentoso. Está justo afuera de Lago Glacial. Ahora ve y da un paseo con Psyche.",
          TextMapId = "QuestDesc_10020608"
        },
        QuestDesc_10020609 = {
          ContentDE = "Notas que la visión de Psyche parece estar gravemente dañada, pero ella se resiste a hablar de ello.\nPsyche desea que la acompañes a las viejas raíces del árbol junto al Lago Lamentoso, un lugar cargado de recuerdos de su infancia.",
          TextMapId = "QuestDesc_10020609"
        },
        QuestDesc_10020610 = {
          ContentDE = "Según Psyche, bajo estas raíces se esconde un secreto. Es hora de desenterrarlo.",
          TextMapId = "QuestDesc_10020610"
        },
        QuestDesc_10020611 = {
          ContentDE = "Psyche te dio la cámara que una vez enterró cuando era niña. Ella ya no puede ver, pero espera que puedas capturar el mundo a través de su lente.\nParece que Psyche tiene algo más en mente. Camina con ella por el Lago Lamentoso y escúchala.",
          TextMapId = "QuestDesc_10020611"
        },
        QuestDesc_10020612 = {
          ContentDE = "Tu conversación con Psyche se vio interrumpida bruscamente por la llegada de Henrik. Le dijiste a Psyche que la estarías esperando en la taquilla a las 2 de la mañana.\nAhora es el momento de regresar a Lago Glacial y prepararte para su rescate.",
          TextMapId = "QuestDesc_10020612"
        },
        QuestDesc_10020613 = {
          ContentDE = "Mientras regresas a Lago Glacial, te encuentras con un soldado sospechoso. Alarmado por tu presencia, ataca sin previo aviso...",
          TextMapId = "QuestDesc_10020613"
        },
        QuestDesc_10020614 = {
          ContentDE = "Una serie de puñetazos “amistosos” calmaron al soldado llamado Kevin.\nParece que tiene algo que decir.",
          TextMapId = "QuestDesc_10020614"
        },
        QuestDesc_10020615 = {
          ContentDE = "Kevin confesó que estaba tratando de enterrar en secreto a un Deteriorador, que solía ser su vecino. Él te rogó que lo mantuvieras en secreto.\nTambién explicó qué es “Deterioro” y compartió la historia de Henrik.\nArmado con esta nueva información, decides regresar a Lago Glacial para discutirlo con Outsider y Snow.",
          TextMapId = "QuestDesc_10020615"
        },
        QuestDesc_10020701 = {
          ContentDE = "La noche ha caído. Como prometiste, te encontrarás con Psyche en la taquilla ubicada al sur de la Casa de Hypnos a las 2 de la mañana. Outsider parece listo.\nNo hay tiempo que perder. Ahora dirígete al punto de encuentro.",
          TextMapId = "QuestDesc_10020701"
        },
        QuestDesc_10020702 = {
          ContentDE = "Mientras te dirigías a encontrarte con Psyche, un grito repentino vino desde la dirección de la Casa de Hypnos: sonaba como Snow.\nSentiste un escalofrío en la espalda que te impulsaba a investigar el origen de la perturbación.",
          TextMapId = "QuestDesc_10020702"
        },
        QuestDesc_10020703 = {
          ContentDE = "Según Snow, Psyche está mostrando signos de deterioro. Mientras tanto, un chico de la Casa de Hypnos te implora que ayudes a Henrik.\nSigue al niño hasta la Casa de Hypnos para comprender la situación por completo.",
          TextMapId = "QuestDesc_10020703"
        },
        QuestDesc_10020704 = {
          ContentDE = "La oficina normalmente cerrada en la planta baja de la Casa de Hypnos ahora está abierta de par en par, lo que sugiere que la oficina de Henrik es el epicentro del incidente en curso.",
          TextMapId = "QuestDesc_10020704"
        },
        QuestDesc_10020705 = {
          ContentDE = "Gravemente herido, Henrik revela la verdad en sus momentos finales y te ruega que salves a Psyche, que ha perdido el sentido. Éste es el deseo colectivo de todos en la Casa de Hypnos.\nSnow te dirige al lugar al que huyó Psyche. Dirígete al Lago Lamentoso para encontrarla.",
          TextMapId = "QuestDesc_10020705"
        },
        QuestDesc_10020706 = {
          ContentDE = "Las mariposas revolotean a lo largo del camino que tomó Psyche, como si te guiaran.\nSíguelas para encontrarla.",
          TextMapId = "QuestDesc_10020706"
        },
        QuestDesc_10020707 = {
          ContentDE = "Siguiendo las mariposas, llegaras al Lago Lamentoso, donde vientos furiosos parecen decididos a bloquear tu camino.\nAfortunadamente, las ráfagas siguen un patrón. Mantente alerta y cruza con cuidado el Lago Glacial.",
          TextMapId = "QuestDesc_10020707"
        },
        QuestDesc_10020708 = {
          ContentDE = "La condición de Psyche empeora. Para cuando finalmente la alcanzas, ella se ha transformado en una Filthoid conocido como la Eclosionadora.\nDerrota a la Eclosionadora y despierta a Psyche de su sueño.",
          TextMapId = "QuestDesc_10020708"
        },
        QuestDesc_10020709 = {
          ContentDE = "Psyche duerme en el ojo de la tormenta. En medio de los vientos aulladores, sientes la crueldad del destino, pero tus manos persisten en sus esfuerzos.\nAl final, lo único que puedes ofrecer es un ramo para la niña dormida.",
          TextMapId = "QuestDesc_10020709"
        },
        QuestDesc_10020801 = {
          ContentDE = "De repente, la ventisca se levanta y Psyche se encuentra en un lugar familiar...",
          TextMapId = "QuestDesc_10020801"
        },
        QuestDesc_10020802 = {
          ContentDE = "Un corredor tejido a partir de recuerdos se extiende ante ella. Al final yace una sombra familiar y extraña del pasado.",
          TextMapId = "QuestDesc_10020802"
        },
        QuestDesc_10020803 = {
          ContentDE = "La sombra roe implacablemente la mente de Psyche, pero tu voz la llama de regreso.\nA medida que sus nuevas alas se despliegan, una tranquila resolución se instala en su corazón.",
          TextMapId = "QuestDesc_10020803"
        },
        QuestDesc_10020804 = {
          ContentDE = "La historia de Psyche concluye con una sola bala de la Escolta de la ciudad.\nRhythm, el suboficial, te confundió con víctimas atacadas por los Filthoid y ahora los mira con preocupación.",
          TextMapId = "QuestDesc_10020804"
        },
        QuestDesc_10020805 = {
          ContentDE = "Siguiendo la tradición de Charon, dejas descansar a Psyche en el agua, dejando que su alma regrese al Mar Nebuloso.",
          TextMapId = "QuestDesc_10020805"
        },
        QuestDesc_10020806 = {
          ContentDE = "Junto con Outsider, encuentras un lugar apartado cerca del Lago Lamentoso para despedirte de Psyche por última vez.\nEstás seguro de que le habría encantado este lugar: un lugar de descanso sereno y hermoso, lejos de gritos de tristeza o del clamor de la maquinaria.",
          TextMapId = "QuestDesc_10020806"
        },
        QuestDesc_10020807 = {
          ContentDE = "Sólo la suave brisa ofrece su silencioso tributo. El sueño se te escapa, por lo que emprendes una caminata por las Cavernas de Deshielo.\nEra el lugar donde se recogía tierra fértil para ella, y uno de los pocos lugares más allá de las murallas de la ciudad, protegido del viento y la nieve.",
          TextMapId = "QuestDesc_10020807"
        },
        QuestDesc_10020808 = {
          ContentDE = [[
Una figura solitaria se encuentra en las Cavernas de Deshielo: una mujer que no conoces.
Cuando sus miradas se encuentran, ella parece dispuesta a hablar.]],
          TextMapId = "QuestDesc_10020808"
        },
        QuestDesc_10020809 = {
          ContentDE = "Aquí, en la delgada grieta entre el sueño y la realidad, los transeúntes del ensueño despiertan. Y en este instante suspendido, el tumulto del mundo se convierte en eco de arena.",
          TextMapId = "QuestDesc_10020809"
        },
        QuestDesc_10029701 = {
          ContentDE = "Aumenta tu Rango de Aventura para continuar la Misión principal\n\nPuedes ganar EXP mediante:\n1. Completa <H>Encargos</> (excluyendo encargos del Manual de Noctoviajero)\n2. Interactúa con los residentes locales y completa <H>Misiones secundarias</>",
          TextMapId = "QuestDesc_10029701"
        },
        QuestDesc_10029801 = {
          ContentDE = "Aumenta tu Rango de Aventura para continuar la Misión principal\n\nPuedes ganar EXP mediante:\n1. Completa <H>Encargos</> (excluyendo encargos del Manual de Noctoviajero)\n2. Interactúa con los residentes locales y completa <H>Misiones secundarias</>",
          TextMapId = "QuestDesc_10029801"
        },
        QuestDesc_10029901 = {
          ContentDE = "Aumenta tu Rango de Aventura para continuar la Misión principal\n\nPuedes ganar EXP mediante:\n1. Completa los tutoriales de <H>Lunotelar de Cuña Demoníaca </> de Lunoherrera\n2. Completa <H>Encargos</> (excluyendo encargos del Manual de Noctoviajero)\n3. Interactúa con los residentes locales y completa <H>Misiones secundarias</>",
          TextMapId = "QuestDesc_10029901"
        },
        QuestDesc_10030101 = {
          ContentDE = "Tras días a la deriva en la oscuridad, tu conciencia finalmente comienza a despertar…",
          TextMapId = "QuestDesc_10030101"
        },
        QuestDesc_10030102 = {
          ContentDE = "Despiertas en el Santuario después de cinco días inconsciente. El primer rostro que ves es el de Camilla. Habla con ella, puede contarte lo que ocurrió mientras estabas fuera.",
          TextMapId = "QuestDesc_10030102"
        },
        QuestDesc_10030103 = {
          ContentDE = "Camilla te dice que fuiste {性别:el único|la única} sobreviviente del ataque de hace cinco días. En cuanto a los detalles, guarda silencio. En su lugar, sugiere ir al Asfódeo para escuchar la verdad de tus amigos preocupados.",
          TextMapId = "QuestDesc_10030103"
        },
        QuestDesc_10030104 = {
          ContentDE = "Las calles del Lago Glacial están adornadas con decoraciones festivas, pero extrañamente silenciosas. Algunos transeúntes apresurados pasan, la calma inquietante bajo la superficie es inconfundible. Si quieres la verdad, lo mejor es ir al Asfódeo y hablar con tus amigos.",
          TextMapId = "QuestDesc_10030104"
        },
        QuestDesc_10030105 = {
          ContentDE = "Rhythm también está investigando la Caza de Charon. Tras evaluar tus opciones, decides seguirla. Podría ser tu oportunidad de asegurar la paz en el Lago Glacial, y quizá aprender algo sobre Berenica de la Legión.",
          TextMapId = "QuestDesc_10030105"
        },
        QuestDesc_10030106 = {
          ContentDE = "Tú y Rhythm acuerdan unir fuerzas en el caso de la Caza de Charon. Primer paso: examinar la escena en busca de pistas que puedan llevar al culpable.",
          TextMapId = "QuestDesc_10030106"
        },
        QuestDesc_10030107 = {
          ContentDE = "Las pistas de la escena sugieren un vínculo con el teatro o la fábrica. Como capitán de los Noctoviajeros, lideras a tu escuadrón hacia el Teatro Galea, mientras Rhythm investiga la fábrica por su cuenta.",
          TextMapId = "QuestDesc_10030107"
        },
        QuestDesc_10030108 = {
          ContentDE = "Una anciana te hace señas desde lejos, probablemente la administradora del teatro. Habla con ella y ve si puedes obtener pistas sobre el caso.",
          TextMapId = "QuestDesc_10030108"
        },
        QuestDesc_10030109 = {
          ContentDE = "Doña Putsch parece más preocupada por el ensayo del Carnaval de la Vela de Plata que por el caso en curso. Tras un breve intercambio, regresa a su trabajo. Pero al menos no te impide mirar alrededor.\nEl maestro de utilería, encargado de todas las entregas de material, podría tener información más útil.",
          TextMapId = "QuestDesc_10030109"
        },
        QuestDesc_10030110 = {
          ContentDE = "Según el registro de utilería, la compañía ha estado ensayando sin parar todo el mes, nada sospechoso. Tu atención se dirige entonces a la elegante mujer en el escenario y al joven ansioso a su lado. Su actitud nerviosa despierta sospechas, ¿podría estar involucrado?",
          TextMapId = "QuestDesc_10030110"
        },
        QuestDesc_10030111 = {
          ContentDE = "La compañía parece carecer tanto de motivo como de oportunidad para cometer el crimen. Sin pistas útiles aquí, es momento de reagruparse y ver si Rhythm encontró algo en la fábrica.",
          TextMapId = "QuestDesc_10030111"
        },
        QuestDesc_10030112 = {
          ContentDE = "Rhythm te cuenta sobre un reciente robo de Phoxichor en la fábrica, el verdadero stock fue reemplazado con aceite de pescado. Eso explicaría las fuertes manchas de Phoxichor en el agresor. Ahora sospechas de los pescadores en las Pesquerías del Lago Glacial. Ve a la Zona Nebulosa y rastrea a los pescadores.",
          TextMapId = "QuestDesc_10030112"
        },
        QuestDesc_10030113 = {
          ContentDE = "Tomas el aceite de pescado de Rhythm y el gato inmediatamente se anima, ronroneando y moviendo la cola como si te invitara a seguirlo. Claramente quiere que lo sigas. Será mejor ver a dónde conduce.",
          TextMapId = "QuestDesc_10030113"
        },
        QuestDesc_10030114 = {
          ContentDE = "El gato te lleva directamente a un pescador visiblemente alterado. Antes de que puedas hablar, cae de rodillas, sollozando y rogando confesar. Algo no está bien, es momento de investigar más a fondo.",
          TextMapId = "QuestDesc_10030114"
        },
        QuestDesc_10030201 = {
          ContentDE = "Has llegado a las alcantarillas cerca de la fábrica. ¿Qué camino tomar ahora? Será mejor consultar a Rhythm, quizá tenga algunas ideas.",
          TextMapId = "QuestDesc_10030201"
        },
        QuestDesc_10030202 = {
          ContentDE = "A pocos pasos dentro de las alcantarillas, Outsider escucha de repente ruidos extraños más adelante. Lo mejor es avanzar con precaución.",
          TextMapId = "QuestDesc_10030202"
        },
        QuestDesc_10030203 = {
          ContentDE = "Gritos de auxilio resuenan por el túnel. Antes de que puedas reaccionar, Rhythm corre hacia el sonido. Mantente cerca y sigue su ejemplo.",
          TextMapId = "QuestDesc_10030203"
        },
        QuestDesc_10030204 = {
          ContentDE = "Has rescatado al primer civil atrapado y abierto la puerta sellada. Es momento de seguir adelante, aún hay alguien más que necesita ayuda.",
          TextMapId = "QuestDesc_10030204"
        },
        QuestDesc_10030205 = {
          ContentDE = "Según el civil, su compañero está justo más adelante. Muévete rápido.",
          TextMapId = "QuestDesc_10030205"
        },
        QuestDesc_10030206 = {
          ContentDE = "Escuchas al segundo civil llamando cerca. Apresúrate y revísalo.",
          TextMapId = "QuestDesc_10030206"
        },
        QuestDesc_10030207 = {
          ContentDE = "Ambos civiles están a salvo. Habla con Rhythm, ve cómo se encuentra después del rescate.",
          TextMapId = "QuestDesc_10030207"
        },
        QuestDesc_10030208 = {
          ContentDE = "Con las aguas residuales drenadas, puedes escuchar los gruñidos del agresor resonando en la oscuridad. Mantente alerta y sigue avanzando.",
          TextMapId = "QuestDesc_10030208"
        },
        QuestDesc_10030210 = {
          ContentDE = "Nadie esperaba que la Caza de Charon involucrara no a uno, sino a dos atacantes. Rhythm resultó gravemente herida al protegerte del segundo agresor. Con la llegada de refuerzos, la Legión se hará cargo de aquí en adelante. Tras discutirlo, los Noctoviajeros acuerdan visitarla en el centro médico, en parte por la recompensa, pero sobre todo para agradecerle por salvar tu vida.",
          TextMapId = "QuestDesc_10030210"
        },
        QuestDesc_10030211 = {
          ContentDE = "Nadie esperaba que la Caza de Charon involucrara no a uno, sino a dos atacantes. Rhythm resultó gravemente herida al protegerte del segundo agresor. Con la llegada de refuerzos, la Legión se hará cargo de aquí en adelante. Tras discutirlo, los Noctoviajeros acuerdan visitarla en el centro médico, en parte por la recompensa, pero sobre todo para agradecerle por salvar tu vida.",
          TextMapId = "QuestDesc_10030211"
        },
        QuestDesc_10030212 = {
          ContentDE = "La Legión prometió enviar una escolta, pero al llegar, no hay nadie a la vista. En cambio, las paredes están llenas de agujeros de bala, evidencia de un feroz tiroteo. Parece que los soldados apostados aquí se cruzaron con el culpable. Ya que vas a salir igual, lo mejor es seguir el rastro y ver a dónde conduce.",
          TextMapId = "QuestDesc_10030212"
        },
        QuestDesc_10030213 = {
          ContentDE = "Descubres un túnel probablemente usado por el atacante durante su escape. Conduce hasta la salida exterior de las alcantarillas. Avanza con cuidado.",
          TextMapId = "QuestDesc_10030213"
        },
        QuestDesc_10030214 = {
          ContentDE = "Una pesada e inquietante quietud llena el aire cerca del final de las alcantarillas. Algo claramente ocurrió aquí. Mantente alerta.",
          TextMapId = "QuestDesc_10030214"
        },
        QuestDesc_10030215 = {
          ContentDE = "La salida es una escena de carnicería. Restos de veneno — no estándar en las fuerzas imperiales — sugieren algo mucho más oscuro detrás de la Caza de Charon. Tras discutirlo, Outsider se queda para informar a la Legión. Tú y Snow siguen el plan y se dirigen al hospital para visitar a Rhythm.",
          TextMapId = "QuestDesc_10030215"
        },
        QuestDesc_10030216 = {
          ContentDE = "Días después, Rhythm finalmente despierta de su coma. Después de ponerla al tanto de todo lo ocurrido, te agradece y como gesto de gratitud, te pide recuperar un sello plateado de su base secreta. Aunque sigue en cama, planea escribir cartas personales a aliados de confianza, esperando reunir más noticias sobre Berenica para ti.",
          TextMapId = "QuestDesc_10030216"
        },
        QuestDesc_10030217 = {
          ContentDE = "Días después, Rhythm finalmente despierta de su coma. Después de ponerla al tanto de todo lo ocurrido, te agradece y como gesto de gratitud, te pide recuperar un sello plateado de su base secreta. Aunque sigue en cama, planea escribir cartas personales a aliados de confianza, esperando reunir más noticias sobre Berenica para ti.",
          TextMapId = "QuestDesc_10030217"
        },
        QuestDesc_10030218 = {
          ContentDE = "Has llegado a la base oculta de Rhythm. Revisa el lugar, el sello plateado con su nombre debería estar en algún sitio.",
          TextMapId = "QuestDesc_10030218"
        },
        QuestDesc_10030219 = {
          ContentDE = "Has llegado a la base oculta de Rhythm. Revisa el lugar, el sello plateado con su nombre debería estar en algún sitio.",
          TextMapId = "QuestDesc_10030219"
        },
        QuestDesc_100302sp101 = {
          ContentDE = "Dos civiles han quedado atrapados en las alcantarillas por un monstruo, probablemente el culpable de la Caza de Charon. Sin duda estás en el camino correcto. El monstruo se ha ido por ahora, así que concéntrate en desbloquear la puerta y poner a salvo a los civiles.",
          TextMapId = "QuestDesc_100302sp101"
        },
        QuestDesc_100302sp102 = {
          ContentDE = "Para reactivar la Consola de control, necesitas despejar las tuberías bloqueadas en esta área. Pero en cuanto el sistema de drenaje se activa, los Filthoids aparecen en masa. Resístelos y protege al civil.",
          TextMapId = "QuestDesc_100302sp102"
        },
        QuestDesc_100302sp103 = {
          ContentDE = "Todas las tuberías bloqueadas han sido despejadas. Intenta desbloquear la puerta otra vez.",
          TextMapId = "QuestDesc_100302sp103"
        },
        QuestDesc_100302sp104 = {
          ContentDE = "Para reactivar la Consola de control, necesitas despejar las tuberías bloqueadas en esta área. Pero en cuanto el sistema de drenaje se activa, los Filthoids aparecen en masa. Resístelos y protege al civil.",
          TextMapId = "QuestDesc_100302sp104"
        },
        QuestDesc_100302sp201 = {
          ContentDE = "El segundo civil está atrapado detrás de las defensas de las alcantarillas. Desactiva los mecanismos de seguridad desde la Consola de control y sácalo a salvo.",
          TextMapId = "QuestDesc_100302sp201"
        },
        QuestDesc_100302sp202 = {
          ContentDE = "El mismo problema otra vez, la Consola de control está sellada tras tuberías bloqueadas. Abre las válvulas, despeja la obstrucción y vuelve a poner el sistema en línea.",
          TextMapId = "QuestDesc_100302sp202"
        },
        QuestDesc_100302sp203 = {
          ContentDE = "El segundo civil está atrapado detrás de las defensas de las alcantarillas. Desactiva los mecanismos de seguridad desde la Consola de control y sácalo a salvo.",
          TextMapId = "QuestDesc_100302sp203"
        },
        QuestDesc_100302sp301 = {
          ContentDE = "El perpetrador de la Caza de Charon irrumpe con un rugido salvaje. Enfréntalo de una vez, es hora de terminar esto.",
          TextMapId = "QuestDesc_100302sp301"
        },
        QuestDesc_10030301 = {
          ContentDE = "De vuelta en la base secreta de Rhythm, encuentras el sello plateado junto con algunos recuerdos de su pasado. Mientras los revisas, algo cambia: quizá la distancia entre ustedes nunca fue tan grande como parecía. Lleva el sello de regreso y escucha lo que tiene que decir.",
          TextMapId = "QuestDesc_10030301"
        },
        QuestDesc_10030302 = {
          ContentDE = "Para evitar problemas innecesarios, conviene colaborar con las acciones de la 13.ª Legión en Lago Glacial por el momento.",
          TextMapId = "QuestDesc_10030302"
        },
        QuestDesc_10030303 = {
          ContentDE = "La Caza de Charon ha entrado en una nueva fase. Siguiendo las órdenes de Clive, te diriges a las alcantarillas bajo la Plaza de la Paz Plateada. Una vez allí, restablece contacto y espera más instrucciones.",
          TextMapId = "QuestDesc_10030303"
        },
        QuestDesc_10030304 = {
          ContentDE = "Después de que terminas de actualizar a Rhythm sobre Berry, la comandante Lynn de la 13.ª Legión irrumpe en la sala. Anuncia sin rodeos que su unidad tomará el control de la Caza de Charon. Afortunadamente, parece no estar al tanto de tus vínculos con Sibylle e incluso ofrece cooperar. No es momento de levantar sospechas. Lo mejor es aparentar cooperación por ahora.",
          TextMapId = "QuestDesc_10030304"
        },
        QuestDesc_100303sp101 = {
          ContentDE = "Has acordado ayudar en la investigación de la Caza de Charon. Lynn te asigna tu primera tarea: reunirte con Clive de la 13.ª Legión fuera de Lago Glacial y ayudar a procesar los suministros entrantes.",
          TextMapId = "QuestDesc_100303sp101"
        },
        QuestDesc_100303sp102 = {
          ContentDE = "Varios días después, finalmente completas las tareas de la 13.ª Legión. Pero Rhythm no aparece en el punto de encuentro acordado. ¿Pudo haber pasado algo? Revisa el área y asegúrate de que esté a salvo.",
          TextMapId = "QuestDesc_100303sp102"
        },
        QuestDesc_100303sp103 = {
          ContentDE = "Para ayudar a los pobladores cuyos hogares fueron afectados por la 13.ª Legión, Rhythm está reuniendo suministros esenciales. Como su aliado, te ofreces a ayudar.",
          TextMapId = "QuestDesc_100303sp103"
        },
        QuestDesc_100303sp104 = {
          ContentDE = "Pesca completada. Ya tienes todo lo que la gente necesita, es hora de entregar los bienes.",
          TextMapId = "QuestDesc_100303sp104"
        },
        QuestDesc_100303sp105 = {
          ContentDE = "Apenas entregas los suministros a Margie, llega una nueva orden de Clive. Parece que la 13.ª Legión está en movimiento, sal y repórtate.",
          TextMapId = "QuestDesc_100303sp105"
        },
        QuestDesc_100303sp201 = {
          ContentDE = "Soldados de la 13.ª Legión patrullan las alcantarillas, cada uno en su sección asignada. Los túneles están cargados de tensión. Dirígete al área que Clive designó para los Noctoviajeros.",
          TextMapId = "QuestDesc_100303sp201"
        },
        QuestDesc_100303sp202 = {
          ContentDE = "Soldados de la 13.ª Legión patrullan las alcantarillas, cada uno en su sección asignada. Los túneles están cargados de tensión. Dirígete al área que Clive designó para los Noctoviajeros.",
          TextMapId = "QuestDesc_100303sp202"
        },
        QuestDesc_100303sp203 = {
          ContentDE = "El área asignada por Clive está inaccesible, la Consola de control está bloqueada por aguas residuales. Drena el sistema para levantar el bloqueo y avanzar a tu sector.",
          TextMapId = "QuestDesc_100303sp203"
        },
        QuestDesc_100303sp204 = {
          ContentDE = "Tras algunos retrasos, finalmente accedes al área asignada por Clive. Avanza rápido.",
          TextMapId = "QuestDesc_100303sp204"
        },
        QuestDesc_100303sp205 = {
          ContentDE = "Intentas reportarte con Clive tras inspeccionar el área, pero el terminal de Rhythm falla, cortando el mensaje. Ve si puedes arreglarlo.",
          TextMapId = "QuestDesc_100303sp205"
        },
        QuestDesc_100303sp206 = {
          ContentDE = "En cuanto la radio vuelve a funcionar, te enteras de que el perpetrador ha roto el bloqueo de la Legión y viene hacia ti. Afortunadamente, Lynn llega con refuerzos. Ahora acaba con esto.",
          TextMapId = "QuestDesc_100303sp206"
        },
        QuestDesc_10030401 = {
          ContentDE = "Aunque la Legión declaró el caso cerrado y regresó triunfante a la capital, tú y Rhythm saben la verdad: está lejos de terminar.",
          TextMapId = "QuestDesc_10030401"
        },
        QuestDesc_10030402 = {
          ContentDE = "Revisando las pistas hasta ahora, sospechas que el asesino tenía una conexión con la ópera. Esa inquietante melodía que tarareó podría provenir de un aria, identificarla podría acotar la búsqueda. El hermano menor de Rhythm, Blues, es un fanático de la ópera. Dejó una colección de cintas de casete en su base secreta. Es una posibilidad remota, pero vale la pena intentarlo.",
          TextMapId = "QuestDesc_10030402"
        }
      }
    end
  },
  {
    MinKey = "QuestDesc_10030403",
    MaxKey = "QuestName_10030208",
    Loader = function()
      return {
        QuestDesc_10030403 = {
          ContentDE = "Ahora viene la parte difícil. Es momento de poner a prueba tu memoria y tu oído, una cinta a la vez.",
          TextMapId = "QuestDesc_10030403"
        },
        QuestDesc_10030404 = {
          ContentDE = "Las horas pasan mientras revisas las grabaciones. Rhythm ha salido a tomar aire. La búsqueda es lenta, tediosa y agotadora. Por ahora, toma un descanso. Ve a ver cómo está.",
          TextMapId = "QuestDesc_10030404"
        },
        QuestDesc_10030501 = {
          ContentDE = "Nunca hubo gloria en convertirse en un Charon Laureado, el título no era más que un señuelo. Lo que esperaba en la ciudad interior era la fría mesa de operaciones de la Academia de Alquimia. Ahora, como monstruo, lo único que puedes hacer es obedecer.",
          TextMapId = "QuestDesc_10030501"
        },
        QuestDesc_10030502 = {
          ContentDE = "Ya no eres humano. No tienes pensamientos ni elección. Dirígete al campo de pruebas. Elimina al objetivo.",
          TextMapId = "QuestDesc_10030502"
        },
        QuestDesc_10030503 = {
          ContentDE = "Ya no eres humano. No tienes pensamientos ni elección. Dirígete al campo de pruebas. Elimina al objetivo.",
          TextMapId = "QuestDesc_10030503"
        },
        QuestDesc_10030504 = {
          ContentDE = "Ya no eres humano. No tienes pensamientos ni elección. Dirígete al campo de pruebas. Elimina al objetivo.",
          TextMapId = "QuestDesc_10030504"
        },
        QuestDesc_10030505 = {
          ContentDE = "Ya no eres humano. No tienes pensamientos ni elección. Dirígete al campo de pruebas. Elimina al objetivo.",
          TextMapId = "QuestDesc_10030505"
        },
        QuestDesc_10030506 = {
          ContentDE = "Ese ingenuo tonto realmente lo logró… No hay vuelta atrás. Sal y hazlo como humano.",
          TextMapId = "QuestDesc_10030506"
        },
        QuestDesc_10030507 = {
          ContentDE = "Ese ingenuo tonto realmente lo logró… No hay vuelta atrás. Sal y hazlo como humano.",
          TextMapId = "QuestDesc_10030507"
        },
        QuestDesc_10030508 = {
          ContentDE = "Ese ingenuo tonto realmente lo logró… No hay vuelta atrás. Sal y hazlo como humano.",
          TextMapId = "QuestDesc_10030508"
        },
        QuestDesc_10030601 = {
          ContentDE = "El título de Charon Laureado no es más que una cruel farsa. No puedes dejar que Rhythm persiga un sueño tejido con engaños. Dile la verdad sobre la Academia de Alquimia… y luego haz lo que deba hacerse.",
          TextMapId = "QuestDesc_10030601"
        },
        QuestDesc_10030602 = {
          ContentDE = "En el Teatro Galea, el Carnaval de la Vela de Plata está en pleno auge. El lugar bulle con máscaras y disfraces extravagantes, el velo perfecto para un monstruo como tú. Escabúllete entre la fiesta y encuentra a tu contacto.",
          TextMapId = "QuestDesc_10030602"
        },
        QuestDesc_10030603 = {
          ContentDE = "Han pasado días desde la partida de la 13.ª Legión. Rhythm parece recuperarse — aunque apenas — de la pérdida de Blues. Puede que aún tenga más que decir. Ve y escucha.",
          TextMapId = "QuestDesc_10030603"
        },
        QuestDesc_10030604 = {
          ContentDE = "La Caza de Charon ha terminado. El alcance de los Abandonados en la Región Cocytus ha sido cortado. Pero esto no es un final, solo la próxima calma antes de la tormenta.",
          TextMapId = "QuestDesc_10030604"
        },
        QuestDesc_1003plus01 = {
          ContentDE = "Entre el dolor persistente y las despedidas, el largo día finalmente llega a su fin.\nEl sueño te evade esta noche, quizá un paseo tranquilo por la ciudad te ayude a despejar la mente.",
          TextMapId = "QuestDesc_1003plus01"
        },
        QuestDesc_1003plus02 = {
          ContentDE = "Te enteras por Outsider y Snow que quedaste atrapado en la Caza de Charon, una serie de asesinatos ocurridos hace cinco días. Antes de que puedas asimilarlo, Rhythm aparece sin previo aviso y termina abruptamente la conversación. Ya no puedes evitarla, lo mejor es escuchar lo que tiene que decir.",
          TextMapId = "QuestDesc_1003plus02"
        },
        QuestDesc_1003plus03 = {
          ContentDE = "Has reunido varias pistas prometedoras, todas posiblemente vinculadas a la Caza de Charon. Cuando el rastro se enfríe, intenta combinarlas. Podría surgir una nueva pista.",
          TextMapId = "QuestDesc_1003plus03"
        },
        QuestDesc_1003plus04 = {
          ContentDE = "Tú y Rhythm acuerdan unir fuerzas en el caso de la Caza de Charon. Primer paso: examinar la escena en busca de pistas que puedan llevar al culpable.",
          TextMapId = "QuestDesc_1003plus04"
        },
        QuestDesc_1003plus05 = {
          ContentDE = "Una fila de carteles gigantes en la entrada del teatro llama inmediatamente tu atención. Podrían arrojar luz sobre hechos recientes, vale la pena revisarlos.",
          TextMapId = "QuestDesc_1003plus05"
        },
        QuestDesc_1003plus06 = {
          ContentDE = "El maestro de utilería niega rotundamente que la cortina encontrada en la escena provenga del Teatro Galea. Afirma que todos los objetos están cuidadosamente registrados y una lista firmada por varios miembros del personal lo respalda. Mejor échale un vistazo tú mismo.",
          TextMapId = "QuestDesc_1003plus06"
        },
        QuestDesc_1003plus07 = {
          ContentDE = "Un actor cansado explica que la compañía ha estado ensayando sin parar para el próximo Carnaval de la Vela de Plata. Una hoja de asistencia cercana registra las horas de ensayo de todos,revísala.",
          TextMapId = "QuestDesc_1003plus07"
        },
        QuestDesc_1003plus08 = {
          ContentDE = "Al terminar de revisar el registro, un sonido desde arriba atrae tu atención. Ve a echar un vistazo.",
          TextMapId = "QuestDesc_1003plus08"
        },
        QuestDesc_1003plus09 = {
          ContentDE = "Has llegado a los dormitorios de los pescadores. Es momento de una inspección puerta por puerta.",
          TextMapId = "QuestDesc_1003plus09"
        },
        QuestDesc_1003plus10 = {
          ContentDE = "Nadie responde, pero un gato aparece detrás de ti, maullando con urgencia como si hubiera captado un rastro. Podría valer la pena seguirlo.",
          TextMapId = "QuestDesc_1003plus10"
        },
        QuestDesc_1003plus11 = {
          ContentDE = "Has atrapado al ladrón de Phoxichor, pero no es el asesino. Aun así, te da una pista: el culpable podría estar escondido en las alcantarillas. Entrégalo a la Oficina de Seguridad y luego reúnete con Rhythm para decidir el siguiente paso.",
          TextMapId = "QuestDesc_1003plus11"
        },
        QuestDesc_1003plus12 = {
          ContentDE = "Con el pescador entregado, te unes a Rhythm en las alcantarillas para rastrear al verdadero sospechoso. Solo cuando hayas confirmado su paradero podrá llamar a la 6ª Legión y poner fin a la Caza de Charon.",
          TextMapId = "QuestDesc_1003plus12"
        },
        QuestDesc_1003plus13 = {
          ContentDE = "Has puesto a salvo a los civiles, pero justo cuando llega el alivio, un rugido monstruoso surge desde abajo. Parece la criatura de la que te advirtieron. Drena las aguas residuales y continúa la persecución.",
          TextMapId = "QuestDesc_1003plus13"
        },
        QuestDesc_1003plus14 = {
          ContentDE = "Unos días después, Rhythm finalmente despierta. Ponla al tanto de lo ocurrido mientras estaba inconsciente.",
          TextMapId = "QuestDesc_1003plus14"
        },
        QuestDesc_1003plus15 = {
          ContentDE = "Has llegado a la base oculta de Rhythm. Revisa el lugar, el sello plateado con su nombre debería estar en algún sitio.",
          TextMapId = "QuestDesc_1003plus15"
        },
        QuestDesc_1003plus16 = {
          ContentDE = "Has llegado a la base oculta de Rhythm. Revisa el lugar, el sello plateado con su nombre debería estar en algún sitio.",
          TextMapId = "QuestDesc_1003plus16"
        },
        QuestDesc_1003plus17 = {
          ContentDE = "Soldados de la 13.ª Legión patrullan las alcantarillas, cada uno en su sección asignada. Los túneles están cargados de tensión. Dirígete al área que Clive designó para los Noctoviajeros.",
          TextMapId = "QuestDesc_1003plus17"
        },
        QuestDesc_1003plus18 = {
          ContentDE = "Has llegado al sector que Clive asignó a tu equipo. Examina con cuidado y evalúa el entorno.",
          TextMapId = "QuestDesc_1003plus18"
        },
        QuestDesc_1003plus19 = {
          ContentDE = "Repasa las pistas reunidas, alguna podría señalar la identidad del asesino. Con ojos frescos, quizá el eslabón perdido se revele.",
          TextMapId = "QuestDesc_1003plus19"
        },
        QuestDesc_1003plus20 = {
          ContentDE = "Rhythm tararea una melodía, inquietantemente similar a la que el asesino cantó esa noche. Es de <I>Niños del campo de nieve</>, una ópera muy conocida. Estaban discutiendo cómo usar esa pista para atraer al asesino… pero parece que él vino primero.",
          TextMapId = "QuestDesc_1003plus20"
        },
        QuestDesc_1003plus20_1 = {
          ContentDE = "Rhythm tararea una melodía, inquietantemente similar a la que el asesino cantó esa noche. Es de <I>Niños del campo de nieve</>, una ópera muy conocida. Estaban discutiendo cómo usar esa pista para atraer al asesino… pero parece que él vino primero.",
          TextMapId = "QuestDesc_1003plus20_1"
        },
        QuestDesc_1003plus21 = {
          ContentDE = "En el Teatro Galea, el Carnaval de la Vela de Plata está en pleno auge. El lugar bulle con máscaras y disfraces extravagantes, el velo perfecto para un monstruo como tú. Escabúllete entre la fiesta y encuentra a tu contacto.",
          TextMapId = "QuestDesc_1003plus21"
        },
        QuestDesc_1003plus22 = {
          ContentDE = "Tu contacto de los Abandonados debería estar cerca. Ve y haz la cita.",
          TextMapId = "QuestDesc_1003plus22"
        },
        QuestDesc_1003plus23 = {
          ContentDE = "Los Abandonados son otra amenaza latente para esta ciudad. Elimínalos.",
          TextMapId = "QuestDesc_1003plus23"
        },
        QuestDesc_1003plus24 = {
          ContentDE = "Justo cuando termina la batalla, soldados de la 13.ª Legión irrumpen. Si quieren pelea, la tendrán ninguno saldrá con vida.",
          TextMapId = "QuestDesc_1003plus24"
        },
        QuestDesc_1003plus25 = {
          ContentDE = "No sabes cómo Rhythm y los Phoxcazadores te rastrearon, pero no hay tiempo para pensarlo. La Legión aún está aquí, y la batalla no ha terminado.",
          TextMapId = "QuestDesc_1003plus25"
        },
        QuestDesc_1003plus26 = {
          ContentDE = "Tu actuación como Blues fue impecable. Rhythm nunca sabrá que mató a su propio hermano. Ni la 13.ª Legión ni los Abandonados vincularán la masacre con ella o los Phoxcazadores.\nPero el telón de ese papel ha caído. Es hora de subir al escenario una última vez. Esta vez, como Parsifal.",
          TextMapId = "QuestDesc_1003plus26"
        },
        QuestDesc_1003plus27 = {
          ContentDE = "Que se levante el telón y con él, que todo termine.",
          TextMapId = "QuestDesc_1003plus27"
        },
        QuestDesc_1003plus28 = {
          ContentDE = "El ruido de drenar las aguas residuales ha atraído a una horda de Filthoids. Ahuyéntalos.",
          TextMapId = "QuestDesc_1003plus28"
        },
        QuestDesc_1003plus29 = {
          ContentDE = "El ruido de drenar las aguas residuales ha atraído a una horda de Filthoids. Ahuyéntalos.",
          TextMapId = "QuestDesc_1003plus29"
        },
        QuestDesc_1003plus30 = {
          ContentDE = "El área asignada por Clive está inaccesible, la Consola de control está bloqueada por aguas residuales. Drena el sistema para levantar el bloqueo y avanzar a tu sector.",
          TextMapId = "QuestDesc_1003plus30"
        },
        QuestDesc_1003plus31 = {
          ContentDE = "Rhythm parece tener preguntas sobre el Phoxichor hallado en la nieve. Habla con ella y comparte tus hallazgos, podría llevar a nuevos descubrimientos.",
          TextMapId = "QuestDesc_1003plus31"
        },
        QuestDesc_1003plus32 = {
          ContentDE = "Tras una breve búsqueda, no se encuentra nada relevante cerca del corredor de entrada. Avanza más adentro y habla con el personal del Teatro Galea.",
          TextMapId = "QuestDesc_1003plus32"
        },
        QuestDesc_1003plus33 = {
          ContentDE = "Siguiendo los gritos de auxilio, encuentras al segundo ciudadano atrapado. Busca la manera de liberarlo.",
          TextMapId = "QuestDesc_1003plus33"
        },
        QuestDesc_1003plus34 = {
          ContentDE = "Tras un breve intercambio, decides cooperar con la 13.ª Legión. Ahora escucha las órdenes de la comandante Lynn.",
          TextMapId = "QuestDesc_1003plus34"
        },
        QuestDesc_1003plus35 = {
          ContentDE = "Cuando te encuentras con Clive, ya está ahuyentando Lobos de Nieve cerca del punto de entrega. Ayúdalo a asegurar el área y espera juntos a la cuadrilla de suministros.",
          TextMapId = "QuestDesc_1003plus35"
        },
