        RESOURCE_DESC_103 = {
          ContentDE = "Sanergie, die zum Abschließen von Missionen verbraucht wird.",
          TextMapId = "RESOURCE_DESC_103"
        },
        RESOURCE_DESC_105 = {
          ContentDE = "Eine seltene Währung, die gegen verschiedene Belohnungen eingetauscht werden kann. Nur während des zweiten geschlossenen Betatests verwendbar.",
          TextMapId = "RESOURCE_DESC_105"
        },
        RESOURCE_DESC_110 = {
          ContentDE = "Ein Kaleidoskop, das ein schillerndes Lichtspektrum reflektiert. Wenn ein einziger Lichtsplitter von Augen in der Dunkelheit eingefangen wird, setzt es unzählige Welten in Bewegung.",
          TextMapId = "RESOURCE_DESC_110"
        },
        RESOURCE_DESC_11001 = {
