        RLBlessingGroup_Desc_1 = {
          ContentDE = "Mejoras de armas cuerpo a cuerpo",
          TextMapId = "RLBlessingGroup_Desc_1"
        },
        RLBlessingGroup_Desc_101 = {
          ContentDE = "Cada Mecha de este conjunto otorga + <Highlight>15%</> de Prob. CRIT y + <Highlight>15%</> de Daño CRIT para armas cuerpo a cuerpo.\nInfligir daño con armas cuerpo a cuerpo tiene un <Highlight>10%</> de probabilidad de aplicar 1 acumulación de [Llama fundida].",
          TextMapId = "RLBlessingGroup_Desc_101"
        },
        RLBlessingGroup_Desc_102 = {
          ContentDE = "[Llama fundida] inflige un <Highlight>35%</> del ATQ del personaje como daño periódico cada <Highlight>1</>s.",
          TextMapId = "RLBlessingGroup_Desc_102"
        },
        RLBlessingGroup_Desc_103 = {
          ContentDE = "Extiende la duración de [Llama fundida] a <Highlight>10</> s. Ahora se acumula hasta <Highlight>20</> veces.",
          TextMapId = "RLBlessingGroup_Desc_103"
        },
        RLBlessingGroup_Desc_104 = {
          ContentDE = "Los objetivos afectados con [Llama fundida] sufren un golpe de [Sable de llama fundida] cada <Highlight>5</> s. Infligir daño con armas cuerpo a cuerpo tiene un <Highlight>10%</> de probabilidad de activar un [Sable de llama fundida] adicional.",
          TextMapId = "RLBlessingGroup_Desc_104"
        },
        RLBlessingGroup_Desc_2 = {
          ContentDE = "Mejoras de armas a distancia",
          TextMapId = "RLBlessingGroup_Desc_2"
        },
        RLBlessingGroup_Desc_201 = {
          ContentDE = "Cada Mecha de este conjunto otorga + <Highlight>15%</> de Prob. CRIT y + <Highlight>15%</> de Daño CRIT para armas a distancia.\nAumenta el Rango de Recogida Automática. Otorga inmunidad al Aturdimiento durante <Highlight>3</> s después de recoger botín.",
          TextMapId = "RLBlessingGroup_Desc_201"
        },
        RLBlessingGroup_Desc_202 = {
          ContentDE = "Infligir daño con cualquier arma a distancia activa [Luna marina] y genera <Highlight>3</> [Mini Lunas marinas] adicionales (máximo una vez cada <Highlight>10</> s).",
          TextMapId = "RLBlessingGroup_Desc_202"
        },
        RLBlessingGroup_Desc_203 = {
          ContentDE = "Al recolectar una [Mini Luna marina] se obtiene 1 [Luna velada].",
          TextMapId = "RLBlessingGroup_Desc_203"
        },
        RLBlessingGroup_Desc_204 = {
          ContentDE = "Al consumir [Luna velada] se disparan <Highlight>3</> [Aguijones] en una dispersión en forma de abanico. Recoger botín otorga 1 acumulación de [Deriva fantasma].",
          TextMapId = "RLBlessingGroup_Desc_204"
        },
        RLBlessingGroup_Desc_3 = {
          ContentDE = "Mejoras de habilidades",
          TextMapId = "RLBlessingGroup_Desc_3"
        },
        RLBlessingGroup_Desc_301 = {
          ContentDE = "Cada Mecha de este conjunto otorga + <Highlight>15%</> de Escudo máximo.\nDaño de Habilidad +<Highlight>25%</>.",
          TextMapId = "RLBlessingGroup_Desc_301"
        },
        RLBlessingGroup_Desc_302 = {
          ContentDE = "Obtiene 1 acumulación de <Highlight>[Destello]</> por segundo (máx. 60). Con 60 acumulaciones, lanzar una habilidad consume todo el <Highlight>[Destello]</> y otorga [Resplandor] durante <Highlight>10 s</>, lo que aumenta el Daño de Habilidad en un <Highlight>50%</>.",
          TextMapId = "RLBlessingGroup_Desc_302"
        },
        RLBlessingGroup_Desc_303 = {
          ContentDE = "Mientras está bajo [Resplandor], activa 1 [Emisión] cada 2 s, lo que inflige Daño de Habilidad equivalente al <Highlight>810%</> del ATQ del personaje a los enemigos dentro de <Highlight>6</> m.",
          TextMapId = "RLBlessingGroup_Desc_303"
        },
        RLBlessingGroup_Desc_304 = {
          ContentDE = "Extiende [Resplandor] a <Highlight>20</> s.",
          TextMapId = "RLBlessingGroup_Desc_304"
        },
        RLBlessingGroup_Desc_4 = {
          ContentDE = "Invocaciones especializadas",
          TextMapId = "RLBlessingGroup_Desc_4"
        },
        RLBlessingGroup_Desc_401 = {
          ContentDE = "Cada Mecha de este conjunto otorga + <Highlight>15%</> de Daño de invocación.\nInvocar una invocación que no sea Lumiramita también invoca 1 [Lumisemilla].\n[Lumisemilla]: Explota cuando un enemigo entra en un radio de <Highlight>3</> m, infligiendo daño equivalente al <Highlight>600%</> del ATQ. Dura <Highlight>10</> s y puede haber hasta 10 simultáneamente.",
          TextMapId = "RLBlessingGroup_Desc_401"
        },
        RLBlessingGroup_Desc_402 = {
          ContentDE = "Cada [Lumisemilla] tiene un <Highlight>40%</> de posibilidades de evolucionar a [Lumihoja] cuando es invocada.\n[Lumihoja]: Explota cuando un enemigo se acerca a <Highlight>3</> m, infligiendo <Highlight>1000%</> del ATQ. Dura <Highlight>10</> s y puede haber hasta 10 simultáneamente.",
          TextMapId = "RLBlessingGroup_Desc_402"
        },
        RLBlessingGroup_Desc_403 = {
          ContentDE = "[Lumihoja] invoca un [Lumiárbol] al explotar. Cuando es sanado, inflige a los enemigos dentro de un radio de 6 m un daño equivalente al <Highlight>4000%</> de los PV restaurados.\n[Lumiárbol]: Cura a los aliados en un radio de <Highlight>10</> m por un <Highlight>5%</> de sus PV Máx. por segundo. Dura <Highlight>10</> s; solo puede existir 1.",
          TextMapId = "RLBlessingGroup_Desc_403"
        },
        RLBlessingGroup_Desc_404 = {
          ContentDE = "Duplica la probabilidad de todos los efectos que pueden invocar [Lumisemilla]. [Lumiárbol] inflige <Highlight>650%</> del ATQ como daño por segundo a los enemigos dentro de su alcance.",
          TextMapId = "RLBlessingGroup_Desc_404"
        },
        RLBlessingGroup_Desc_5 = {
          ContentDE = "Mejoras de movilidad",
          TextMapId = "RLBlessingGroup_Desc_5"
        }
      }
    end
  },
