        RLTreasureGroup_Desc_102 = {
          ContentDE = "Con los <Highlight>3</> Artefactos del [Pacto del Dios de la Abundancia] recolectados, tu personaje obtiene un aumento de Daño del <Highlight>10%</> por cada <Highlight>100</> Brasas que posea.\nSi las Brasas están por debajo de <Highlight>200</>, reduce el Daño Recibido en <Highlight>30%</>.",
          TextMapId = "RLTreasureGroup_Desc_102"
