        },
        RLTreasureGroup_Desc_105 = {
          ContentDE = "Con los <Highlight>2</> Artefactos de [Hechicera desolada] recolectados, aumenta la reducción de [Postura] en un <Highlight>100%</> y el Daño Infligido a los enemigos bajo [Retribución de Ask] en un <Highlight>100%</>",
          TextMapId = "RLTreasureGroup_Desc_105"
