        SCEREAD_NAME_1000001 = {
          ContentDE = "{空格}",
          TextMapId = "SCEREAD_NAME_1000001"
        },
        SCEREAD_NAME_1000002 = {
          ContentDE = "{空格}",
          TextMapId = "SCEREAD_NAME_1000002"
        },
        SCEREAD_TEXT_1000001 = {
          ContentDE = "Schwarzer Drache wütet, trübe Fluten breiten sich aus; Tag und Nacht geraten aus der Ordnung, die Temperaturen stürzen jäh.\n Gras und Bäume welken, jegliches Leben bricht ab; Felsgestein zerberstet, Himmel und Erde verfärben sich.\n Die einfachen Menschen von Schilf und Ufer bangen um ihre Heimat; die Sternenweber-Getreuen stellen sich gemeinsam der Not.\n Sie schmolzen Erz, schmiedeten Eisen, errichteten diesen Turm und entzündeten sein Rauchwerk; wohlriechender Wind erfüllte die Luft, trübes Miasma ward gelöst.\n Wacht stets über diesen Turm, lasst den Duft nicht erlöschen; pflegt ihn regelmäßig, so bleibt diese Gegend sicher.\n Sollte Zhuyin sich regen, kehrt das Unheil zurück; so lange auch das Glück währt, dem Turm wird am Ende die Kraft versiegen.\n Darum ist dies hier niedergeschrieben, als Mahnung für die Späteren: Wenn ihr abermals diese Heimsuchung trefft, so sucht nach neuen Wegen.\n Mit vereinten Herzen schirmt Flüsse und Auen; bewahrt Huaxu auf ewig, Frieden für alle Generationen.",
          TextMapId = "SCEREAD_TEXT_1000001"
        },
        SCEREAD_TEXT_1000002 = {
          ContentDE = "Durch Eid und Dekret rufen wir die Verlorenen herbei: Beendet euer endloses Irren; macht euch auf und eilt ins Reich der Glückseligkeit ...\n Diese Inschrift hält fest:\n Gui (Dorffrau; auf der Flucht von Zobel-Bi’an erschlagen.)\n Chuntao (Weberin; ihr Heim wurde überrannt, sie wurde darin erschlagen.)\n Li Erlang (Bauer; bei der Feldarbeit von Zobel-Bi’an erschlagen.)\n Xiao Xiaosan (Schreibjunge; auf der Flucht vom Lehrer getrennt, starb nach einem Irrgang in die Gritblight-Ebene)\n ...",
          TextMapId = "SCEREAD_TEXT_1000002"
        },
        SKILL_100001_DESC = {
          ContentDE = "<H>[Disponible solo al desplegarse como Compañero de combate]</>\nAumenta el ATQ propio y de sus aliados.",
          TextMapId = "SKILL_100001_DESC"
        },
        SKILL_100001_NAME = {
          ContentDE = "Asalto",
          TextMapId = "SKILL_100001_NAME"
        },
        SKILL_100003_DESC = {
          ContentDE = "<H>[Disponible solo al desplegarse como Compañero de combate]</>\nAumenta el Daño de Habilidad propio y de sus aliados.",
