        },
        SKILL_100009_DESC = {
          ContentDE = "<H>[Disponible solo al desplegarse como Compañero de combate]</>\nAumenta la Prob. CRIT propia y de sus aliados.",
          TextMapId = "SKILL_100009_DESC"
        },
        SKILL_100009_NAME = {
