        },
        SKILL_10101_DESC = {
          ContentDE = "ATQ del personaje +<H>#1</>.",
          TextMapId = "SKILL_10101_DESC"
        },
        SKILL_10102_DESC = {
          ContentDE = "Probabilidad de Activación +<H>#1</>. Cuando un personaje Hydro activa un efecto extra con esta arma, los demás aliados obtienen ATQ +<H>#2</> durante <H>#3</> s.",
          TextMapId = "SKILL_10102_DESC"
        },
        SKILL_10103_DESC = {
          ContentDE = "Rango de ATQ +<H>#1</>. Al acertar un Daño CRIT con esta arma, hay <H>#2</> de probabilidad de restaurar <H>#3</> de Cordura. Se activa como máximo cada <H>#4</> s.",
          TextMapId = "SKILL_10103_DESC"
        },
        SKILL_10104_DESC = {
          ContentDE = "DEF +<H>#1</>. Al infligir daño con esta arma y activar un efecto extra, hay <H>#3</> de probabilidad de reducir el escudo del objetivo en un valor equivalente al <H>#2</> de la DEF del usuario.",
          TextMapId = "SKILL_10104_DESC"
        },
        SKILL_10105_DESC = {
          ContentDE = "Velocidad de Ataque +<H>#1</>. Al realizar un Ataque Cargado con esta arma, hay <H>#2</> de probabilidad de reducir el enfriamiento del apoyo de Geniemon en <H>#3</> s.",
          TextMapId = "SKILL_10105_DESC"
