        },
        TARGET_DUNGEON_DEFENCE_108 = {
          ContentDE = "Beschütze die <Highlight>Luno-Abenteurerin</> vor den <Highlight>drei Wellen</> der gegnerischen Angriffe. Die Mission scheitert, wenn das Gerät, das sie überprüft, zerstört wird.",
