        },
        TARGET_DUNGEON_DEFENCE_109 = {
          ContentDE = "Du kannst wählen, ob du nach jeweils drei Wellen evakuieren oder weitermachen möchtest.",
          TextMapId = "TARGET_DUNGEON_DEFENCE_109"
        },
        TARGET_DUNGEON_DEFENCE_110 = {
          ContentDE = "Beschütze die <H>Luno-Abenteurerin</>, bis der Countdown endet. Die Mission scheitert, wenn das Gerät, das sie überprüft, zerstört wird.",
          TextMapId = "TARGET_DUNGEON_DEFENCE_110"
        },
        TARGET_DUNGEON_DEFENCE_111 = {
          ContentDE = "Nachdem du die Luno-Abenteurerin eine Zeit lang erfolgreich verteidigt hast, kannst du wählen, ob du dich zurückziehen oder weitermachen willst.",
