        TextMap_AnswerDetail_100003 = {
          ContentDE = "El retazo de telón apunta al Teatro Galea, y el inquietante tarareo operático del agresor refuerza el vínculo. El teatro merece una búsqueda exhaustiva.",
          TextMapId = "TextMap_AnswerDetail_100003"
        },
        TextMap_AnswerDetail_100004 = {
          ContentDE = "El agresor huyó al suroeste y la única instalación en esa dirección con grandes reservas de Phoxichor es la fábrica local. Merece una búsqueda exhaustiva.",
          TextMapId = "TextMap_AnswerDetail_100004"
        },
        TextMap_AnswerDetail_100005 = {
          ContentDE = "El escondite del agresor estaba decorado con utilería teatral, y durante el ataque tarareó una melodía operática. Estas pistas sugieren que podría ser un entusiasta de la ópera. La melodía misma podría ser la clave de su identidad.",
          TextMapId = "TextMap_AnswerDetail_100005"
        },
        TextMap_AnswerDetail_100101 = {
          ContentDE = "Basado en la posición de la luna en el momento del incidente, se estima que el ataque ocurrió entre las 4 y las 5 de la mañana.",
          TextMapId = "TextMap_AnswerDetail_100101"
        },
        TextMap_AnswerDetail_100201 = {
          ContentDE = "La veleta rota probablemente se quebró cuando el agresor aterrizó en el tejado. Junto con otras pistas, podría aportar más información.",
          TextMapId = "TextMap_AnswerDetail_100201"
        },
        TextMap_AnswerDetail_100202 = {
          ContentDE = "Base de la veleta doblada apunta al suroeste. Junto con otras pistas, podría aportar más información.",
          TextMapId = "TextMap_AnswerDetail_100202"
        },
        TextMap_AnswerDetail_100203 = {
          ContentDE = "El patrón de ruptura y la base doblada confirman que se desprendió durante la fuga por los tejados.\nLa veleta ensamblada apunta al suroeste, confirmando la dirección de huida.",
          TextMapId = "TextMap_AnswerDetail_100203"
        },
        TextMap_AnswerDetail_100301 = {
          ContentDE = "Esa noche, el agresor tarareó una melodía operática con una voz áspera. ¿Podría ser un cantante, o simplemente un amante de la música?",
          TextMapId = "TextMap_AnswerDetail_100301"
        },
        TextMap_AnswerDetail_100302 = {
          ContentDE = "Un retazo de terciopelo de telón fue hallado en la escena del crimen, idéntico al usado en el Teatro Galea. ¿Podría esto señalar la implicación del teatro? Se necesita más evidencia para confirmar el vínculo.",
          TextMapId = "TextMap_AnswerDetail_100302"
        },
        TextMap_AnswerDetail_100303 = {
          ContentDE = "El retazo de telón apunta al Teatro Galea, y el tarareo operático del agresor refuerza la conexión. El teatro merece una búsqueda exhaustiva.",
          TextMapId = "TextMap_AnswerDetail_100303"
        },
        TextMap_AnswerDetail_100401 = {
          ContentDE = "El agresor huyó al suroeste, un área densa con casas, escuelas y una fábrica. La investigación de Rhythm se ha estancado, ya que la zona es demasiado amplia sin más pistas. Se necesitan más indicios para acotar la búsqueda.",
          TextMapId = "TextMap_AnswerDetail_100401"
        },
        TextMap_AnswerDetail_100402 = {
          ContentDE = "Se descubrieron rastros de Phoxichor en la nieve cerca de la escena del crimen. Sin embargo, no se han reportado fugas en instalaciones cercanas. Será mejor consultar a Rhythm sobre los detalles del caso para reunir más pistas.",
          TextMapId = "TextMap_AnswerDetail_100402"
        },
        TextMap_AnswerDetail_100403 = {
          ContentDE = "Recuerdas un olor penetrante impregnando al agresor, clara evidencia de una fuerte contaminación de Phoxichor. Muy pocos sitios en el Lago Glacial podrían explicar niveles tan altos. Cruza estas pistas para reducir las posibilidades.",
          TextMapId = "TextMap_AnswerDetail_100403"
        },
        TextMap_AnswerDetail_100404 = {
          ContentDE = "El agresor huyó al suroeste y la única instalación en esa dirección con grandes reservas de Phoxichor es la fábrica local. ¿Podría ser su escondite? Merece una búsqueda exhaustiva.",
          TextMapId = "TextMap_AnswerDetail_100404"
        },
        TextMap_AnswerDetail_100501 = {
          ContentDE = "En las alcantarillas encontraste cortinas de terciopelo y maniquíes dispuestos como actores en plena actuación. Quien montó esta escena posiblemente se ve a sí mismo como parte de una obra. Cruza estas pistas, podrían revelar quién es en realidad.",
          TextMapId = "TextMap_AnswerDetail_100501"
        },
        TextMap_AnswerDetail_100502 = {
          ContentDE = "Esa noche, el agresor tarareó una melodía operática con una voz áspera. ¿Podría ser un cantante, o simplemente un amante de la música?",
          TextMapId = "TextMap_AnswerDetail_100502"
        },
        TextMap_AnswerDetail_100503 = {
          ContentDE = "El escondite del agresor estaba decorado con utilería teatral, y durante el ataque tarareó una melodía operática. Estas pistas sugieren que podría ser un entusiasta de la ópera. La melodía misma podría ser la clave de su identidad.",
          TextMapId = "TextMap_AnswerDetail_100503"
        },
        TextMap_AnswerDetail_200101 = {
          ContentDE = "El señor Buck solo bebe jugo y leche en el Asfódeo. No tiene tolerancia al alcohol un sorbo basta para dejarlo inconsciente",
          TextMapId = "TextMap_AnswerDetail_200101"
        },
        TextMap_AnswerDetail_200102 = {
          ContentDE = "Alguien mezcló secretamente alcohol en su leche, claramente para tumbarlo. Una huella pegajosa de niño permanece visible en la jarra.",
          TextMapId = "TextMap_AnswerDetail_200102"
        },
        TextMap_AnswerDetail_200103 = {
          ContentDE = "Un rastro de pequeñas huellas conduce desde la calle hasta el alféizar de la ventana del Sr. Buck, señales claras de que un niño entró e hizo algo dentro.",
          TextMapId = "TextMap_AnswerDetail_200103"
        },
        TextMap_AnswerDetail_200104 = {
          ContentDE = "Unas palomitas esparcidas cerca de las huellas, probablemente se pegaron al intruso y se desprendieron al trepar por la ventana.",
          TextMapId = "TextMap_AnswerDetail_200104"
        },
        TextMap_AnswerDetail_200105 = {
          ContentDE = "Un joven Charon tembloroso vendiendo cerveza, palomitas, entradas de ópera y carteles cerca del Teatro Galea.",
          TextMapId = "TextMap_AnswerDetail_200105"
        },
        TextMap_AnswerDetail_200106 = {
          ContentDE = "Un niño, sabiendo que Buck no soportaba el alcohol, entró en su casa y adulteró su leche, lo suficiente para dejarlo inconsciente. Por eso Buck se ha estado durmiendo inusualmente temprano.",
          TextMapId = "TextMap_AnswerDetail_200106"
        },
        TextMap_AnswerDetail_200107 = {
          ContentDE = "Un hombre borracho está desplomado junto al basurero, apestando a alcohol. No encaja con el perfil de un niño, ni parece del tipo que regalaría su bebida.",
          TextMapId = "TextMap_AnswerDetail_200107"
        },
        TextMap_AnswerDetail_200108 = {
          ContentDE = "Una niña pequeña insiste una y otra vez a su estricto padre para que le dé palomitas. Aunque encaja con el perfil de una niña, está claro que las palomitas bajo la ventana de Buck no vinieron de ella.",
          TextMapId = "TextMap_AnswerDetail_200108"
        },
        TextMap_AnswerDetail_200201 = {
          ContentDE = "Hace dieciséis años, el amigo de Donat, Sig, organizó un secuestro. La víctima, Enola, murió accidentalmente durante el incidente, y Sig fue condenado a muerte.",
          TextMapId = "TextMap_AnswerDetail_200201"
        },
        TextMap_AnswerDetail_200202 = {
          ContentDE = "Giselle, la Phoxcazadora, trabajaba antes para la Escolta. Pero hace dieciséis años, renunció después de que un veredicto en un caso la pusiera en desacuerdo con su superior.",
          TextMapId = "TextMap_AnswerDetail_200202"
        },
        TextMap_AnswerDetail_200203 = {
          ContentDE = "La hermana de Sig, Violet, que había dejado Lago Glacial dieciséis años antes, parece haber regresado. Se encontró una cinta violeta en la tumba de su hermano.",
          TextMapId = "TextMap_AnswerDetail_200203"
        },
        TextMap_AnswerDetail_200204 = {
          ContentDE = "Violetta siempre lleva una cinta violeta en el escenario. Ella afirma que es un recuerdo de una amiga querida, una pieza característica que siempre lleva consigo.",
          TextMapId = "TextMap_AnswerDetail_200204"
        },
        TextMap_AnswerDetail_200205 = {
          ContentDE = "Rosalind, la hija del Conde Magnus, ha desaparecido, se cree que ha sido secuestrada. Sus padres habían contratado recientemente a una profesora de canto.",
          TextMapId = "TextMap_AnswerDetail_200205"
        },
        TextMap_AnswerDetail_200206 = {
          ContentDE = "Una de las alumnas de Violetta fue secuestrada. La carta de rescate hacía referencia a eventos ocurridos hace dieciséis años.",
          TextMapId = "TextMap_AnswerDetail_200206"
        },
        TextMap_AnswerDetail_200207 = {
          ContentDE = "Hace dieciséis años, Giselle formaba parte del equipo encargado de investigar el secuestro. El veredicto final la perturbó tanto que decidió renunciar a la Escolta.",
          TextMapId = "TextMap_AnswerDetail_200207"
        },
        TextMap_AnswerDetail_200208 = {
          ContentDE = "El color y la forma de ambas cintas son idénticos. Junto con sus nombres similares, está claro que Violetta y Violet comparten una conexión cercana.",
          TextMapId = "TextMap_AnswerDetail_200208"
        },
        TextMap_AnswerDetail_200209 = {
          ContentDE = "La alumna desaparecida de Violetta es muy probable que sea Rosalind, la hija del Conde Magnus. La referencia a eventos ocurridos hace dieciséis años en la carta de rescate podría sugerir una conexión más profunda entre Violetta y el caso.",
          TextMapId = "TextMap_AnswerDetail_200209"
        },
        TextMap_AnswerDetail_200210 = {
          ContentDE = "El secuestro de Rosalind está claramente relacionado con el secuestro de hace dieciséis años, y Violetta sabe exactamente lo que ocurrió en ese entonces.",
          TextMapId = "TextMap_AnswerDetail_200210"
        },
        TextMap_AnswerDetail_200211 = {
          ContentDE = "El viejo caso escondía verdades ocultas, y Violetta las conocía. Giselle fingió el “secuestro” de su alumna para sacar esas verdades a la luz.",
          TextMapId = "TextMap_AnswerDetail_200211"
        },
        TextMap_AnswerDetail_200301 = {
          ContentDE = "Un grupo de Lirios celestes descansa en la ventana, aún húmedos con el rocío de la mañana, alguien debió colocarlos allí recientemente.",
          TextMapId = "TextMap_AnswerDetail_200301"
        },
        TextMap_AnswerDetail_200302 = {
          ContentDE = "Este rincón tranquilo de Primavera Eterna permanece intacto. Ninguna huella salvo las de Lingling… nada fuera de lugar.",
          TextMapId = "TextMap_AnswerDetail_200302"
        },
        TextMap_AnswerDetail_200303 = {
          ContentDE = "Encontrado cerca de la entrada, lleno de fotos familiares. En una, una Lingling más joven sostiene un ramo de Lirios celestes, sonriendo junto a Nana, justo afuera de esta misma casa.",
          TextMapId = "TextMap_AnswerDetail_200303"
        },
        TextMap_AnswerDetail_200304 = {
          ContentDE = "Explica que los padres de Lingling la trajeron de Haojing a Puerto de las Brumas por trabajo, quedándose temporalmente en el viejo dormitorio de obreros que solían llamar hogar.",
          TextMapId = "TextMap_AnswerDetail_200304"
        },
        TextMap_AnswerDetail_200305 = {
          ContentDE = "Alguien dejó el ramo sin dejar rastro.",
          TextMapId = "TextMap_AnswerDetail_200305"
        },
        TextMap_AnswerDetail_200306 = {
          ContentDE = "El “fantasma” conocía bien esta humilde casa y apreciaba el álbum. Quizá alguna vez fue parte de esta familia.",
          TextMapId = "TextMap_AnswerDetail_200306"
        },
        TextMap_AnswerDetail_200307 = {
          ContentDE = "El ramo de Lirios celestes, el álbum familiar, la familiaridad con la antigua casa… Todo converge hacia la misma conclusión: un ser querido ha regresado bajo otra forma.",
          TextMapId = "TextMap_AnswerDetail_200307"
        },
        TextMap_AnswerDetail_200401 = {
          ContentDE = "Un niño de doce años que se resfrió tras jugar en la nieve... ¿Podría este expediente estar relacionado con la esposa de Weisheng?",
          TextMapId = "TextMap_AnswerDetail_200401"
        },
        TextMap_AnswerDetail_200402 = {
          ContentDE = "Una mujer de treinta y un años cuya vista se deterioró tras largas noches de estudio... ¿Podría este expediente estar relacionado con la esposa de Weisheng?",
          TextMapId = "TextMap_AnswerDetail_200402"
        },
        TextMap_AnswerDetail_200403 = {
          ContentDE = "Un hombre de cuarenta años que sufre alucinaciones debido al duelo por su esposa fallecida... ¿Podría este expediente estar relacionado con la esposa de Weisheng?",
          TextMapId = "TextMap_AnswerDetail_200403"
        },
        TextMap_AnswerDetail_200501 = {
          ContentDE = "El informe de autopsia indica que el cadáver murió por una grave lesión interna causada por un golpe frontal con un objeto contundente; el arma parece ser el guante de acero de los guardias de la estación. El cadáver había sido torturado antes de morir.",
          TextMapId = "TextMap_AnswerDetail_200501"
        },
        TextMap_AnswerDetail_200502 = {
          ContentDE = "El informe de autopsia indica que el estado dental del cadáver revela una situación económica acomodada, pero el contenido estomacal corresponde a comida barata común entre los trabajadores de la estación.",
          TextMapId = "TextMap_AnswerDetail_200502"
        },
        TextMap_AnswerDetail_200503 = {
          ContentDE = "El único limpiador de estructuras metálicas que se marchó recientemente fue Handy, y abandonó el trabajo apresuradamente ayer.",
          TextMapId = "TextMap_AnswerDetail_200503"
        },
        TextMap_AnswerDetail_200504 = {
          ContentDE = "Según sus compañeros, Handy era torpe y lento en su trabajo, algo muy inusual para un limpiador de estructuras metálicas.",
          TextMapId = "TextMap_AnswerDetail_200504"
        },
        TextMap_AnswerDetail_200505 = {
          ContentDE = "Según sus compañeros, Handy poseía conocimientos excepcionales, algo poco común entre los trabajadores de la estación.",
          TextMapId = "TextMap_AnswerDetail_200505"
        },
        TextMap_AnswerDetail_200506 = {
          ContentDE = "Según sus compañeros, Handy afirmó ayer que el jefe de estación Eisenbahn lo había amenazado de muerte.",
          TextMapId = "TextMap_AnswerDetail_200506"
        },
        TextMap_AnswerDetail_200507 = {
          ContentDE = "Handy era torpe y se le daba mal el trabajo, pero además era mucho más culto que la mayoría de los trabajadores de la estación. Las dos cosas apuntan a que Handy en realidad no era un trabajador de la estación.",
          TextMapId = "TextMap_AnswerDetail_200507"
        },
        TextMap_AnswerDetail_200508 = {
          ContentDE = "Después de que Eisenbahn lo amenazara de muerte ayer, Handy abandonó el trabajo apresuradamente e intentó huir de la estación.",
          TextMapId = "TextMap_AnswerDetail_200508"
        },
        TextMap_AnswerDetail_200509 = {
          ContentDE = "Según el informe de autopsia, el cadáver tenía una situación económica acomodada, pero su dieta reciente era de comida barata típica de trabajadores de la estación. Lo más probable es que sea Handy, quien se disfrazó de limpiador de estructuras metálicas por algún motivo.",
          TextMapId = "TextMap_AnswerDetail_200509"
        },
        TextMap_AnswerDetail_200510 = {
          ContentDE = "Tras recibir amenazas, Handy quiso abandonar la estación. La herida mortal fue obra de los guardias de la estación, quienes obedecen ciegamente a Eisenbahn. Al parecer intentó escapar, pero los hombres de Eisenbahn consiguieron alcanzarlo.",
          TextMapId = "TextMap_AnswerDetail_200510"
        },
        TextMap_AnswerDetail_200511 = {
          ContentDE = "Handy probablemente era un forastero que llegó a Lago Glacial con algún propósito en mente. Su papel de trabajador no era más que una tapadera para recabar información. Una vez descubierto su verdadero objetivo, quiso marcharse, pero Eisenbahn lo mandó silenciar.",
          TextMapId = "TextMap_AnswerDetail_200511"
        },
        TextMap_AnswerName_100003 = {
          ContentDE = "Teatro Galea — Posible escondite",
          TextMapId = "TextMap_AnswerName_100003"
        },
        TextMap_AnswerName_100004 = {
          ContentDE = "Fábrica — Posible escondite",
          TextMapId = "TextMap_AnswerName_100004"
        },
        TextMap_AnswerName_100005 = {
          ContentDE = "Melodía operática escuchada durante el ataque",
          TextMapId = "TextMap_AnswerName_100005"
        },
        TextMap_AnswerName_100101 = {
          ContentDE = "Hora estimada del ataque — de las 4 y las 5 de la mañana.",
          TextMapId = "TextMap_AnswerName_100101"
        },
        TextMap_AnswerName_100201 = {
          ContentDE = "Veleta recién dañada",
          TextMapId = "TextMap_AnswerName_100201"
        },
        TextMap_AnswerName_100202 = {
          ContentDE = "Base de la veleta doblada apunta en una dirección",
          TextMapId = "TextMap_AnswerName_100202"
        },
        TextMap_AnswerName_100203 = {
          ContentDE = "Veleta ensamblada indica ruta de escape al suroeste",
          TextMapId = "TextMap_AnswerName_100203"
        },
        TextMap_AnswerName_100301 = {
          ContentDE = "Voz inquietante del agresor cantando",
          TextMapId = "TextMap_AnswerName_100301"
        },
        TextMap_AnswerName_100302 = {
          ContentDE = "Retazo de telón encontrado en la escena",
          TextMapId = "TextMap_AnswerName_100302"
        },
        TextMap_AnswerName_100303 = {
