        Two = {ContentDE = "2", TextMapId = "Two"},
        UIGUIDE_AMMO = {
          ContentDE = "Hay una posibilidad de obtener suministros de munición derrotando enemigos, abriendo cofres o destruyendo objetos rompibles, lo que puede usarse para recargar los proyectiles de las armas a distancia.",
          TextMapId = "UIGUIDE_AMMO"
        },
        UIGUIDE_ATTACK = {
          ContentDE = "Pulsa &Attack& para realizar un ataque cuerpo a cuerpo.",
          TextMapId = "UIGUIDE_ATTACK"
        },
        UIGUIDE_CHARGEATTACK = {
          ContentDE = "Mantén &Attack& para realizar un ataque cargado.",
          TextMapId = "UIGUIDE_CHARGEATTACK"
        },
        UIGUIDE_EXECUTION_01 = {
          ContentDE = "Los enemigos poderosos mantendrán su Postura de combate, la cual puede ser <Highlight>debilitada por los ataques</>. Los enemigos <Highlight>perderán el equilibrio</> cuando su Postura se debilite hasta cierto punto, y una vez que se debilite completamente, estarán <Highlight>aturdidos temporalmente</>.",
          TextMapId = "UIGUIDE_EXECUTION_01"
        },
        UIGUIDE_EXECUTION_02 = {
          ContentDE = "Los enemigos aturdidos serán vulnerables y revelarán sus debilidades. En este punto, <Highlight>puedes acercarte a ellos para ejecutar un ataque poderoso</>. Algunos Daimons se refieren a esto como “Retribución de Ask”, la cual trae tanto destrucción como oportunidad.",
          TextMapId = "UIGUIDE_EXECUTION_02"
        },
        UIGUIDE_FALLATTACK = {
          ContentDE = "Pulsa &Attack& mientras estés en el aire para ejecutar un Ataque Descendente",
          TextMapId = "UIGUIDE_FALLATTACK"
        },
        UIGUIDE_GUN = {
          ContentDE = "Las armas a distancia son ideales para derrotar enemigos que se encuentran lejos o en una posición elevada. Ten en cuenta los límites de su cargador y munición.",
          TextMapId = "UIGUIDE_GUN"
        },
        UIGUIDE_HPSHIELD = {
          ContentDE = "Cuando un personaje es atacado, el <Highlight>escudo</> mostrado debajo suele consumirse primero. Una vez que el <Highlight>escudo</> es quebrantado, los ataques adicionales reducirán los <Highlight>PV</>.",
          TextMapId = "UIGUIDE_HPSHIELD"
        },
        UIGUIDE_PARTIALDAMAGE_01 = {
          ContentDE = "Algunos enemigos poseen partes brillantes que son destructibles, y cada parte posee sus <Highlight>propios PV</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_01"
        },
        UIGUIDE_PARTIALDAMAGE_02 = {
          ContentDE = "Cuando los PV de una parte destructible sean reducidos a 0, el enemigo entrará en <Highlight>Estado de destrucción</>, lo que <Highlight>debilita significativamente la Postura del enemigo</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_02"
        },
        UIGUIDE_PARTIALDAMAGE_03 = {
          ContentDE = "Cuando su Postura se debilite hasta cierto punto, el enemigo <Highlight>perderá su equilibrio</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_03"
        },
        UIGUIDE_PARTIALDAMAGE_04 = {
          ContentDE = "Una vez que la Postura de un enemigo se rompa <Highlight>quedará aturdido temporalmente</>. <Highlight>Durante la recuperación de Postura</>, <Highlight>serán expuestas las debilidades</> del enemigo y el daño que reciba aumentará considerablemente.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_04"
        },
        UIGUIDE_PARTIALDAMAGE_05 = {
          ContentDE = "La armadura del Cristalófilo es destructible, y cada parte destructible tiene su <Highlight>propio PV</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_05"
        },
        UIGUIDE_PARTIALDAMAGE_06 = {
          ContentDE = "Ante la presencia de <Highlight>cualquier</> armadura, el Cristalófilo permanece <Highlight>invencible</>. Cuando los PV de una parte destructible se reducen a 0, el Cristalófilo entra en <Highlight>Estado de destrucción</> y pierde el equilibrio.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_06"
        },
        UIGUIDE_PARTIALDAMAGE_07 = {
          ContentDE = "Cuando el Cristalófilo <Highlight>pierda el equilibrio</>, quedará <Highlight>aturdido</> por un breve periodo de tiempo y <Highlight>perderá su invencibilidad</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_07"
        },
        UIGUIDE_PARTIALDAMAGE_08 = {
          ContentDE = "Cuando toda la armadura es destruida, el Cristalófilo quedará <Highlight>completamente aturdido</> y sus <Highlight>debilidades quedarán expuestas</>. Usar <Highlight>“Retribución de Ask”</> en su <Highlight>cabeza</> en este momento lo <Highlight>derrotará de inmediato</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_08"
        },
        UIGUIDE_SKILL2_01 = {
          ContentDE = "Inspirada por el poder de la Resonancia, la <Highlight>Habilidad Definitiva</> de Berenica ha sido despertada.\nPresiona &Skill2& para lanzar la Habilidad Definitiva de Berenica [Llama Infernal]. [Llama Infernal] <Highlight>consume Cordura continuamente</> durante su activación, lanzando ondas de espada en la dirección de ataque. Presiona &Skill2& <Highlight>nuevamente</> para <Highlight>finalizar la Habilidad Definitiva</>.",
          TextMapId = "UIGUIDE_SKILL2_01"
        },
        UIGUIDE_SKILL2_01_phone = {
