        },
        UIGuide_DengHua_1 = {
          ContentDE = "<H>Flores-linterna</> están dispersas por la Grieta del Olvido, portando las oraciones de los vivos. Bajo su luz, recuperas gradualmente PV y estás protegido de la erosión de la Grieta del Olvido.",
          TextMapId = "UIGuide_DengHua_1"
        },
        UIGuide_Destructible = {
          ContentDE = "Algunos objetos pueden ser dañados al ser atacados. Puedes encontrar suministros ocultos en ellos...",
          TextMapId = "UIGuide_Destructible"
        },
        UIGuide_DianFeng_1 = {
          ContentDE = "Durante la Clasificación suprema, los Phoxcazadores se enfrentan a <H>enemigos de amenaza extrema</> además de oleadas de enemigos <H>mucho más peligrosos de lo habitual</>.",
          TextMapId = "UIGuide_DianFeng_1"
        },
        UIGuide_DianFeng_2 = {
          ContentDE = "Los enemigos de amenaza extrema tienen un PV excepcionalmente alto. Derrotar unidades normales reduce su PV.",
