        },
        UIGuide_DianFeng_4 = {
          ContentDE = "Los Phoxcazadores obtienen puntos de clasificación según PV restante de los enemigos de amenaza extrema y el tiempo disponible.",
          TextMapId = "UIGuide_DianFeng_4"
        },
        UIGuide_Dodge_PC = {
          ContentDE = "Presiona &Avoid& para esquivar ataques entrantes. Solo puedes esquivar un <H>número limitado de veces</> dentro de un periodo de tiempo específico. Las esquivas consecutivas son posibles cuando tienes suficientes intentos de esquiva.",
          TextMapId = "UIGuide_Dodge_PC"
        },
        UIGuide_Dodge_Phone = {
          ContentDE = "Pulsa el botón para esquivar ataques entrantes. Solo puedes esquivar un <H>número limitado de veces</> dentro de un periodo de tiempo específico. Las esquivas consecutivas son posibles cuando tienes suficientes intentos de esquiva.",
          TextMapId = "UIGuide_Dodge_Phone"
        },
        UIGuide_Dot = {
          ContentDE = "Inflige daño <H>una vez</> cada <H>2 s</> durante su duración. El Daño Periódico <H>no puede</> activar los Efectos Adicionales.",
          TextMapId = "UIGuide_Dot"
        },
        UIGuide_DynStory_1 = {
          ContentDE = "De vez en cuando, Misiones dinámicas aparecerán por el mundo. Tu participación puede alterar el resultado.",
          TextMapId = "UIGuide_DynStory_1"
        },
        UIGuide_DynStory_2 = {
          ContentDE = "En algunas Misiones dinámicas, tus elecciones afectarán a tus Cinco Impresiones.",
          TextMapId = "UIGuide_DynStory_2"
        },
        UIGuide_EX01Map = {
          ContentDE = "En el <H>Mapa</>, selecciona la <H>esquina superior derecha</> para abrir el <H>Mapa mundial</> donde puedes intercambiar entre el <H>Capítulo Noctoviajero</> y el <H>Capítulo Crepúsculo</>.",
          TextMapId = "UIGuide_EX01Map"
        },
        UIGuide_EX01Mechanism_1 = {
          ContentDE = "Interactúa con los <H>transformadores</> para <H>activar o desactivar</> sus dispositivos conectados. Comprueba el color de los <H>cables</> para diferenciar qué dispositivos están <H>activos</>.",
          TextMapId = "UIGuide_EX01Mechanism_1"
        },
        UIGuide_EX01Mechanism_2 = {
          ContentDE = "Comprueba el color de los <H>cables</> conectados para determinar sus estados: <H>Azul</>: El <H>dispositivo</> está activo. <H>Naranja</>: El dispositivo está <H>inactivo</>. Busca los transformadores necesarios cerca para activarlo.",
          TextMapId = "UIGuide_EX01Mechanism_2"
        },
        UIGuide_Elevator = {
          ContentDE = "Los elevadores son mecanismos estándar para el transporte vertical.",
          TextMapId = "UIGuide_Elevator"
        },
        UIGuide_ExplorationMechanism_1_PC = {
          ContentDE = "Lunoexploradora ha preparado desafíos en todo el mundo. Acércate a uno y presiona &Interactive& para iniciar el desafío.",
          TextMapId = "UIGuide_ExplorationMechanism_1_PC"
        },
        UIGuide_ExplorationMechanism_1_Phone = {
          ContentDE = "Lunoexploradora ha preparado desafíos en todo el mundo. Acércate a uno e <H>interactúa</> con él para iniciar el desafío.",
          TextMapId = "UIGuide_ExplorationMechanism_1_Phone"
        },
        UIGuide_ExplorationMechanism_2 = {
          ContentDE = "Completa el desafío siguiendo la guía para llegar al objetivo dentro del tiempo especificado.",
          TextMapId = "UIGuide_ExplorationMechanism_2"
        },
        UIGuide_ExplorationMechanism_3 = {
          ContentDE = "Completa el desafío siguiendo la navegación para disparar a los objetivos designados dentro del límite de tiempo.",
          TextMapId = "UIGuide_ExplorationMechanism_3"
        },
        UIGuide_FanZhuan_1 = {
          ContentDE = "Interactúa con el mecanismo de rotación hace girar horizontalmente los bloques de piedra a ambos lados de la puerta, revelando su cara decorada con motivos.",
          TextMapId = "UIGuide_FanZhuan_1"
        },
        UIGuide_FanZhuan_2 = {
          ContentDE = "Una nueva interacción provoca una rotación adicional, revelando la cara con anillos. Utiliza la función Atracción del Nexo Mecánico para extraer el bloque decorado y desbloquear el cofre.",
          TextMapId = "UIGuide_FanZhuan_2"
        },
        UIGuide_FangShu_1 = {
          ContentDE = "El Nexo Mecánico puede equiparse e invocarse desde la <H>Mochila táctica</>.",
          TextMapId = "UIGuide_FangShu_1"
        },
        UIGuide_FangShu_2 = {
          ContentDE = "Después de invocar el Nexo Mecánico, mantén &Fire& para entrar en modo Atracción e interactuar con los mecanismos de la Secta Jishu.",
          TextMapId = "UIGuide_FangShu_2"
        },
        UIGuide_FangShu_2_Phone = {
          ContentDE = "Tras invocar el Nexo mecánico, mantén pulsado el botón para activar el modo Atracción e interactuar con los mecanismos de la Secta Jishu.",
          TextMapId = "UIGuide_FangShu_2_Phone"
        },
        UIGuide_FangShu_3 = {
          ContentDE = "Después de invocar el Nexo Mecánico, pulsa &Skill3& para escanear los mecanismos interactivos cercanos.",
          TextMapId = "UIGuide_FangShu_3"
        },
        UIGuide_FangShu_3_Phone = {
          ContentDE = "ras invocar el Nexo mecánico, pulsa el botón para escanear los mecanismos interactivos cercanos.",
          TextMapId = "UIGuide_FangShu_3_Phone"
        },
        UIGuide_FangShu_4 = {
          ContentDE = "Después de invocar el Nexo mecánico, abre de nuevo la Mochila táctica y selecciona el Nexo mecánico para recuperarlo. Una vez retirado, los ataques a distancia y las habilidades de Geniemon estarán nuevamente disponibles.",
          TextMapId = "UIGuide_FangShu_4"
        },
        UIGuide_Feina_1 = {
          ContentDE = "En este cuento inconcluso, todo está en escala de grises. Haz clic en &Fire& para pintar el mundo con <H>Pigmento Tejesueños</> y darle color al relato.",
          TextMapId = "UIGuide_Feina_1"
        },
        UIGuide_Feina_10 = {
          ContentDE = "Observa el <H>entorno</> de cada gema y píntala con el color correcto para encender su luz y disipar las nieblas.",
          TextMapId = "UIGuide_Feina_10"
        },
        UIGuide_Feina_11 = {
          ContentDE = "Absorber la energía de una gema forma un aura protectora alrededor del pequeño Ruiseñor, protegiéndolo de las nieblas. El aura se desvanece con el tiempo, ilumina gemas rápidamente para renovar su fuerza.",
          TextMapId = "UIGuide_Feina_11"
        },
        UIGuide_Feina_12 = {
          ContentDE = "Golpea un disco grabado con pigmento <H>del color correspondiente</> para romperlo y abrir el camino.",
          TextMapId = "UIGuide_Feina_12"
        },
        UIGuide_Feina_1_Phone = {
          ContentDE = "En este cuento inconcluso, todo está en escala de grises. Pulsa para pintar el mundo con <H>Pigmento Tejesueños</> y darle color al relato.",
          TextMapId = "UIGuide_Feina_1_Phone"
        },
        UIGuide_Feina_2 = {
          ContentDE = "<H>Plumas blancas</> están esparcidas por el reino de cuento. Reúne suficientes para obtener recompensas extra.",
          TextMapId = "UIGuide_Feina_2"
        },
        UIGuide_Feina_3 = {
          ContentDE = "Algunos dispositivos solo pueden activarse con ciertos colores. Haz clic en &ChargeBullet& para cambiar entre pigmentos.",
          TextMapId = "UIGuide_Feina_3"
        },
        UIGuide_Feina_3_Gamepad = {
          ContentDE = "Algunos dispositivos solo pueden activarse con un color específico. Presiona &GamepadUseSkill& + &Fire& para alternar entre diferentes pigmentos.",
          TextMapId = "UIGuide_Feina_3_Gamepad"
        },
        UIGuide_Feina_3_Phone = {
          ContentDE = "Algunos dispositivos solo pueden activarse con ciertos colores. Pulsa el botón para cambiar entre pigmentos.",
          TextMapId = "UIGuide_Feina_3_Phone"
        },
        UIGuide_Feina_4 = {
          ContentDE = "Algunas flores permanecen sin color. Observa flores cercanas de <H>la misma forma</> y píntalas con el color correspondiente.",
          TextMapId = "UIGuide_Feina_4"
        },
        UIGuide_Feina_5 = {
          ContentDE = "Algunas flores perderán su color tras un tiempo. <H>Píntalas todas correctamente a tiempo</> para activar el mecanismo.",
          TextMapId = "UIGuide_Feina_5"
        },
        UIGuide_Feina_6 = {
          ContentDE = "Aplica un pigment a la palangana para que emita luz mágica del mismo color. Observa el entorno y usa <H>el color correcto</> para activar el mecanismo.",
          TextMapId = "UIGuide_Feina_6"
        },
        UIGuide_Feina_7 = {
          ContentDE = "Sigue el brillo de la gema y <H>pinta todas las espinas con el color correcto</> para despejar las ramas entrelazadas.",
          TextMapId = "UIGuide_Feina_7"
        },
        UIGuide_Feina_8 = {
          ContentDE = "Una vez que todas las espinas estén coloreadas, el pequeño Ruiseñor usará el poder de la gema para ayudar a Fina a abrir el camino.",
          TextMapId = "UIGuide_Feina_8"
        },
        UIGuide_Feina_9 = {
          ContentDE = "Nieblas peligrosas invaden el bosque. Si permaneces demasiado tiempo, Fina perderá el rumbo.",
          TextMapId = "UIGuide_Feina_9"
        },
        UIGuide_FenZuSai_1 = {
          ContentDE = "Durante la Fase de grupos, los Phoxcazadores se enfrentan a oleadas de enemigos <H>mucho más peligrosos de lo habitual</>.",
          TextMapId = "UIGuide_FenZuSai_1"
        },
        UIGuide_FenZuSai_2 = {
          ContentDE = "Derrotar el número requerido de enemigos dentro del tiempo establecido permite superar la Fase de grupos.",
          TextMapId = "UIGuide_FenZuSai_2"
        },
        UIGuide_FenZuSai_3 = {
          ContentDE = "Los Phoxcazadores obtienen puntos de clasificación según el número de enemigos derrotados y el tiempo restante.",
          TextMapId = "UIGuide_FenZuSai_3"
        },
        UIGuide_FireMechanism = {
          ContentDE = "Las <H>Trampas de llamas</> se <H>activarán</> al ser atacadas, infligiendo daño a <H>todos los objetivos</> que las atraviesen. Algunas <H>Trampas de llamas</> infligen daño más alto, pero requieren más tiempo de recarga.",
          TextMapId = "UIGuide_FireMechanism"
        },
        UIGuide_Fish_01 = {
          ContentDE = "Una vez que hayas lanzado la línea, espera a que el botón del carrete parpadee, eso significa que un pez ha mordido el anzuelo. Recoge la línea rápidamente antes de que se escape.",
          TextMapId = "UIGuide_Fish_01"
        },
        UIGuide_Fish_02 = {
          ContentDE = "Durante la recogida, mantén la vista en el indicador a la derecha. Mantén presionado el botón del carrete para aplicar tensión, alinea el indicador con la marca del pez y sostén firme hasta que la captura sea tuya.",
          TextMapId = "UIGuide_Fish_02"
