        UIGuide_QiTianDeng_1 = {
          ContentDE = "<H>Linternas celestes</> flotan sobre las aguas del Río del Olvido. Destruirlas con un arma a distancia hace caer sus Flores-linterna, creando en la superficie del agua una zona de refugio que se reduce progresivamente, ayudándote a resistir la erosión de la Grieta del Olvido. Puedes moverte dentro de esta zona y recuperar PV.",
          TextMapId = "UIGuide_QiTianDeng_1"
        },
        UIGuide_QianKun_1 = {
          ContentDE = "Usa el <H>Nexo mecánico</> para girar la Hélice de Doble Forma y alterar la estructura del Laberinto de Yanyin.",
          TextMapId = "UIGuide_QianKun_1"
        },
        UIGuide_QianKun_2 = {
          ContentDE = "Usa el <H>Nexo mecánico</> en el lado izquierdo de la Hélice de Doble Forma para girar las salas del Laberinto de Yanyin en el sentido de las agujas del reloj. Usarlo desde el lado opuesto las hace girar en sentido contrario.\n La dirección del giro depende de dónde te sitúes al activar la Hélice de Doble Forma.",
          TextMapId = "UIGuide_QianKun_2"
        },
        UIGuide_QiaoBan_1 = {
          ContentDE = "El Tablero mecánico de rompecabezas está compuesto por pivotes y plataformas.\n Los pivotes pueden fijarse a las plataformas adyacentes.",
          TextMapId = "UIGuide_QiaoBan_1"
        },
        UIGuide_QiaoBan_2 = {
          ContentDE = "Después de activar el Tablero mecánico de rompecabezas, vuelve a interactuar con la Estela de la Iluminación para restablecerlo.",
          TextMapId = "UIGuide_QiaoBan_2"
        },
        UIGuide_QueXie_1 = {
          ContentDE = "Puedes equipar e invocar <H>Nexo mecánico: Disipador de corrupción</> desde la Mochila táctica.",
          TextMapId = "UIGuide_QueXie_1"
        },
        UIGuide_Reading = {
          ContentDE = "Puedes encontrar objetos legibles como libros, notas y cartas esparcidas por el mundo.",
          TextMapId = "UIGuide_Reading"
        },
        UIGuide_RelayMechanism_1 = {
          ContentDE = "Atacar una <H>Rueda Phoxynamo</> alternará su estado de activación. Si la <H>Rueda Phoxynamo</> es <H>azul</>, se encuentra <H>activa</>. Si aparece <H>naranja</>, se encuentra <H>inactiva</>.",
          TextMapId = "UIGuide_RelayMechanism_1"
        },
        UIGuide_RelayMechanism_2 = {
          ContentDE = "Algunas <H>Ruedas Phoxynamo</> <H>volverán automáticamente</> a su <H>estado original</> luego de un tiempo establecido tras un cambio de estado.",
          TextMapId = "UIGuide_RelayMechanism_2"
        },
        UIGuide_Rouge_1 = {
          ContentDE = "El espacio dentro del Abismo es inestable y cambia constantemente. Luego de completar cada fase, aparecerán nuevas puertas que llevan a distintos tipos de zonas. Elige tu camino y continúa tu exploración.",
          TextMapId = "UIGuide_Rouge_1"
        },
        UIGuide_Rouge_2_1 = {
          ContentDE = "Zona de Abisoide: Centrado en combate. Derrota los Abisoides para ganar recompensas como Brasas.",
          TextMapId = "UIGuide_Rouge_2_1"
        },
        UIGuide_Rouge_2_2 = {
          ContentDE = "Zona de Eco: Contiene eventos impredecibles conocidos como encuentros.",
          TextMapId = "UIGuide_Rouge_2_2"
        },
        UIGuide_Rouge_2_3 = {
          ContentDE = "Zona de Descanso: Una zona segura donde puedes intercambiar Brasas por suministros, restaurar PV y recuperar Cordura.",
          TextMapId = "UIGuide_Rouge_2_3"
        },
        UIGuide_Run_PC = {
          ContentDE = "Mantén &Avoid& para correr.",
          TextMapId = "UIGuide_Run_PC"
        },
        UIGuide_Run_Phone = {
          ContentDE = "Mantén presionado el botón para correr.",
          TextMapId = "UIGuide_Run_Phone"
        },
        UIGuide_SIDEWAYSJUMP = {
          ContentDE = "Cuando te encuentres cerca de una pared escalable, mantén una dirección y presiona &Jump& <H>repetidamente</> para saltar hacia los lados y realizar saltos consecutivos en la pared.",
          TextMapId = "UIGuide_SIDEWAYSJUMP"
        },
        UIGuide_Saiqi_1 = {
          ContentDE = "Presiona &Skill1& para que Psyche cree 1 [Fantasma] y luego se proyecte hacia adelante. Esta habilidad se puede usar en cualquier momento sin interrumpir la acción actual de Psyche.",
          TextMapId = "UIGuide_Saiqi_1"
        },
        UIGuide_Saiqi_1_Gamepad = {
          ContentDE = "Presiona &GamepadUseSkill& + &Attack& para que Psyche cree 1 [Fantasma] y luego se proyecte hacia adelante. Esta habilidad se puede usar en cualquier momento sin interrumpir la acción actual de Psyche.",
          TextMapId = "UIGuide_Saiqi_1_Gamepad"
        },
        UIGuide_Saiqi_1_Phone = {
          ContentDE = "Presiona el botón para que Psyche cree 1 [Fantasma] y luego se proyecte hacia adelante. Esta habilidad se puede usar en cualquier momento sin interrumpir la acción actual de Psyche.",
          TextMapId = "UIGuide_Saiqi_1_Phone"
        },
        UIGuide_Saiqi_2 = {
          ContentDE = "Presiona &Skill2& para que Psyche entre en estado [Metamorfosis Radiante] y obtenga la habilidad de volar. En estado [Metamorfosis Radiante], Psyche solo puede usar habilidades y disparar. En estado [Metamorfosis Radiante], [Tejido de Crisálida Onírica] se reemplaza por [Fototaxis]: Se lanza hacia adelante y dispara [Polvo Etéreo] que se fija automáticamente en un enemigo aleatorio, causando Daño Anemo al impactar.",
          TextMapId = "UIGuide_Saiqi_2"
        },
        UIGuide_Saiqi_2_Gamepad = {
          ContentDE = "Presiona &GamepadUseSkill& + &Interactive& para que Psyche entre en estado [Metamorfosis Radiante] y obtenga la habilidad de volar. En estado [Metamorfosis Radiante], Psyche solo puede usar habilidades y disparar. En estado [Metamorfosis Radiante], [Tejido de Crisálida Onírica] se reemplaza por [Fototaxis]: Se lanza hacia adelante y dispara [Polvo Etéreo] que se fija automáticamente en un enemigo aleatorio, causando Daño Anemo al impactar.",
          TextMapId = "UIGuide_Saiqi_2_Gamepad"
        },
        UIGuide_Saiqi_2_Phone = {
          ContentDE = "Presiona el botón para que Psyche entre en estado [Metamorfosis Radiante] y obtenga la habilidad de volar. En estado [Metamorfosis Radiante], Psyche solo puede usar habilidades y disparar. En estado [Metamorfosis Radiante], [Tejido de Crisálida Onírica] se reemplaza por [Fototaxis]: Se lanza hacia adelante y dispara [Polvo Etéreo] que se fija automáticamente en un enemigo aleatorio, causando Daño Anemo al impactar.",
          TextMapId = "UIGuide_Saiqi_2_Phone"
        },
        UIGuide_Shadow_1 = {
          ContentDE = "Usa el <H>Sello de compañero de combate</> para invocar aliados en batalla. Arrastra los Sellos de compañero de combate a la Mochila táctica para habilitar las invocaciones.",
          TextMapId = "UIGuide_Shadow_1"
        },
        UIGuide_Shadow_2 = {
          ContentDE = "Mantén &OpenBattleWheel& para invocar aliados, que luchará junto a tu personaje actual.",
          TextMapId = "UIGuide_Shadow_2"
        },
        UIGuide_ShanYe_1 = {
          ContentDE = "Utiliza la función Atracción del Nexo Mecánico para hacer girar las aspas, generar una corriente de aire y abrir la puerta mecánica.",
          TextMapId = "UIGuide_ShanYe_1"
        },
        UIGuide_ShenJi_1 = {
          ContentDE = "Usa Nexo mecánico: Disipador de corrupción para señalar el punto de impacto en el suelo y guiar el disparo del Cañón celestial.",
          TextMapId = "UIGuide_ShenJi_1"
        },
        UIGuide_ShenJi_2 = {
          ContentDE = "El Cañón celestial tiene un tiempo de recarga entre disparos. Inflige muchísimo daño a los enemigos.",
          TextMapId = "UIGuide_ShenJi_2"
        },
        UIGuide_ShengMing_1 = {
          ContentDE = "Puedes obtener <H>reputación</> mediante <H>Desafío</> y <H>Contribución</>. La reputación tiene un límite semanal.",
          TextMapId = "UIGuide_ShengMing_1"
        },
        UIGuide_ShengMing_2 = {
          ContentDE = "Los Desafíos se dividen en tres niveles de dificultad. Tras aceptar y completar uno, obtendrás Reputación y desbloquearás el siguiente nivel de dificultad. Los Desafíos se actualizan automáticamente cada día.",
          TextMapId = "UIGuide_ShengMing_2"
        },
        UIGuide_ShengMing_3 = {
          ContentDE = "Obtén Reputación reuniendo y entregando los objetos requeridos para las Contribuciones. Las Contribuciones se actualizan automáticamente cada semana, o puedes actualizarlas al instante gastando Monedas.",
          TextMapId = "UIGuide_ShengMing_3"
        },
        UIGuide_Sojourns_01 = {
          ContentDE = "<Highlight>Fragmentos de memoria</> desbloqueados. Selecciona el icono en el Santuario para acceder.",
          TextMapId = "UIGuide_Sojourns_01"
        },
        UIGuide_Sojourns_01_Pad = {
          ContentDE = "<Highlight>Fragmentos de memoria</> ahora desbloqueados. Pulsa en el Santuario para acceder.",
          TextMapId = "UIGuide_Sojourns_01_Pad"
        },
        UIGuide_Sojourns_02 = {
          ContentDE = "Los <Highlight>Fragmentos de memoria</> capturan fragmentos de tiempo y memoria.",
          TextMapId = "UIGuide_Sojourns_02"
        },
        UIGuide_Sojourns_03 = {
          ContentDE = "Visita <Highlight>Antología del tiempo</> para ver historias de las diferentes etapas de la vida de un personaje.",
          TextMapId = "UIGuide_Sojourns_03"
        },
        UIGuide_Sojourns_03_Pad = {
          ContentDE = "Pulsa para visitar <Highlight>Antología del tiempo</> y explorar historias de distintas etapas de la experiencia de un personaje.",
          TextMapId = "UIGuide_Sojourns_03_Pad"
        },
        UIGuide_Sojourns_04 = {
          ContentDE = "Cada personaje tiene su propio conjunto de historias.",
          TextMapId = "UIGuide_Sojourns_04"
        },
        UIGuide_Sojourns_04_Pad = {
          ContentDE = "Pulsa para explorar la historia única de cada personaje.",
          TextMapId = "UIGuide_Sojourns_04_Pad"
        },
        UIGuide_Sojourns_05 = {
          ContentDE = "Usa <Highlight>Huella del alma</> para reconstruir estas historias. Algunas entradas tienen requisitos especiales.",
          TextMapId = "UIGuide_Sojourns_05"
        },
        UIGuide_Sojourns_06 = {
          ContentDE = "Cumple los requisitos para desbloquear historias y ganar recompensas.",
          TextMapId = "UIGuide_Sojourns_06"
        },
        UIGuide_Sojourns_06_Pad = {
          ContentDE = "Las historias se desbloquearán una vez cumplidos los requisitos. Pulsa para reclamar las recompensas asociadas",
          TextMapId = "UIGuide_Sojourns_06_Pad"
        },
        UIGuide_Sojourns_07 = {
          ContentDE = "Las historias desbloqueadas pueden revisitar en <Highlight>Instante eterno</>.",
          TextMapId = "UIGuide_Sojourns_07"
        },
        UIGuide_Sp = {
          ContentDE = "El recurso principal necesario para usar habilidades en batalla. <H>Se restaura</> con el tiempo.",
          TextMapId = "UIGuide_Sp"
        },
        UIGuide_SpecialDestructible_1 = {
          ContentDE = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.",
          TextMapId = "UIGuide_SpecialDestructible_1"
        },
        UIGuide_SpecialDestructible_2 = {
          ContentDE = "Por ejemplo, la <H>Criolita</> que cubre algunos cofres puede ser destruida con <H>Efecto Adicional: Contundente, Efecto Adicional: Pyro, o habilidades que infligen Daño Pyro</>.\n(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)",
          TextMapId = "UIGuide_SpecialDestructible_2"
        },
        UIGuide_SpecialDestructible_3 = {
          ContentDE = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.\nLas <H>Vid Umbro</> que cubren algunos cofres pueden ser destruidas con <H>Efecto Adicional: Cortante, Efecto Adicional: Lumino, o habilidades que infligen Daño Lumino</>.\n(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)",
          TextMapId = "UIGuide_SpecialDestructible_3"
        },
        UIGuide_SpecialDestructible_4 = {
          ContentDE = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.\nLa <H>Grava</> que cubre algunos cofres puede ser destruida con <H>Efecto Adicional: Contundente</>.\n(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)",
          TextMapId = "UIGuide_SpecialDestructible_4"
        },
        UIGuide_SpecialDestructible_5 = {
          ContentDE = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.\nEl <H>Escudo Lumino</> que cubre algunos cofres puede ser destruido con <H>Efecto Adicional: Perforante, Efecto Adiciona: Umbro, o habilidades que infligen Daño Umbro</>.\n(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)",
          TextMapId = "UIGuide_SpecialDestructible_5"
        },
        UIGuide_SpecialSideStoryUI1 = {
          ContentDE = "Es posible que encuentres algunas Misiones secundarias especiales. Están marcadas con un indicador azul en la lista de misiones.",
          TextMapId = "UIGuide_SpecialSideStoryUI1"
        },
        UIGuide_SpecialSideStoryUI2 = {
          ContentDE = "También pueden aparecer Misiones secundarias especiales durante la exploración. Completarlas puede desbloquear nuevas características o funciones.",
          TextMapId = "UIGuide_SpecialSideStoryUI2"
        },
