        },
        UIGuide_TongLv_1 = {
          ContentDE = "Algunos personajes poseen Armas de Consonancia únicas. Estas armas suben de nivel junto con el personaje y no pueden reemplazarse ni mejorarse de forma independiente, pero pueden equiparse con Cuñas demoníacas.",
          TextMapId = "UIGuide_TongLv_1"
        },
        UIGuide_TrainingGround_1 = {
          ContentDE = "La Meditación del Reino de las Arenas te permite volver a enfrentarte a enemigos pasados en un entorno controlado, ayudándote a familiarizarte con sus movimientos y perfeccionar tus habilidades de combate.",
          TextMapId = "UIGuide_TrainingGround_1"
        },
        UIGuide_TrainingGround_2 = {
          ContentDE = "Desde el <H>Vórtice Arenoso</> en la Meditación del Reino de las Arenas, encontrarás suministros de combate como <H>Cajas de suministros de munición</>, <H>Sal volátil</> y <H>Sal volátil concentrada</> para facilitar tu combate.",
          TextMapId = "UIGuide_TrainingGround_2"
        },
        UIGuide_TrainingGround_3_PC = {
          ContentDE = "Accede al <H>Arsenal</> en la parte <H>superior derecha</> de la página para cambiar rápidamente de personaje.",
          TextMapId = "UIGuide_TrainingGround_3_PC"
        },
        UIGuide_TrainingGround_3_Phone = {
          ContentDE = "Accede al <H>Arsenal</> en la parte <H>superior izquierda</> de la página para cambiar rápidamente de personaje.",
          TextMapId = "UIGuide_TrainingGround_3_Phone"
        },
        UIGuide_TrainingGround_4_PC = {
          ContentDE = "En la Meditación del Reino de las Arenas,haz clic en &OpenMenu& y selecciona <H>salir</> para salir.",
          TextMapId = "UIGuide_TrainingGround_4_PC"
        },
        UIGuide_TrainingGround_4_Phone = {
          ContentDE = "Selecciona <H>salir de la Meditación del Reino de las Arenas</> en el <H>menú</> en la parte <H>superior izquierda</> para salir.",
          TextMapId = "UIGuide_TrainingGround_4_Phone"
        },
        UIGuide_TrialRank_1 = {
          ContentDE = "Gana EXP mediante la progresión de personajes, armas, Geniemons y Cuñas Demoníacas, o completando misiones, para subir tu Rango de Aventura.",
          TextMapId = "UIGuide_TrialRank_1"
        },
        UIGuide_TrialRank_2 = {
          ContentDE = "Avanzar a Rangos de Aventura más altos otorga recompensas valiosas y poderosos beneficios.",
          TextMapId = "UIGuide_TrialRank_2"
        },
        UIGuide_TriggerEffect_1 = {
          ContentDE = "Los <H>personajes</> tienen tipos de elemento. Hay seis elementos: <H>Hydro, Pyro, Anemo, Electro, Lumino y Umbro</>. Cada elemento tiene su <H>Efecto Adicional</> que aplica una desventaja, infligiendo <H>Daño Periódico</>:\nHydro: Causa Daño Hydro periódico.\nPyro: Causa Daño Pyro periódico.\nElectro: Causa Daño Electro periódico.\nAnemo: Causa Daño Anemo periódico.\nLumino: Causa Daño Lumino periódico y <H>actualiza</> el tiempo restante de todos los efectos elementales adicionales activos.\nUmbro: Causa Daño Umbro periódico y <H>ralentiza</> la recuperación de Postura del objetivo.",
          TextMapId = "UIGuide_TriggerEffect_1"
        },
        UIGuide_TriggerEffect_2 = {
          ContentDE = "Los efectos físicos provienen de las <H>Armas</>. Los tres tipos de daño — <H>Cortante, Perforante y Contundente</> — aumentan su daño respectivo o amplifican el debilitamiento de la Postura:\nCortante: Inflige más daño al <H>escudo</> del objetivo.\nPerforante: Inflige más daño a los <H>PV</> del objetivo.\nContundente: Debilita la <H>Postura</> del objetivo con más efectividad.",
          TextMapId = "UIGuide_TriggerEffect_2"
        },
        UIGuide_TriggerEffect_3 = {
          ContentDE = "Al infligir daño con una arma o ciertas habilidades, existe una probabilidad de activar un <H>Efecto Adicional</> elemental. La probabilidad está basada en la <H>probabilidad de activación</> del arma.",
          TextMapId = "UIGuide_TriggerEffect_3"
        },
        UIGuide_TurnTable = {
          ContentDE = "Un mecanismo de cerradura de puerta común. Ilumina todas las áreas blancas dentro del tiempo asignado para desbloquear este tipo de cerradura mágica.",
          TextMapId = "UIGuide_TurnTable"
        },
        UIGuide_ValveMechanism = {
          ContentDE = "Un mecanismo de cerradura de puerta común. Mover continuamente el puntero para atravesar los rangos de arrastre dentro del límite de tiempo puede desbloquear este tipo de cerradura mágica.",
          TextMapId = "UIGuide_ValveMechanism"
        },
        UIGuide_WIKI_01 = {
          ContentDE = "Durante los diálogos de la historia, cuando aparezca el botón <H>ver entrada</> en la esquina inferior derecha, puedes seleccionarlo para obtener más información.",
          TextMapId = "UIGuide_WIKI_01"
        },
        UIGuide_WIKI_02 = {
          ContentDE = "En <H>Atlasium</>, puedes ver todas las entradas que han sido desbloqueadas.",
          TextMapId = "UIGuide_WIKI_02"
        },
        UIGuide_WallJump_PC = {
          ContentDE = "Cuando estés cerca de una pared, presiona <H>repetidamente</> &Jump& para saltar sobre la pared.",
          TextMapId = "UIGuide_WallJump_PC"
        },
        UIGuide_WallJump_Phone = {
          ContentDE = "Cuando estés cerca de una pared, pulsa <H>repetidamente</> el botón para saltar sobre la pared.",
          TextMapId = "UIGuide_WallJump_Phone"
        },
        UIGuide_WangXi_1 = {
          ContentDE = "La Grieta del Olvido erosiona continuamente a cualquier ser vivo que caiga en ella. Mientras permanezcas en este entorno, tus PV disminuirán constantemente.",
          TextMapId = "UIGuide_WangXi_1"
        },
        UIGuide_WangXi_2 = {
          ContentDE = "La Grieta del Olvido está atravesada por las aguas del Río del Olvido. Entrar en contacto con estas aguas acelera considerablemente la pérdida de PV.",
          TextMapId = "UIGuide_WangXi_2"
        },
        UIGuide_WangXi_3 = {
          ContentDE = "Aprovechar sabiamente las zonas de refugio formadas por las Flores-linterna es clave para salir de la Grieta del Olvido.",
          TextMapId = "UIGuide_WangXi_3"
        },
        UIGuide_WuYou_1 = {
          ContentDE = "Derrota a una cantidad determinada de enemigos para entrar en el Combate de Alto Riesgo.",
          TextMapId = "UIGuide_WuYou_1"
        },
        UIGuide_WuYou_2 = {
          ContentDE = "Derrota enemigos en la partida para fortalecer a tu Wishen.",
          TextMapId = "UIGuide_WuYou_2"
        },
        UIGuide_WuYou_3 = {
          ContentDE = "Supera el nivel dentro del tiempo especificado para alcanzar el objetivo de recompensa.",
          TextMapId = "UIGuide_WuYou_3"
        },
        UIGuide_XiQiu_1 = {
          ContentDE = "Utiliza la función Atracción del Nexo Mecánico para atraer las esferas del mecanismo hacia su base correspondiente y desbloquear el dispositivo.",
          TextMapId = "UIGuide_XiQiu_1"
        },
        UIGuide_XiaoChuan_1 = {
          ContentDE = "<H>Embarcaciones pequeñas</> flotan sobre las aguas del Río del Olvido. Cuando se encienden, generan a su alrededor una zona de refugio móvil, ayudándote a resistir la erosión de la Grieta del Olvido. Puedes moverte dentro de esta zona y recuperar PV.",
          TextMapId = "UIGuide_XiaoChuan_1"
        },
        UIGuide_XiaoYao_1 = {
          ContentDE = "A veces Xiaoyao poseerá objetos cercanos y alterará su aspecto. Usa la función de escaneo del Nexo mecánico para identificarlos.",
          TextMapId = "UIGuide_XiaoYao_1"
        },
        UIGuide_XiaoYao_2 = {
          ContentDE = "Usa el Nexo mecánico para sacar a Xiaoyao de esos objetos poseídos.",
          TextMapId = "UIGuide_XiaoYao_2"
        },
        UIGuide_XiaoYao_3 = {
          ContentDE = "Una vez expuesto, Xiaoyao puede huir y poseer otro objeto cercano.\n Sigue su rastro y atrápalo.\n Si no lo atrapas a tiempo, perderás la pista y la persecución terminará.",
          TextMapId = "UIGuide_XiaoYao_3"
        },
        UIGuide_XiaoYao_4 = {
          ContentDE = "Cuando Xiaoyao huya, puede dejar tras de sí Caminos de Wishen, que te permiten desplazarte rápidamente a otros lugares.",
          TextMapId = "UIGuide_XiaoYao_4"
        }
      }
    end
  },
