        UI_COMMONPOP_TEXT_100058_2 = {
          ContentDE = "Las recompensas y puntos se basarán en tu progreso actual.",
          TextMapId = "UI_COMMONPOP_TEXT_100058_2"
        },
        UI_COMMONPOP_TEXT_100066 = {
          ContentDE = "Un Sello de compañero de combate está usando esta arma. ¿Vender de todos modos?",
          TextMapId = "UI_COMMONPOP_TEXT_100066"
        },
        UI_COMMONPOP_TEXT_100066_2 = {
          ContentDE = "¿Autoequipar Cuñas Demoníacas? Las Cuñas Demoníacas usadas actualmente se removerán",
          TextMapId = "UI_COMMONPOP_TEXT_100066_2"
        },
        UI_COMMONPOP_TEXT_100067 = {
          ContentDE = "Autoequipamiento no disponible: No se encontraron Cuñas Demoníacas adecuadas",
          TextMapId = "UI_COMMONPOP_TEXT_100067"
        },
        UI_COMMONPOP_TEXT_100071 = {
          ContentDE = "¿Seguro que quieres rechazar todas las solicitudes de amistad pendientes?",
          TextMapId = "UI_COMMONPOP_TEXT_100071"
        },
        UI_COMMONPOP_TEXT_100072 = {
          ContentDE = "Actualmente está sujeto a las medidas de protección contra la adicción.\nDe acuerdo con las directrices de la Administración Nacional de Prensa y Publicaciones sobre la prevención de la dependencia de los menores a los juegos en línea, las cuentas de menores solo pueden iniciar sesión una hora al día, de 20:00 a 21:00, los viernes, sábados, domingos y días festivos.\nPor favor, gestione su tiempo de juego de manera responsable y disfrute de una vida equilibrada.",
          TextMapId = "UI_COMMONPOP_TEXT_100072"
        },
        UI_COMMONPOP_TEXT_100073 = {
          ContentDE = "Tu cuenta (UID: %d) ha iniciado sesión en otro dispositivo y esta sesión se cerrará.",
          TextMapId = "UI_COMMONPOP_TEXT_100073"
        },
        UI_COMMONPOP_TEXT_100074 = {
          ContentDE = "Conexión fallida. No se puede conectar al servidor; vertifique su conexión de red.",
          TextMapId = "UI_COMMONPOP_TEXT_100074"
        },
        UI_COMMONPOP_TEXT_100075 = {
          ContentDE = "Necesitas reiniciar el juego para aplicar el cambio de idioma. ¿Reiniciar ahora?",
          TextMapId = "UI_COMMONPOP_TEXT_100075"
        },
        UI_COMMONPOP_TEXT_100076 = {
          ContentDE = "¿Bloquear a este jugador?",
          TextMapId = "UI_COMMONPOP_TEXT_100076"
        },
        UI_COMMONPOP_TEXT_100076_2 = {
          ContentDE = "Tras bloquear a este jugador, ya no se te emparejará con él.",
          TextMapId = "UI_COMMONPOP_TEXT_100076_2"
        },
        UI_COMMONPOP_TEXT_100076_3 = {
          ContentDE = "¿Quieres denunciar y bloquear a este usuario?",
          TextMapId = "UI_COMMONPOP_TEXT_100076_3"
        },
        UI_COMMONPOP_TEXT_100077 = {
          ContentDE = "¿Eliminar a este jugador de tu lista de amigos?",
