        },
        UI_COMMONPOP_TEXT_100078 = {
          ContentDE = "Se ha detectado el uso no autorizado de complementos de terceros en tu cuenta. La conexión al servidor se ha interrumpido.",
          TextMapId = "UI_COMMONPOP_TEXT_100078"
