        },
        UI_COMMONPOP_TEXT_100094 = {
          ContentDE = "Energía insuficiente ¿Deseas recuperarla ahora?",
          TextMapId = "UI_COMMONPOP_TEXT_100094"
        },
        UI_COMMONPOP_TEXT_100095 = {
          ContentDE = "¿Seguro que deseas gastar <H>%s</> de Phoxene para restaurar <H>%d</> de energía?",
          TextMapId = "UI_COMMONPOP_TEXT_100095"
        },
        UI_COMMONPOP_TEXT_100096 = {
          ContentDE = "¿Quieres abandonar el desafío?",
          TextMapId = "UI_COMMONPOP_TEXT_100096"
        },
        UI_COMMONPOP_TEXT_100098 = {
          ContentDE = "Los materiales seleccionados incluyen Cuñas Demoníacas bloqueadas. Se desbloquearán al iniciar la forja.\n¿Seguro que quieres usar estas Cuñas Demoníacas para forjar %s?",
          TextMapId = "UI_COMMONPOP_TEXT_100098"
        },
        UI_COMMONPOP_TEXT_100099 = {
          ContentDE = "Los materiales seleccionados incluyen Cuñas Demoníacas mejoradas; y sus materiales de mejora no serán devueltos tras el proceso de forja.\n¿Seguro que quieres usar estas Cuñas Demoníacas para forjar %s?",
          TextMapId = "UI_COMMONPOP_TEXT_100099"
        },
        UI_COMMONPOP_TEXT_100099_2 = {
          ContentDE = "Los objetos equipados se removerán automáticamente al consumirse en forja.",
          TextMapId = "UI_COMMONPOP_TEXT_100099_2"
        },
        UI_COMMONPOP_TEXT_100100 = {
          ContentDE = "¿Usar los tintes seleccionados para colorear este objeto?",
          TextMapId = "UI_COMMONPOP_TEXT_100100"
        },
        UI_COMMONPOP_TEXT_100103 = {
          ContentDE = "¿Iniciar un intento de <H>prueba de %s</> para obtener este objeto?\n(Dificultad: %d)",
          TextMapId = "UI_COMMONPOP_TEXT_100103"
        },
        UI_COMMONPOP_TEXT_100109 = {
          ContentDE = "Inicio de sesión no disponible por problemas de red. Inténtalo más tarde.",
          TextMapId = "UI_COMMONPOP_TEXT_100109"
        },
        UI_COMMONPOP_TEXT_100111 = {
          ContentDE = "Has sido silenciado por lenguaje inapropiado. La restricción se levantará en %d día(s), %d hora(s), %d minuto(s).",
          TextMapId = "UI_COMMONPOP_TEXT_100111"
        },
        UI_COMMONPOP_TEXT_100114 = {
          ContentDE = "¿Está seguro de que desea mejorar este Geniemon?",
          TextMapId = "UI_COMMONPOP_TEXT_100114"
        },
        UI_COMMONPOP_TEXT_100115 = {
          ContentDE = "¿Está seguro de que desea ascender este Geniemon?",
          TextMapId = "UI_COMMONPOP_TEXT_100115"
        },
        UI_COMMONPOP_TEXT_100116 = {
          ContentDE = "El nivel de su personaje es muy inferior al recomendado para este encargo. ¿Desea continuar de todas formas?",
          TextMapId = "UI_COMMONPOP_TEXT_100116"
        },
        UI_COMMONPOP_TEXT_100117 = {
          ContentDE = "¿Desafiar [%s] ahora?",
          TextMapId = "UI_COMMONPOP_TEXT_100117"
        },
        UI_COMMONPOP_TEXT_100118 = {
          ContentDE = "¿Seguro que quieres consumir los materiales de Amplificación seleccionados para realizar la Amplificación?",
          TextMapId = "UI_COMMONPOP_TEXT_100118"
        },
        UI_COMMONPOP_TEXT_100119 = {
          ContentDE = "Entre los materiales de Amplificación seleccionados hay Cuñas Demoníacas de Nivel superior a 0. ¿Quieres continuar con la Amplificación?",
          TextMapId = "UI_COMMONPOP_TEXT_100119"
        },
        UI_COMMONPOP_TEXT_100121 = {
          ContentDE = "{性别:Querido Phoxcazador|Querida Phoxcazadora},\nLamentamos informarle que no es elegible para la Primera Prueba Beta Cerrada. Agradecemos profundamente su apoyo y entusiasmo por el juego.",
          TextMapId = "UI_COMMONPOP_TEXT_100121"
        },
        UI_COMMONPOP_TEXT_100135_1 = {
          ContentDE = "¿Restablecer todas las partes a colores por defectos?",
          TextMapId = "UI_COMMONPOP_TEXT_100135_1"
        },
        UI_COMMONPOP_TEXT_100135_2 = {
          ContentDE = "No se devolverán los tintes utilizados.",
          TextMapId = "UI_COMMONPOP_TEXT_100135_2"
