        UI_WEAPON_DESC_10101 = {
          ContentDE = "Die Waffe, die Berenica trägt. Eine Klinge mit goldenen Verzierungen. Die Klinge besteht aus einem seltenen schwarzen Metall. Dies ist eindeutig keine Waffe eines der Dorfbewohner der Purgatorio-Insel.\n ",
          TextMapId = "UI_WEAPON_DESC_10101"
        },
        UI_WEAPON_DESC_10102 = {
          ContentDE = "Mögen ausgelassene Festlichkeiten deine Einsamkeit lindern.",
          TextMapId = "UI_WEAPON_DESC_10102"
        },
        UI_WEAPON_DESC_10103 = {
          ContentDE = "Ein Schwert von unbekannter Herkunft. Ein Schwert, das bereits seit Urzeiten existiert. Vielleicht wird es eines Tages zum Schlüssel für die Verbindung zwischen Vergangenheit und Gegenwart.",
          TextMapId = "UI_WEAPON_DESC_10103"
        },
        UI_WEAPON_DESC_10104 = {
          ContentDE = "Die beste Verteidigung ist ein starker Angriff – aber vergiss nicht die Bedeutung von ausreichender Erholung.",
          TextMapId = "UI_WEAPON_DESC_10104"
        },
        UI_WEAPON_DESC_10105 = {
          ContentDE = "Ich werde eine Reise jenseits des Sandes antreten, genau wie du.",
          TextMapId = "UI_WEAPON_DESC_10105"
        },
        UI_WEAPON_DESC_10198 = {
          ContentDE = "Ein Schwert, veredelt mit den neuesten Technologien zur Oberflächenbehandlung – beliebt bei Rittern, die für ihre Loyalität und Disziplin bekannt sind.",
          TextMapId = "UI_WEAPON_DESC_10198"
        },
        UI_WEAPON_DESC_10199 = {
          ContentDE = "Ein gewöhnliches Schwert. Aus dem billigsten Metall hergestellt, also ist es nicht schlimm, wenn es zerbricht.",
          TextMapId = "UI_WEAPON_DESC_10199"
        },
        UI_WEAPON_DESC_10201 = {
          ContentDE = "Küss mich! Knutsch mich! Bevor der morgige Tag anbricht, bevor junge Herzen altern und bevor der Tod uns scheidet.",
          TextMapId = "UI_WEAPON_DESC_10201"
        },
        UI_WEAPON_DESC_10202 = {
          ContentDE = "Eine Stangenwaffe, die die Sternenweber aus ihrer Heimat mitgebracht haben – Huaxu. Form und Farbe der Klinge sind von einer besonderen Pflanze in Huaxu inspiriert, die man Weide nennt. In Huaxu symbolisiert diese Pflanze normalerweise die „Heimat“. Die Sternenweber sind zwar gerade damit beschäftigt, jeden Zentimeter von Atlasia mit Sternenhimmeln zu überziehen, aber irgendwann werden sie in ihre grüne Heimat mit den üppigen Weiden zurückkehren.",
          TextMapId = "UI_WEAPON_DESC_10202"
        },
        UI_WEAPON_DESC_10203 = {
          ContentDE = "Die Jahre vergehen, und die Erdenbewohner werden immer durchschnittlicher.",
          TextMapId = "UI_WEAPON_DESC_10203"
        },
        UI_WEAPON_DESC_10204 = {
          ContentDE = "Einst vergrub ich einen Samen in der gefrorenen Erde und hoffte auf einen Erntemond, der vielleicht niemals kommen würde.",
          TextMapId = "UI_WEAPON_DESC_10204"
        },
        UI_WEAPON_DESC_10205 = {
          ContentDE = "Eine Sense, die vom Ritterorden der Heiligen Iris der Elysischen Kirche geführt wird. „Heilige Erhebung!“ Geheiligt sei das Licht der göttlichen Barmherzigkeit, das die andauernde Narretei der Unweisen zerschmettert.",
          TextMapId = "UI_WEAPON_DESC_10205"
        },
        UI_WEAPON_DESC_10206 = {
          ContentDE = "Verfall ist das Ende des Lebens; akzeptiere ihn, und du wirst in einen ewigen und friedlichen Hafen segeln.",
          TextMapId = "UI_WEAPON_DESC_10206"
        },
        UI_WEAPON_DESC_10207 = {
          ContentDE = "Die Wut des Ozeans einfangend, bringt sein azurblauer Kristall die Gnadenbitte des Feindes zum Verstummen, bevor sie die Ruhe dieses Reiches stören kann. Die Gnadengesuche des Feindes sind dissonante Klänge, die erstickt werden müssen, bevor sie aus der Partitur dieses Reiches entweichen können.",
          TextMapId = "UI_WEAPON_DESC_10207"
        },
        UI_WEAPON_DESC_10208 = {
          ContentDE = "Eine Taube, die schwor, die Würde zu verteidigen, und jede Feder für den Frieden opfert.",
          TextMapId = "UI_WEAPON_DESC_10208"
        }
      }
    end
  },
  {
    MinKey = "UI_WEAPON_DESC_10209",
