        },
        UI_WEAPON_DESC_20296 = {
          ContentDE = "Doppelpistolen, die mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurden – beliebt bei allen, die gerne unter freiem Himmel reisen.",
          TextMapId = "UI_WEAPON_DESC_20296"
        },
        UI_WEAPON_DESC_20298 = {
          ContentDE = "Gewöhnliche Doppelpistolen. Aus dem billigsten Metall hergestellt, also ist es nicht schlimm, wenn es zerbricht.",
          TextMapId = "UI_WEAPON_DESC_20298"
        },
        UI_WEAPON_DESC_20301 = {
          ContentDE = "Die Bußfertigen sollen nicht länger zu den Sternen aufblicken – der Himmel schenkt ihnen kein Gehör, und die Sterne gewähren ihnen keine Absolution.",
          TextMapId = "UI_WEAPON_DESC_20301"
        },
        UI_WEAPON_DESC_20302 = {
          ContentDE = "Abenddämmerung, rote Tanzschuhe und Tau auf Rosen; ein Luftzug streift die Schläfen, das entrüstete Kreischen schneller Schüsse und der Geruch von Schießpulver ... Alle bezeugen ein Fest der Projektile.",
          TextMapId = "UI_WEAPON_DESC_20302"
        },
        UI_WEAPON_DESC_20303 = {
          ContentDE = "Die wahrhaftigste Rückkehr zur Natur besteht darin, zu Asche zu zerfallen und in der wartenden Erde zu versinken.",
          TextMapId = "UI_WEAPON_DESC_20303"
        },
        UI_WEAPON_DESC_20304 = {
          ContentDE = "Bronze härtet den stählernen Rahmen; inmitten von Dornen, eine Seele, geschmiedet für den Anspruch auf Heldentum.",
          TextMapId = "UI_WEAPON_DESC_20304"
        },
        UI_WEAPON_DESC_20305 = {
          ContentDE = "Hellfire reitet auf eintausend silbernen Geschossen, die auf den Boden herabregnen, das Edikt der Götter in die Herzen aller Ketzer einätzend.",
          TextMapId = "UI_WEAPON_DESC_20305"
        },
        UI_WEAPON_DESC_20398 = {
          ContentDE = "Ein Granatwerfer, der mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurde – beliebt bei furchtlosen Belagerungsbrechern.",
          TextMapId = "UI_WEAPON_DESC_20398"
        },
        UI_WEAPON_DESC_20399 = {
          ContentDE = "Ein Granatwerfer, gefertigt unter Verwendung der neuesten Schmelz- und Vergoldungstechniken. Dieses Modell ist eine klare Empfehlung von Schmiedemeistern. Die perfekte Balance zwischen Qualität und Erschwinglichkeit macht es zu einer beliebten Wahl bei Reisenden in ganz Atlasia.",
          TextMapId = "UI_WEAPON_DESC_20399"
        },
        UI_WEAPON_DESC_20401 = {
          ContentDE = "Erst wenn der letzte Schrei verklungen ist ... kann wieder Ruhe in die Welt einkehren.",
          TextMapId = "UI_WEAPON_DESC_20401"
        },
        UI_WEAPON_DESC_20402 = {
          ContentDE = "Stecke Blumensamen in den Körper, damit die Zerstörung von innen heraus erblühen kann.",
          TextMapId = "UI_WEAPON_DESC_20402"
        },
        UI_WEAPON_DESC_20403 = {
          ContentDE = "Eine Feuerwaffe, die vom Ritterorden der Heiligen Iris der Elysischen Kirche eingesetzt wird. Heilige Erhebung! Wir geloben, die Botschaft der Großen Neun in ganz Atlasia zu verbreiten.",
          TextMapId = "UI_WEAPON_DESC_20403"
        },
        UI_WEAPON_DESC_20405 = {
