        UI_WeaponSkin_Des_3010101 = {
          ContentDE = "Ein wahrer Angler kehrt nie mit leeren Händen nach Hause zurück. Ein Glück, dass auf dem Fischmarkt ein Ausverkauf stattfand – 80 Münzen pro Stück, aber das muss ja niemand wissen.",
          TextMapId = "UI_WeaponSkin_Des_3010101"
        },
        UI_WeaponSkin_Des_3010102 = {
          ContentDE = "Unmittelbar vor ihrer Kollision küssten sich die Sterne zum Abschied. Ihr zerschmettertes Flüstern verwandelte sich in Feuerstreifen – der Atem der Liebenden, hinweggetrieben über die Milchstraße.",
          TextMapId = "UI_WeaponSkin_Des_3010102"
        },
        UI_WeaponSkin_Des_3010104 = {
          ContentDE = "Ein Großschwert von ungewöhnlicher Ausführung, angeblich die Liebe eines Vaters verkörpernd: streng, belehrend und ein wenig traumatisierend.",
