  {
    MinKey = "WeaponType_Polearm",
    MaxKey = "WikiText_40800301",
    Loader = function()
      return {
        WeaponType_Polearm = {
          ContentDE = "Stangenwaffe",
          TextMapId = "WeaponType_Polearm"
        },
        WeaponType_Shotgun = {
          ContentDE = "Schrotflinte",
          TextMapId = "WeaponType_Shotgun"
        },
        WeaponType_Sword = {
          ContentDE = "Schwert",
          TextMapId = "WeaponType_Sword"
        },
        WeaponType_Swordwhip = {
          ContentDE = "Peitschenschwert",
          TextMapId = "WeaponType_Swordwhip"
        },
        Weapon_BreakLevelUp_Success = {
          ContentDE = "Arma ascendida",
          TextMapId = "Weapon_BreakLevelUp_Success"
        },
        Weapon_LevelUp_Success = {
          ContentDE = "Arma mejorada",
          TextMapId = "Weapon_LevelUp_Success"
        },
        WeeklyDungeonShop = {
          ContentDE = "Recompensas de cacería",
          TextMapId = "WeeklyDungeonShop"
        },
        WikiText_10100301 = {
          ContentDE = "Eine Monarchie im hohen Norden des Kontinents Atlasia, gegründet vor einem Jahrtausend von Elysianern, die während der Großen Migration nach Norden zogen. Der Name Hyperborea bedeutet „das Land des äußersten Nordens“.\n Im Jahr 20 des Neuen Kalenders wurde Dis Galea auf der Burg Icelake als Dis I. gekrönt, womit das Hyperboreische Imperium offiziell begründet wurde. Im Jahr 47 verlegte Kaiserin Bellona I. die Hauptstadt nach Dismania.\n Die Geschichte des Imperiums ist eine Geschichte der Eroberung. Durch die Beherrschung von Phoxichor und alchemistischer Technologie sichert Hyperborea seine Herrschaft mit militärischer Gewalt. Bis heute steht es in einem langanhaltenden Konflikt mit der Elysischen Kirche, deren Gläubige die Großen Neun verehren.\n Der derzeitige Kaiser des Hyperboreischen Imperiums ist Julius.",
          TextMapId = "WikiText_10100301"
        },
        WikiText_10100401 = {
          ContentDE = "Eine innerhalb des Hyperboreischen Imperiums aktive Widerstandsgruppe, die sich überwiegend aus Charons zusammensetzt, die der imperialen Herrschaft überdrüssig geworden sind. Mit verschiedenen, teils extremen Methoden versucht sie, politische Entscheidungen zu beeinflussen – und in manchen Fällen sogar das Imperium selbst zu stürzen. In den letzten Jahren wurde die Gruppe mit zahlreichen bewaffneten Zusammenstößen und Attentaten im gesamten Reichsgebiet in Verbindung gebracht.",
          TextMapId = "WikiText_10100401"
        },
        WikiText_10100402 = {
          ContentDE = "Einige Mitglieder der Verlassenen besitzen die Fähigkeit, Filthoiden durch spezielle klangbasierte Techniken zu manipulieren, ihre Aggression gezielt zu steigern und sie als lebende Waffen gegen ihre Feinde einzusetzen.",
          TextMapId = "WikiText_10100402"
        },
        WikiText_10100403 = {
          ContentDE = "Innerhalb der Organisation sind die Mitglieder in vier absteigende Rangstufen gegliedert: Bote, Langmähne, Rabe und Wildschwarm.\n Über ihnen allen steht der Nebelschatten – ein Konklave aus sieben Boten, verehrt als höchste Autorität der Verlassenen.",
          TextMapId = "WikiText_10100403"
        },
        WikiText_10100501 = {
          ContentDE = "Die wichtigste Streitmacht des Imperiums, bestehend aus 13 Legionen, von denen jede eine klar definierte Aufgabe erfüllt.\n Die 13. Legion unter dem Kommando von Sibylle untersteht direkt dem Kaiser und ist für spezielle, von ihm persönlich erteilte Einsätze zuständig – insbesondere für solche, die die Verlassenen betreffen.",
          TextMapId = "WikiText_10100501"
        },
        WikiText_10100601 = {
          ContentDE = "Die militärische Einheit, die für die Aufrechterhaltung von öffentlicher Ordnung und Sicherheit in Icelake zuständig ist. Sie untersteht dem Kommando der 6. Legion des Imperiums.",
          TextMapId = "WikiText_10100601"
        },
        WikiText_10100602 = {
          ContentDE = "Obwohl die Eskorte offiziell den Schutz aller Bürger Icelakes gewährleisten soll, richtet sich ihr Augenmerk häufig unverhältnismäßig stark auf Angelegenheiten der Solarian. Einzelne Angehörige der Einheit missbrauchen ihre Autorität sogar offen und behandeln Charon-Zivilisten unter dem Vorwand der Ordnungssicherung schlecht.",
          TextMapId = "WikiText_10100602"
        },
        WikiText_10100701 = {
          ContentDE = "Eine offizielle akademische Institution des hyperboreischen Imperiums.\n Die Alchemisten Hyperboreas ähnelten einst ihren Pendants auf dem restlichen Kontinent – geheimnisvolle Gestalten, losgelöst vom Alltagsleben. Dies änderte sich unter Königin Bellona II., die die Königliche Alchemie-Akademie gründete und die Rolle der Alchemisten im Imperium schrittweise neu definierte.\n Ursprünglich eine kleine Gelehrtengemeinschaft, vereinte die Akademie unter königlicher Schirmherrschaft die klügsten Köpfe des Reiches, um legendäre Ziele zu verfolgen, etwa die militärische Nutzung der Elementarumwandlung. Zwar wurden diese Ambitionen nie verwirklicht, doch führten Jahrhunderte der Forschung schließlich zur Entdeckung von Phoxichor – einer aus Phoxenen gewonnenen Energiequelle von goldgleichem Wert. Dieser Durchbruch markierte den Beginn der Phoxene-Technologie und rückte die Alchemisten ins Zentrum der nationalen Entwicklung. Mit der Zeit wurden sie zu Synonymen imperialer Gelehrsamkeit und im Staatsdienst eingesetzt, um Industrie, Infrastruktur und militärische Schlagkraft durch phoxenebasierte Technologien voranzutreiben. Die Akademie selbst entwickelte sich zu einem weitverzweigten Netzwerk von Forschungsstätten in den großen Städten des Imperiums.\n Heute ist die Akademie in zwei Hauptzweige gegliedert: das Aeolipile und die Spathatoi. Das Aeolipile, auch Alte Akademie genannt, führt den ursprünglichen Auftrag fort und konzentriert sich auf mechanische Erfindungen, Ingenieurprojekte und die Entwicklung von Waffen auf Basis der Phoxene-Technologie. Die Spathatoi hingegen, auch Neue Akademie, wurden von Kaiser Julius I. mit Unterstützung der 13. Legion gegründet. Sie übernahmen die früheren biologischen Disziplinen der Akademie und führen heute die Forschung in den Lebenswissenschaften, der Medizin und der Charon-Magie an.",
          TextMapId = "WikiText_10100701"
        },
        WikiText_10100801 = {
          ContentDE = "Der Hyperboreische Militärrat fungiert als zentrale Verwaltungsinstanz des Imperiums. Seine Mitglieder werden direkt vom Kaiser ernannt und unterstützen ihn in Fragen der Staatsführung. Im Gegensatz zum von Aristokraten dominierten Senat umfasst der Militärrat auch Personen niederer Herkunft, die durch Leistung und außergewöhnliche Fähigkeiten aufgestiegen sind.",
          TextMapId = "WikiText_10100801"
        },
        WikiText_10100901 = {
          ContentDE = "Ein theokratischer Staat im Süden des Kontinents Atlasia, zentriert um einen heiligen Turm, an dem der Legende nach einst neun Gottheiten erschienen sind. Als die älteste aller menschlichen Zivilisationen angesehen, folgt Elysium dem elysischen orthodoxen Glauben, der die Großen Neun verehrt. Sämtliche weltlichen Angelegenheiten werden von der Elysischen Kirche verwaltet, welche den göttlichen Willen auslegt.\n Der Glaube predigt Ideale von Gerechtigkeit und geteilter Freude und ermöglichte über Jahrtausende hinweg ein friedliches Zusammenleben der verschiedenen Völker unter seiner Herrschaft.",
          TextMapId = "WikiText_10100901"
        },
        WikiText_10101001 = {
          ContentDE = "Ein Phoxjäger-Team, gegründet von {nickname}, Outsider und Snow.\n Während Outsider und Snow vorschlugen, die Gruppe „Praktikanten für die 99 innovativen Kochstile köstlicher geflügelter Hexapoden der Dämonenkönigin des Ultralichts aus der reinweißen Inferno“ zu nennen, ließ sich {nickname} letztlich von den Worten der mysteriösen Gestalt in {性别:seinem|ihrem} Traum inspirieren und wählte Nachtfahrer – ein Name schlicht in der Form, doch von stiller Bedeutung.",
          TextMapId = "WikiText_10101001"
        },
        WikiText_20100101 = {
          ContentDE = "Ein wortkarges Mädchen, unberührt von den Wegen der Welt. Sie lebt gemeinsam mit {nickname} in einem Dorf auf der Purgatorio-Insel. Seit ihrer Kindheit haben sie sich gegenseitig gestützt und betrachten einander als Familie, enger noch als durch Blut verbunden.",
          TextMapId = "WikiText_20100101"
        },
        WikiText_20100102 = {
          ContentDE = "Vom hyperboreischen Militär als „Nr. 0“ bezeichnet, ist sie seit Langem Ziel einer andauernden Jagd. Nach einer Konfrontation mit Sibylle ist ihr gegenwärtiger Aufenthaltsort unbekannt.",
          TextMapId = "WikiText_20100102"
        },
        WikiText_20100201 = {
          ContentDE = "Sibylle Mason, Großkommandantin der 13. Legion des Hyperboreischen Imperiums. Sie erschien auf der Purgatorio-Insel auf der Jagd nach Berenica, die sie als „Nr. 0“ bezeichnet.",
          TextMapId = "WikiText_20100201"
        },
        WikiText_20100301 = {
          ContentDE = "Randy Howard ist Offizier der 13. Legion des Hyperboreischen Imperiums und dient derzeit als Adjutant von Großkommandantin Sibylle.",
          TextMapId = "WikiText_20100301"
        },
        WikiText_20100401 = {
          ContentDE = "Camilla Scarlet, Besitzerin des Asphodel, einer bekannten Taverne in Icelake. Gewandt und hervorragend vernetzt.\n Sie wurde von einer geheimnisvollen, weiß gekleideten Gestalt damit betraut, {nickname} zu retten und {性别:ihm|ihr} während {性别:seines|ihres} vorübergehenden Aufenthalts in Icelake beizustehen.",
          TextMapId = "WikiText_20100401"
        },
        WikiText_20100501 = {
          ContentDE = "Eine Luno, die gemeinsam mit Camilla {nickname} gerettet hat. Erkennbar an einem Paar dämonenartiger Hörner, die an jene der Charon erinnern, spricht sie in übertrieben pathetischer, geradezu theatralischer Weise.",
          TextMapId = "WikiText_20100501"
        },
        WikiText_20100502 = {
          ContentDE = "Sie bezeichnet sich selbst als die „Reinweiße Erlöserin ☆ Dämonenkönigin des Lichts“. Obwohl sie – anders als die meisten Luno – offenbar kein Verlangen nach menschlicher Bewunderung verspürt, gleicht ihr Verhalten dem ihren in nahezu jeder anderen Hinsicht.",
          TextMapId = "WikiText_20100502"
        },
        WikiText_20100601 = {
          ContentDE = "Henrik Ethelred, Besitzer des Gasthauses namens Hypnos’ Haus. Ein distanzierter, wortkarger Mann, der für sein tiefes Misstrauen gegenüber Fremden bekannt ist.",
          TextMapId = "WikiText_20100601"
        },
        WikiText_20100602 = {
          ContentDE = "Einst ein angesehener Arzt in Icelake, war Henrik für seine außergewöhnlichen Fähigkeiten weithin bekannt – zu seinen Patienten zählten sogar Adlige aus der Innenstadt. Nach dem frühen Tod seiner Frau zog er ihre einzige Tochter Hayley allein groß.\n Vor einigen Jahren wurde er während einer Reise nach Scarletriver wegen Mordes verhaftet und inhaftiert. Da es sich bei dem Opfer um einen Charon mit Anzeichen der Verderbnis handelte, verbüßte Henrik nur eine kurze Haftstrafe und wurde anschließend freigelassen. Er kehrte allein nach Icelake zurück. Hayley wurde nie wieder gesehen.",
          TextMapId = "WikiText_20100602"
        },
        WikiText_20100603 = {
          ContentDE = "Der von Henrik getötete Charon war in Wahrheit seine eigene Tochter. Als Hayley erste Anzeichen der Verderbnis zeigte, brachte Henrik sie nach Scarletriver, um nach einer Heilung zu suchen, und begann mit der Erforschung eines unterdrückenden Medikaments. Doch die Krankheit schritt schneller voran, als seine Arbeit vollendet werden konnte.\n Um ihr das Schicksal zu ersparen, zu einem Filthoid zu werden, beendete Henrik ihr Leben mit eigenen Händen – und ließ seine Tochter in der Würde eines Menschen aus dieser Welt scheiden.",
          TextMapId = "WikiText_20100603"
        },
        WikiText_20100701 = {
          ContentDE = "Psyche Frey, ein fröhliches, lebenslustiges Mädchen, das sowohl als Untermieterin als auch als Gehilfin im Hypnos’ Haus lebt.",
          TextMapId = "WikiText_20100701"
        },
        WikiText_20100702 = {
          ContentDE = "Psyche liebte es von Herzen, Blumen und Pflanzen zu pflegen. Doch infolge einer Krankheit verschlechterte sich ihr Sehvermögen zunehmend, bis sie schließlich vollständig erblindete.",
          TextMapId = "WikiText_20100702"
        },
        WikiText_20100703 = {
          ContentDE = "Im Alter von siebzehn Jahren, nachdem bei ihr erste Anzeichen der Verderbnis aufgetreten waren, blieb Psyche keine andere Wahl, als sich von ihren leiblichen Eltern zu trennen und im Hypnos’ Haus Zuflucht zu suchen.\n Als sich ihr Zustand weiter verschlechterte, meldete sie sich freiwillig für Henriks experimentelles Mittel zur Unterdrückung der Verderbnis – festklammernd an einen letzten, schwachen Hoffnungsschimmer. Doch die Behandlung scheiterte: Das Medikament beschleunigte den Verlauf der Krankheit, und schließlich verwandelte sie sich in einen Filthoid.\n Außerhalb von Icelake begegnete sie {nickname}. Durch {nickname}s Worte erlangte sie für einen kurzen Moment ihr Bewusstsein zurück und erinnerte sich daran, wer sie einst gewesen war. Unwillig, als Monster weiterzuleben, entschied sie sich dafür, ihrem Leben selbst ein Ende zu setzen.",
          TextMapId = "WikiText_20100703"
        },
        WikiText_20100801 = {
          ContentDE = "Ein aufgewecktes, lebensfrohes Plünderermädchen aus Icelake. Warmherzig und hilfsbereit teilt sie ihre Funde stets mit den Bedürftigen in ihrer Umgebung. Die Menschen aus den Slums nennen sie liebevoll die „Prinzessin Mülleimer“. {nickname}s Weg als {性别:Phoxjäger|Phoxjägerin} begann ihretwegen – mit einem Auftrag, ihre gestohlene Geldbörse zurückzuholen.",
          TextMapId = "WikiText_20100801"
        },
        WikiText_20100901 = {
          ContentDE = "Ein gewandter Phoxjäger aus Icelake, freiheitsliebend, schlagfertig und mit einer Neigung, den Mund etwas zu voll zu nehmen. Er kreuzte erstmals den Weg von {nickname}, als er einen Auftrag verfolgte, der sich um das seltene Mineral Kristallo von Stella drehte.",
          TextMapId = "WikiText_20100901"
        },
        WikiText_20101001 = {
          ContentDE = "Ein Charon-Mädchen von zarter Gesundheit und die jüngere Schwester von Outsider. Sie lebt weitgehend zurückgezogen. Besessen von Märchen spricht und handelt Fina, als wäre sie selbst eine Figur aus einer solchen Geschichte – lieblich, unschuldig, verträumt und ein wenig verloren in ihrem Staunen.",
          TextMapId = "WikiText_20101001"
        },
        WikiText_20101002 = {
          ContentDE = "Inspiriert durch ihre Begegnung mit {nickname} begann Fina, sich nach der Welt jenseits ihres Zuhauses zu sehnen. Ermutigt von Outsider wagte sie den Schritt nach draußen, schloss viele neue Freundschaften und traf unerwartet ihren einzigen noch lebenden Verwandten, Savio, wieder.\n Ihre Liebe zu Märchen verlieh ihr die Fähigkeit, Gefährten aus Geschichten herbeizurufen, ihre lebhafte Fantasie Wirklichkeit werden zu lassen und ihr den Mut zu geben, jeder Gefahr zu begegnen.",
          TextMapId = "WikiText_20101002"
        },
        WikiText_20101101 = {
          ContentDE = "Rhythm Fischer, ein Feldwebel der Eskorte unter dem 6. Legion. Bekannt für ihren Fleiß und ihre Disziplin stellt sie den Schutz der Zivilbevölkerung stets an erste Stelle.",
          TextMapId = "WikiText_20101101"
        },
        WikiText_20101102 = {
          ContentDE = "In Mist Aken geboren und in Armut aufgewachsen, entwickelte Rhythm ein tiefes Mitgefühl für benachteiligte Charon-Bürger. Auch über ihre offiziellen Pflichten hinaus setzte sie sich häufig persönlich dafür ein, ihnen zu helfen.",
          TextMapId = "WikiText_20101102"
        },
        WikiText_20101103 = {
          ContentDE = "Rhythm nahm einst gemeinsam mit ihrem jüngeren Bruder Blues an den Aufnahmeprüfungen der 6. Legion teil. Zwar bestand sie diese nicht, trat jedoch später der Icelake-Eskorte bei.",
          TextMapId = "WikiText_20101103"
        },
        WikiText_20101104 = {
          ContentDE = "In ihrer Kindheit wurden Rhythms Eltern getötet, nachdem sie unwissentlich einen Verdorbenen beherbergt hatten – ein Vorfall, der zu schweren zivilen Verlusten führte. Seitdem schwor sie, niemals wieder zuzulassen, dass jemand einem Filthoid zum Opfer fällt.",
          TextMapId = "WikiText_20101104"
        },
        WikiText_20101105 = {
          ContentDE = "In Wahrheit war es Rhythm selbst, die ihre Eltern dazu gedrängt hatte, den Verdorbene aufzunehmen. Die Last dieser Schuld trägt sie seither ununterbrochen mit sich.",
          TextMapId = "WikiText_20101105"
        },
        WikiText_20101106 = {
          ContentDE = "Für ihr herausragendes Handeln während der Ermittlungen zur Jagd auf Charon wurde Rhythm mit dem Titel Lorbeerkranz-Charon ausgezeichnet. Doch nachdem sie sowohl einen geliebten Menschen als auch ihren Lebenssinn verloren hatte, legte sie schließlich ihren Dienst bei der Eskorte nieder.",
          TextMapId = "WikiText_20101106"
        },
        WikiText_20101201 = {
          ContentDE = "Daphne Theodore, Sanitäterin im Feldeinsatz der 13. Legion, von ruhigem und sanftem Wesen. Außergewöhnlich begabt und gewissenhaft studierte sie einst unter dem Chefalchemisten der Alchemie-Akademie von Hyperborea und galt weithin als aufstrebendes Talent. Aus persönlicher Überzeugung verließ sie schließlich die Akademie, um als Medizinerin in der Legion zu dienen, wo sie zu einer engen Gefährtin von {nickname2} wurde.",
          TextMapId = "WikiText_20101201"
        },
        WikiText_20101202 = {
          ContentDE = "Die Tochter von Avar. Obwohl er niemals die Gründe für seine Abwesenheit aussprach, erlaubte Daphnes Scharfsinn ihr, die Wahrheit selbst zu erkennen. Dankbar für seine stille Liebe und sein Opfer ist sie zu der Überzeugung gelangt, ihren eigenen Weg gehen zu müssen – nicht als ein Kind, das von anderen beschützt wird, sondern als Gleichgestellte, die der Welt an ihrer Seite entgegentritt.",
          TextMapId = "WikiText_20101202"
        },
        WikiText_20101301 = {
          ContentDE = "Avar Hrodland, Hauptmann der Einheit Schneewölfe der 13. Legion und ehemaliger Ausbilder von {nickname2} während {性别2:seiner|ihrer} Zeit an der Kaiserlichen Militärakademie. Ein erfahrener und verlässlicher Soldat, der sowohl als Mentor als auch als Kamerad großes Ansehen genießt.",
          TextMapId = "WikiText_20101301"
        },
        WikiText_20101302 = {
          ContentDE = "Avar ist der leibliche Vater von Daphne. Vor vielen Jahren, als Kaiser Julius die Politik des Imperiums gegenüber den Charon von Nachsicht zu Unterdrückung wandelte, entschied sich Daphnes Mutter zur Scheidung und änderte den Familiennamen ihrer Tochter offiziell, um deren Zukunft zu schützen.\n Avar stimmte dieser Regelung zu und hielt bewusst die Fassade eines abwesenden und gleichgültigen Vaters aufrecht, um die junge Daphne daran zu hindern, an der Vergangenheit festzuhalten. Selbst nach ihrer Wiederbegegnung innerhalb der Legion wahrte er eine strenge emotionale Distanz, um ihre wahre Beziehung zu verbergen.",
          TextMapId = "WikiText_20101302"
        },
        WikiText_20101303 = {
          ContentDE = "Während der Operation „Lonza-Festung“ deckte Avar Fulvis’ Verschwörung auf und wurde von diesem ermordet, um ihn zum Schweigen zu bringen.",
          TextMapId = "WikiText_20101303"
        },
        WikiText_20101304 = {
          ContentDE = "In einem letzten Versuch, sicherzustellen, dass die Wahrheit hinter dem Lonza-Vorfall nicht begraben würde, entwickelte Avar vor seinem Tod einen Plan. Er inszenierte die Hinrichtung von {nickname2} und schwor Fulvis seine Loyalität vor, um mithilfe dieser Täuschung {nickname2} die Flucht zu ermöglichen. Dabei opferte er sein Leben und hinterließ eine Tonaufnahme als entscheidendes Beweisstück.",
          TextMapId = "WikiText_20101304"
        },
        WikiText_20101401 = {
          ContentDE = "Antonius Fulvis, Oberst der 13. Legion und Kommandant der Operation „Lonza-Festung“.\n Als Spross eines alten hyperboreischen Adelshauses gelangte Fulvis weniger durch militärische Verdienste als durch ererbten Einfluss im Senat in seine Position. Arrogant und selbstsicher ist er dafür bekannt, unbedachte strategische Entscheidungen zu treffen, ohne Rücksicht auf die Sicherheit seiner Untergebenen.",
          TextMapId = "WikiText_20101401"
        },
        WikiText_20101402 = {
          ContentDE = "Ein kompromissloser Extremist unter den Solarian. Fulvis hegt einen tief verwurzelten Hass gegen die Charon. Die frühen versöhnlichen Maßnahmen Kaiser Julius gegenüber der Charon-Bevölkerung betrachtet er als Zeichen von Schwäche; Großkommandantin Sibylle begegnet er mit kaum verhüllter Verachtung, während er insgeheim nach ihrer Position innerhalb der Legion trachtet.\n Während der Operation „Lonza-Festung“ spielte Fulvis den Verlassenen gezielt geheime Informationen zu und fälschte anschließend Beweise, um Avar – einen Charon-Offizier – des Hochverrats zu bezichtigen. Sein eigentliches Ziel war es, eine Säuberung von Charon-Angehörigen aus den oberen Rängen des imperialen Militärs zu erzwingen.",
          TextMapId = "WikiText_20101402"
        },
        WikiText_20101501 = {
          ContentDE = "Eine junge Charon-Frau, die während der Operation „Festung Lonza-Festung“ von der Einheit Greif gefangen genommen wurde. Sie behauptet, kein Mitglied der Verlassenen zu sein, und beteuert, lediglich eine Zivilistin zu sein, die von der Gruppe zwangsrekrutiert wurde, um bei mechanischen Modifikationen innerhalb der Festung zu helfen.",
          TextMapId = "WikiText_20101501"
        },
        WikiText_20101502 = {
          ContentDE = "Vollständiger Name: Katya Oen. Ursprünglich eine Zivilistin, wurde sie vom Imperium zwangsrekrutiert, um Wartungsarbeiten in der Lonza-Festung auszuführen. Während der Besetzung der Festung wurde sie von den Verlassenen gerettet und schloss sich ihnen anschließend an. Katya beteiligte sich am Angriff der Verlassenen auf die Hyperboreische Legion, blieb jedoch absichtlich zurück, als sich die übrigen zurückzogen – sie ergab sich freiwillig, um {nickname2} zu begegnen, der auch als „Der bleiche Schnitter“ bekannt ist. Ihre Beweggründe sind bis heute unklar.",
          TextMapId = "WikiText_20101502"
        },
        WikiText_20101601 = {
          ContentDE = "Ein Soldat der 13. Legion des Hyperboreischen Imperiums, der als Adjutant von Oberst Fulvis dient.",
          TextMapId = "WikiText_20101601"
        },
        WikiText_20101602 = {
          ContentDE = "Falsi gelangte in den Besitz von Avars Tonaufnahme – einem zentralen Beweis im Lonza-Hochverratsfall. Während der Explosion in der Festung wurde sie von ihrer Einheit getrennt und seither nicht mehr gesehen. Die Aufnahme ging bei dem Vorfall verloren, ihr derzeitiger Verbleib ist unbekannt.",
          TextMapId = "WikiText_20101602"
        },
        WikiText_20101701 = {
          ContentDE = "Ein einflussreicher Hochadliger Hyperboreas und ehemaliges führendes Mitglied des Militärrats. Während der frühen Regierungsjahre Kaiser Julius’ diente er als Regent und unterstützte den jungen Herrscher bei der Niederschlagung des Charon-Aufstands sowie bei der Einführung von Reformen zur Verbesserung der Rechte und des gesellschaftlichen Status der Charon – Maßnahmen, die die ethnischen Spannungen innerhalb des Imperiums erheblich milderten.",
          TextMapId = "WikiText_20101701"
        },
        WikiText_20101801 = {
          ContentDE = "Der derzeitige Kaiser des Hyperboreischen Imperiums. Er bestieg den Thron in jungen Jahren und leitete mit Unterstützung von Herzog Servius zunächst eine Reihe von Reformen ein, die darauf abzielten, die Unterdrückung und Marginalisierung der Charon-Bevölkerung zu lindern und die inneren Spannungen des Imperiums zu entschärfen. Aus bislang unbekannten Gründen wurden diese versöhnlichen Maßnahmen später aufgegeben und durch eine zunehmend repressive Politik ersetzt.",
          TextMapId = "WikiText_20101801"
        },
        WikiText_20101901 = {
          ContentDE = "Hellfire Surt dient derzeit als Wächterin des imperialen Militärgefängnisses.\n Als direkte Nachfahrin der Surt-Blutlinie weist sie die charakteristischen Merkmale ihrer Familie auf: eine leuchtend, flammenrot gefärbte Haut sowie eine Körpertemperatur, die so hoch ist, dass kaum jemand sich ihr nähern kann, ohne Verbrennungen zu erleiden.\n Fanatisch der Gerechtigkeit und der Ordnung verpflichtet, vertritt sie eine kompromisslose Haltung gegenüber Täuschung und der Verschleierung der Wahrheit.",
          TextMapId = "WikiText_20101901"
        },
        WikiText_20101902 = {
          ContentDE = "Die Waffe der Wächterin, Inferno, ist ein einzigartiges Artefakt, das ausschließlich innerhalb der Surt-Blutlinie weitergegeben wird. Ihre extreme Hitze und Macht gelten für jeden Träger außerhalb der Familie als unerträglich, wodurch das Amt der Aufseherin seit seiner Einführung faktisch erblich ist.",
          TextMapId = "WikiText_20101902"
        },
        WikiText_20101903 = {
          ContentDE = "Im Verlauf des Lonza-Hochverratsfalls führte Hellfire eine drogeninduzierte hypnotische Vernehmung von {nickname2} durch. Von der Echtheit {性别2:seiner|ihrer} Aussage überzeugt, genehmigte sie eine weitergehende Untersuchung des Falls.",
          TextMapId = "WikiText_20101903"
        },
        WikiText_20102001 = {
          ContentDE = "Ein Prinz des Hyperboreischen Imperiums und der jüngere Bruder von Kaiser Julius.",
          TextMapId = "WikiText_20102001"
        },
        WikiText_20102002 = {
          ContentDE = "Trotz seiner adeligen Herkunft ist Vergilius für sein sanftmütiges Wesen und seine ungezwungenen Umgangsformen bekannt. Er ist ein alter Bekannter von {nickname2}.\n Während der Ermittlungen im Lonza-Hochverratsfall griff Vergilius mit einer vom Kaiser unterzeichneten königlichen Begnadigung ein und erreichte so die Freilassung sowohl von {nickname2} als auch von Daphne noch vor ihrer angesetzten Hinrichtung.",
          TextMapId = "WikiText_20102002"
        },
        WikiText_20102101 = {
          ContentDE = "Ursprünglich unter dem Namen Dis Galea bekannt, erlangte er während der Großen Migration als herausragender Feldherr Berühmtheit und wurde später zum Gründungsherrscher der Galea-Dynastie in Hyperborea.",
          TextMapId = "WikiText_20102101"
        },
        WikiText_20102102 = {
          ContentDE = "Wie kaiserliche Aufzeichnungen belegen, führte Dis Ⅰ in den unruhigen Jahren nach der Nacht des Klagenden Sees die Solarian im Aufstand gegen die Gräueltaten der Charon. Doch nach errungenem Sieg wählte er nicht die Rache, sondern die Vergebung, und so begann die große Epoche, die als der Silberfrieden bekannt ist.",
          TextMapId = "WikiText_20102102"
        },
        WikiText_20102201 = {
          ContentDE = "Die derzeitige Leiterin der Truppe „Die Zauberflöte“. Obwohl sie inzwischen im fortgeschrittenen Alter ist, bleibt sie in ihrer Aufsicht akribisch und unbeirrbar und behält jedes Detail mit außergewöhnlicher Sorgfalt im Blick. Dank ihres kontinuierlichen Einsatzes hält die Truppe seit über einem Jahrzehnt ein konstant hohes Aufführungsniveau und genießt in Icelake weithin Anerkennung für ihre Exzellenz.",
          TextMapId = "WikiText_20102201"
        },
        WikiText_20102301 = {
          ContentDE = "Die führende Sopranistin der Truppe „Die Zauberflöte“ und eine der gefeiertsten Opernkünstlerinnen Hyperboreas, berühmt für ihre meisterhafte stimmliche Ausdruckskraft und ihre wandelbare Bühnenpräsenz. Ihre außergewöhnliche Fähigkeit, Stimme und Erscheinung mühelos zu verändern, brachte ihr den Beinamen „Violetta der tausend Gesichter“ ein.",
          TextMapId = "WikiText_20102301"
        },
        WikiText_20102302 = {
          ContentDE = "Ihr wirklicher Name ist Enola Ruthford, Tochter von Fabrice Ruthford, dem Offizier, der einst für den Glevum-Grube zuständig war.\n Ein Entführungsfall brachte sie erstmals mit Violet in Kontakt, einem Mädchen von bescheidenem Ursprung, das davon träumte, Dramatikerin zu werden. Nach Violets Tod täuschte Enola ihren eigenen Tod vor, nahm mit Hilfe von Violets älterem Bruder Sig den Namen Violetta an und floh nach Luca, um Oper zu studieren.\n Nun eine gefeierte Sängerin, kehrt Violetta nach Hause zurück, um „Putini“ – die Oper, die sie mit ihrer verstorbenen Freundin schrieb – auf die lokale Bühne zu bringen. Sie widmet sich der Ausbildung junger Operntalente, unabhängig von Geburt oder Status.\n Wenn den Gerüchten der Phoxjäger zu glauben ist, hat sie auch heimlich nach einem vermissten Studenten namens Parsifal gesucht.",
          TextMapId = "WikiText_20102302"
        },
        WikiText_20102401 = {
          ContentDE = "Blues Fischer, ein junger Charon aus Icelake, ist der jüngere Bruder von Rhythm Fischer. Mit dem Ziel, eines Tages den Titel eines Lorbeerkranz-Charons zu erlangen, trat er der 6. Legion bei, bestand das Auswahlverfahren und wurde anschließend in ein dreijähriges, abgeschottetes Ausbildungsprogramm aufgenommen.",
          TextMapId = "WikiText_20102401"
        },
        WikiText_20102402 = {
          ContentDE = "Nach seinem Eintritt in die 6. Legion wurde Blues von der Spathatoi zwangsweise alchemistischen Modifikationen unterzogen, wodurch er seinen menschlichen Körper verlor und zu einem Wesen von außergewöhnlicher Kampfkraft wurde. Nach seiner Flucht aus der Einrichtung führte die Wirkung eines experimentellen Suppressors zu einer fortschreitenden Verschlechterung seines Zustands. Mit dem allmählichen Verlust der Kontrolle begann er, nächtliche Angriffe auf Zivilisten zu verüben – Ereignisse, die später als der wahre Ursprung der Jagd auf Charon in Icelake erkannt wurden. In einer Konfrontation mit Rhythm erlitt er tödliche Verletzungen. Um seiner Schwester die Last der Wahrheit zu ersparen, bat er einen Freund, die tatsächliche Ursache seines Todes zu verschweigen.",
          TextMapId = "WikiText_20102402"
        },
        WikiText_20102501 = {
          ContentDE = "Lynn, Major der 13. Legion des Hyperboreischen Imperiums, ist eine sachliche und kompromisslose Offizierin. Sie wurde nach Icelake entsandt, um die Ermittlungen im Fall der Jagd auf Charon zu leiten.",
          TextMapId = "WikiText_20102501"
        },
        WikiText_20102601 = {
          ContentDE = "Ein weiteres Versuchsobjekt aus dem Augmentationsprogramm der 6. Legion. Phantasio begegnete Blues während ihrer Gefangenschaft in der Einrichtung. Die beiden freundeten sich an und flohen später gemeinsam. Später wurde er als die treibende Kraft hinter den späteren Phasen der Jagd auf Charon identifiziert. Um Blues’ letzten Wunsch zu erfüllen, beschädigte Phantasio seine eigenen Stimmbänder, um ihn zu imitieren, und offenbarte Rhythm schließlich die Wahrheit.",
          TextMapId = "WikiText_20102601"
        },
        WikiText_20102602 = {
          ContentDE = "Wahrer Name: Parsifal Snowfield. Er verkörperte einst die Frostfee in der letzten Aufführung von Kinder aus dem Schneefeld.\n Nach Abschluss der Ermittlungen zur Jagd auf Charon schlug er Rhythm bewusstlos und vertraute sie {nickname} an. Um {nickname}s Beteiligung an dem Gefecht mit der 13. Legion zu verschleiern, blieb Phantasio zurück, deckte ihren Rückzug und beseitigte alle Spuren. Im anschließenden Zusammenstoß mit Lynns Einheit wurde er schwer verwundet und von der 13. Legion in Gewahrsam genommen. Sein derzeitiger Verbleib ist unbekannt.",
          TextMapId = "WikiText_20102602"
        },
        WikiText_20102701 = {
          ContentDE = "Eine Adelige aus der Innenstadt Icelakes, die sich stolz gibt, jedoch von Natur aus gütig ist.\n Sie kam in die umliegenden Bezirke, um ihrem Freund Savio zu helfen, und traf dort auf Fina und {nickname}. Nach einem Entführungsfall überwand sie ihre Vorurteile gegenüber den Charon und schloss eine feste Freundschaft mit Fina.",
          TextMapId = "WikiText_20102701"
        },
        WikiText_20102801 = {
          ContentDE = "Ein junger Mann aus der Innenstadt, Fina’s Halbbruder.\n Nachdem er beide Eltern verloren hatte, litt er unter Mobbing in der Schule. Er glaubte, seine einzige Freundin Cassandra hätte ihn verlassen, und floh allein aus Icelake, nur um von Banditen entführt zu werden. Er wurde sicher von Fina und {nickname} gerettet, was zu seiner Wiedervereinigung mit Fina führte. Ermutigt von {nickname}, fand er den Mut, das Leben neu zu begegnen.",
          TextMapId = "WikiText_20102801"
        },
        WikiText_20300101 = {
          ContentDE = "Eine mysteriöse Händlerin aus Huaxu, die trotz ihrer Herkunft als Charon eine hohe Stellung innehat. Sie begegnete {nickname} erstmals, als sie am Galea-Theater eingriff und Hilfe leistete.",
          TextMapId = "WikiText_20300101"
        },
        WikiText_20300102 = {
          ContentDE = "Während einer Legion-Operation, die darauf abzielte, {nickname} anzulocken, griff Zhiliu erneut ein, rettete {nickname} und eskortierte {nickname} nach Huaxu.",
          TextMapId = "WikiText_20300102"
        },
        WikiText_20300103 = {
          ContentDE = "Als Hohe Kanzlerin von Loongyuan steht Zhiliu dem Ministerium des Wohlstands vor und führt zugleich den Kaufmannsgildeverband EverSpring. Obwohl sie dieses hohe Amt bekleidet, bevorzugt sie die schlichte Anrede als Händlerin. Mit ihrem zugänglichen Auftreten und ihrem scharfen Geschäftssinn genießt sie großes Ansehen unter den Sternenwebern.",
          TextMapId = "WikiText_20300103"
        },
        WikiText_20300104 = {
          ContentDE = "Zhiliu strebt danach, die Plage von Zhuyin zu beenden.\n Zu diesem Zweck hat sie {nickname} damit beauftragt, Zhuyin-Schuppen zu beschaffen. Eine hochkonzentrierte reaktive Substanz, die mit diesen Schuppen in Resonanz tritt, war der ursprüngliche Grund für ihre Reise nach Icelake. Zwar scheiterte ihr anfängliches Ziel dort, doch führte es zu ihrer unerwarteten Begegnung mit {nickname}.",
          TextMapId = "WikiText_20300104"
        },
        WikiText_20300105 = {
          ContentDE = "Zhilius wahres Ziel ist nicht die Versiegelung Zhuyins, sondern die Aneignung seiner Macht. Um unvorhersehbare Faktoren auszuschalten, ließ sie {nickname} am Zhuyin-Altar gefangen setzen und wandte sich gegen {性别:ihn|sie}.",
          TextMapId = "WikiText_20300105"
        },
        WikiText_20300201 = {
          ContentDE = "Eine Luno aus Huaxu, die davon träumt, die größte Sternenweberin des Landes zu werden. Sie bewundert Snow zutiefst – die einzige gehörnte Luno – und hat sich ihr aus eigenem Willen als treue Gefolgsfrau angeschlossen.",
          TextMapId = "WikiText_20300201"
        },
        WikiText_20300301 = {
          ContentDE = "Eine der Gründungsfiguren Huaxus, Architektin der Neun Kapitel und Begründerin der Xuanheng-Sekte.\n Vor rund einem Jahrtausend war sie in ganz Atlasia aktiv und eine Zeitgenossin Galeas, des Gründungskai­sers von Hyperborea. Yang schrieb einst folgende Worte in die Annalen der Geschichte Huaxus: „Himmel und Mensch in vollkommener Übereinstimmung; Yin und Yang in nahtloser Harmonie.“",
          TextMapId = "WikiText_20300301"
        },
        WikiText_20300401 = {
          ContentDE = "Ein Magistrat von Yingtian in Huaxu, der eine Aura kühler Distanziertheit ausstrahlt. Er trägt die Bürde, alles Leben zu schützen, als heilige Pflicht – selbst um den Preis der eigenen Sicherheit.",
          TextMapId = "WikiText_20300401"
        },
        WikiText_20300402 = {
          ContentDE = "Ein ehemaliger Wanderer und Mitschüler Kezhous, der ihm inzwischen aus dem Weg geht.\n Kezhou zufolge wurde Yuming durch einen Unfall – nicht aus eigenem Willen – zum Magistrat von Yingtian.",
          TextMapId = "WikiText_20300402"
        },
        WikiText_20300501 = {
          ContentDE = "Der Anführer des Dunstmarkts, der Untergrundorganisation Huaxus, der unter Schwarzmarkthändlern hohes Ansehen genießt.\n Sein Büro befindet sich in einem gewaltigen, gestrandeten Handelswrack an der Westküste – der beschädigte Rumpf verbirgt ein überraschend geräumiges Inneres.",
          TextMapId = "WikiText_20300501"
        },
        WikiText_20300502 = {
          ContentDE = "Ein unauffälliger Förderer und Sponsor der Archäologischen Gesellschaft Greenwich.",
          TextMapId = "WikiText_20300502"
        },
        WikiText_20300601 = {
          ContentDE = "Die derzeitige Erbin der Fu-Blutlinie, von zurückhaltendem und distanziertem Wesen. Sie begegnete {nickname} erstmals, als sie Verwundete im Dunstmarkt behandelte.",
          TextMapId = "WikiText_20300601"
        },
        WikiText_20300602 = {
          ContentDE = "Fushu, die vor einem Jahrhundert wirkte,\n zog sich während der Großen Seuche bei der Behandlung von Kranken eine tödliche Krankheit zu. Ihre Schwester Fufeng versetzte sie in einen Zustand der Stasis, um das Fortschreiten der Krankheit aufzuhalten. Ein Jahrhundert später entwickelte Fufengs Nachfolger ein Heilmittel, das Fushu wiedererweckte und ihr erlaubte, die Welt erneut zu spüren.",
          TextMapId = "WikiText_20300602"
        },
        WikiText_20300701 = {
          ContentDE = "Ein Schwertkämpfer, der sich selbst als Wanderer bezeichnet, mit ungezwungener Art und ritterlichem Geist. Auf der Suche nach seinem Bruder geriet Kezhou in die Vielfach-Fangjagd-Formation, wo er auf den ebenfalls gestrandeten {nickname} traf.",
          TextMapId = "WikiText_20300701"
        },
        WikiText_20400101 = {
          ContentDE = "{性别2:Ein geheimnisvoller Junge, der|Ein geheimnisvolles Mädchen, das} in {nickname}s wiederkehrendem Traum vom Sandreich erscheint. {性别2:Er|Sie} scheint Wahrheiten zu kennen, die selbst {nickname} noch nicht erkannt hat.",
          TextMapId = "WikiText_20400101"
        },
        WikiText_20400102 = {
          ContentDE = "Unter {性别2:seiner|ihre} Führung erwachte in {nickname} die Kraft, die als „Resonanz“ bekannt ist.",
          TextMapId = "WikiText_20400102"
        },
        WikiText_20400103 = {
          ContentDE = "Der wahre Name des mysteriösen {性别2:Jungen|Mädchens} ist {nickname2}.\n {性别2:Er|Sie} trägt ein Geheimnis in sich, das niemand sonst kennt – eine Stimme, die ausschließlich in {性别2:seinem|ihrem} Geist existiert. Sie flüstert von einem starken Verlangen nach Schmerz, Blut und Tod und lockt {性别2:ihn|sie} unablässig in die Dunkelheit.",
          TextMapId = "WikiText_20400103"
        },
        WikiText_20400104 = {
          ContentDE = "Ein junger Soldat des Hyperboreischen Imperiums, bekannt für {性别2:seine|ihre} außergewöhnliche Kampfkraft während {性别2:seiner|ihrer} Zeit als Kadett an der Kaiserlichen Militärakademie von Hyperborea. Als Jahrgangsbester des 133. Abschlussjahrgangs erhielt {性别2:er|sie} den Beinamen „Der bleiche Schnitter“.\n Derzeit dient {性别2:er|sie} als Hauptmann der Einheit Greif der 13. Legion und wurde der Operation „Lonza-Festung“ zugeteilt.",
          TextMapId = "WikiText_20400104"
        },
        WikiText_20400105 = {
          ContentDE = "Sie verfügt nur über Erinnerungen aus wenigen Jahren und besitzt keinerlei Wissen über {性别2:seine|ihre} Herkunft oder {性别2:sein|ihr} frühes Leben.",
          TextMapId = "WikiText_20400105"
        },
        WikiText_20400201 = {
          ContentDE = "Eine geheimnisvolle Gestalt, die eines Nachts in der Asphodel erschien. Sie zahlte Camilla eine hohe Summe, um {nickname} von außerhalb Icelake zu retten.",
          TextMapId = "WikiText_20400201"
        },
        WikiText_20400301 = {
          ContentDE = "Ein Lunarian mit außergewöhnlichen Fähigkeiten in der Schmiedekunst. Von {nickname}s Waffe Nachhall der Erinnerung fasziniert, entschied sie sich, für eine Zeit in Icelake zu bleiben, um {nickname} bei der Schmiedung und Verfeinerung von Waffen zu unterstützen.",
          TextMapId = "WikiText_20400301"
        },
        WikiText_20400401 = {
          ContentDE = "Eine geheimnisvolle Frau, die in der Tauenden Höhle erschienen ist. Sie gibt an, eine Fährfrau des Nebelmeeres zu sein – eine, die die Gedanken der Verstorbenen erblicken und ihre verlorenen Seelen zurück in das Nebelmeer führen kann, aus dem sie einst hervorgingen.\n Ihr zufolge trägt {nickname} ein außergewöhnliches Schicksal in sich und könnte eines Tages den Fluss des Lebens überschreiten, um im Herzen des Nebelmeeres erneut den Seelen der Vergangenheit zu begegnen.",
          TextMapId = "WikiText_20400401"
        },
        WikiText_30100101 = {
          ContentDE = "Der Name des riesigen Kontinents, auf dem sich unsere Geschichte entfaltet.",
          TextMapId = "WikiText_30100101"
        },
        WikiText_30100201 = {
          ContentDE = "Entlang der nördlichen Ausläufer des hyperboreischen Imperiums erstrecken sich das Vidofnir-Gebirge und ziehen eine zerklüftete Linie durch den Kontinent Atlasia. Jenseits ihrer eisverhangenen Gipfel liegt der wahre Hohe Norden – die Heimat der uralten Fjorde von Askard, in denen noch immer die ältesten Charon-Stämme leben.",
          TextMapId = "WikiText_30100201"
        },
        WikiText_30100301 = {
          ContentDE = "Über den Kontinent Atlasia verstreut finden sich die sogenannten Himmelsbäume – kristalline Wucherungen, benannt nach ihrer baumartigen Gestalt. Ihre Größe reicht von winzigen Setzlingen bis hin zu gewaltigen Riesen. In ihren durchscheinenden Strukturen schimmern Adern aus blauem Licht, und aus ihren glitzernden Zweigen lässt sich der seltene Kristall Phoxenen gewinnen.\n Man nimmt an, dass die Himmelsbäume älter sind als die Menschheitsgeschichte selbst; ihr wahrer Ursprung ist bis heute unbekannt. Alte elysische Gelehrte betrachteten sie als Geschenke des Himmels – ein Glaube, der sich in ihrem Namen widerspiegelt. Allerdings führten verschiedene Kulturen unterschiedliche Bezeichnungen für sie, und in manchen bildeten sich frühe religiöse Systeme, die auf ihrer Verehrung beruhten.\n Doch ihr Reichtum ist nicht unerschöpflich. Nach längerer Ausbeutung beginnen die Äste allmählich zu verdorren und liefern schließlich keine Phoxenen mehr.",
          TextMapId = "WikiText_30100301"
        },
        WikiText_30100401 = {
          ContentDE = "Ein seltenes Mineral, bestehend aus ineinandergreifenden, pyramidenförmigen Prismen. Seine Farbpalette reicht von tiefem Violett bis zu nachtblauem Schwarz, und in seinem kristallinen Kern schimmern Lichter, die sich wie wanderndes Sternenlicht bewegen, als hätte der Nachthimmel selbst feste Gestalt angenommen. Verehrt für seine betörende Schönheit, löste der Kristallo von Stella einst einen wahren Rausch unter Aristokraten und Sammlern aus, wobei die Nachfrage die Preise in irrationale Höhen trieb.",
          TextMapId = "WikiText_30100401"
        },
        WikiText_30100402 = {
          ContentDE = "In einigen Regionen der Welt wurde Kristallo von Stella als Bestandteil medizinischer Heilmittel verwendet.\n Innerhalb des hyperboreischen Imperiums führte jedoch ein katastrophaler Vorfall in Flagson, einer südlichen Provinz, im Zusammenhang mit der medizinischen Nutzung dieses Kristallos zu weitreichenden Unruhen. Seitdem ist der zivile Handel mit dem Kristallo im gesamten Imperium strengstens verboten.",
          TextMapId = "WikiText_30100402"
        },
        WikiText_30100403 = {
          ContentDE = "Wird Kristallo von Stella präzise zu pharmazeutischen Verbindungen verarbeitet, kann es bei Charon-Individuen mit frühen Anzeichen der Verderbnis unterschiedliche Wirkungen entfalten. Je nach Zusammensetzung kann es den Verlauf der Krankheit entweder beschleunigen oder unterdrücken.",
          TextMapId = "WikiText_30100403"
        },
        WikiText_30100501 = {
          ContentDE = "Ein weitläufiger natürlicher See unmittelbar außerhalb von Icelake. Aufgrund des rauen Klimas der Region ist der See die meiste Zeit des Jahres zugefroren – eine Eigenschaft, die der Stadt ihren Namen gab.",
          TextMapId = "WikiText_30100501"
        },
        WikiText_30100601 = {
          ContentDE = "Ein durchscheinender Kristall, der gewöhnlich aus den „Zweigen“ der Himmelbäume gewonnen wird. Er weist häufig einen blassblauen Schimmer auf.\n Hochwertige Phoxene ist reich an brennbarer Energie, aus der durch Veredelung Phoxichor gewonnen wird – eine unverzichtbare Energiequelle moderner Maschinen. Die Entwicklung phoxenebasierter Technologien hat den Fortschritt der menschlichen Zivilisation erheblich beschleunigt. Im Verlauf der Geschichte Atlasias waren Aufstieg und Fall von Nationen ebenso wie der Ausbruch großer Kriege eng mit der Kontrolle und Ausbeutung von Phoxeneressourcen verknüpft.",
          TextMapId = "WikiText_30100601"
        },
        WikiText_30100701 = {
          ContentDE = "Ein Hochland nordwestlich von Nebelkai, nahe dem Zhuyin-Altar.\n Durch das ausströmende Verderben Zhuyins ist das Gebiet heute weitgehend von einer öden Gritblight-Landschaft überzogen. Der Boden ist von kristallinen Pflanzen und scharfkantigen Felsformationen übersät, die der Region ihren Namen gaben. Geistlose Filthoiden und Zobel-Bi'an streifen umher, wodurch die Gritblight-Ebene zu einer Katastrophenzone geworden ist, die für gewöhnliche Menschen unpassierbar ist.",
          TextMapId = "WikiText_30100701"
        },
        WikiText_30100801 = {
          ContentDE = "Eine geologische Gefahr, die mit der Plage von Zhuyin entstand und sich nun in Nebelkai ausbreitet. Sie erscheint als violetter, kristalliner Staub, der Oberflächen überzieht und Flora wie Fauna ihrer Lebenskraft beraubt, was zu schweren ökologischen Schäden führt.\n Der von Meister Gongshang entwickelte Mechanische Nexus ist in der Lage, Gritblight zu adsorbieren und zu entfernen.",
          TextMapId = "WikiText_30100801"
        },
        WikiText_30100901 = {
          ContentDE = "Ein Kraut, das nur in bestimmten Regionen wächst und dafür bekannt ist, Verletzungen zu neutralisieren, die von Bi'an verursacht wurden.",
          TextMapId = "WikiText_30100901"
        },
        WikiText_30300101 = {
          ContentDE = "Filthoiden sind brutale Kreaturen, die auf dem Kontinent Atlasia überall vorkommen. Sie streifen in zahllosen Gestalten über den Kontinent Atlasia, von denen die meisten äußerst aggressiv sind. Obwohl sie dank des Aufstiegs der Nationalstaaten\n und des langen Marsches des Krieges keine Gefahr mehr für die Zivilisation als Ganzes darstellen, bilden sie bis heute eine ernste Bedrohung für Einzelpersonen und kleine Siedlungen.",
          TextMapId = "WikiText_30300101"
        },
        WikiText_30300201 = {
          ContentDE = "Eine hochintelligente, nichtmenschliche Spezies, deren Erscheinung der von Menschenkindern stark ähnelt. Sie werden auch Lunos genannt und sind vor allem an ihrer blassen Haut und ihrem weißen Haar zu erkennen. Obwohl sie ein langes Leben führen, zeigen Lunarian keinerlei sichtbare Zeichen des Alterns. Tief mit der Menschheit verbunden, leben sie auf dem gesamten Kontinent Atlasia häufig friedlich Seite an Seite mit Menschen.",
          TextMapId = "WikiText_30300201"
        },
        WikiText_30300202 = {
          ContentDE = "Trotz ihres weitgehend einheitlichen Erscheinungsbildes zeigen die meisten Lunarin eine natürliche Begabung in einem bestimmten Bereich – etwa Schmiedekunst, Handel, Investitionen und Ähnliches. Snow jedoch – jene, die stets in der Asphodel umherflattert – scheint eine Ausnahme zu sein ... es sei denn, sich selbst in den höchsten Tönen anzupreisen gilt als eine ernstzunehmende Fähigkeit.",
          TextMapId = "WikiText_30300202"
        },
        WikiText_30300301 = {
          ContentDE = "Die Charon – eine Rasse, gekennzeichnet durch ihre Hörner und markanten Rückendornen – verfügen über eine höhere körperliche Widerstandskraft als gewöhnliche Menschen, die zusammenfassend als Solarian bezeichnet werden. Zudem zeigen sie eine bemerkenswerte Anpassungsfähigkeit sowohl gegenüber Hitze als auch gegenüber Kälte.\n Der Name „Charon“ geht auf einen alten Schöpfungsmythos zurück, der unter ihresgleichen überliefert wird: die Legende von einem göttlichen Gefährt, das neugeborene Seelen in die Welt der Lebenden überführt.",
          TextMapId = "WikiText_30300301"
        },
        WikiText_30300302 = {
          ContentDE = "Innerhalb des Hyperboreischen Imperiums machen die Charon etwa 20 % der Bevölkerung aus. Man glaubt, dass sie eine verfluchte Blutlinie tragen, und sie werden häufig als „Kinder des Dämons“ gebrandmarkt. Infolgedessen werden ihnen grundlegende Rechte verwehrt, die den Solarian zustehen, und sie sind im gesamten Imperium systematischer Diskriminierung ausgesetzt.",
          TextMapId = "WikiText_30300302"
        },
        WikiText_30300303 = {
          ContentDE = "Beim Übergang ins Erwachsenenalter durchlaufen die Charon eine einmalige Veränderung, die als Erwachen bekannt ist.\n Bei den meisten verläuft dieser Wandel kaum merklich – sofern er sich überhaupt zeigt. Bei wenigen Begabten jedoch bringt das Erwachen arkane Fähigkeiten hervor, die im gesamten Imperium als „Magie“ bezeichnet werden. Diese Kräfte unterscheiden sich von Individuum zu Individuum stark in Form und Stärke. Jene, bei denen solche Fähigkeiten manifest werden, nennt man Daimonen.\n In seltenen Fällen schlägt das Erwachen fehl und mündet in einen Zustand, der als Verderbnis bekannt ist.",
          TextMapId = "WikiText_30300303"
        },
        WikiText_30300304 = {
          ContentDE = "Die Betroffenen verlieren nach und nach ihre Menschlichkeit – Erinnerungen, Verstand, selbst ihre Identität – und verwandeln sich schließlich in eine besonders zerstörerische Variante der Filthoiden, weit gefährlicher als jene, die man üblicherweise in der Wildnis antrifft. Eine bekannte Heilung existiert nicht.\n Gerade diese Furcht vor der Verderbnis treibt die Solarian dazu, die Charon als existenzielle Bedrohung zu betrachten.",
          TextMapId = "WikiText_30300304"
        },
        WikiText_30300305 = {
          ContentDE = "Nach hyperboreischen Geschichtsaufzeichnungen führten die Charon während der Ära des Heiligen Turms vor über zweitausend Jahren einen kontinentweiten Krieg, in dem sie Solarian unterschiedslos massakrierten und diese an den Rand der Auslöschung trieben. Dieses Narrativ wird bis heute häufig als zentrales Argument angeführt, um zu rechtfertigen, warum Charon-Bürger im Imperium weiterhin tief verwurzelter Stigmatisierung ausgesetzt sind und ihnen die volle Gleichstellung der Bürgerrechte verwehrt bleibt.",
          TextMapId = "WikiText_30300305"
        },
        WikiText_30300401 = {
          ContentDE = "Ein gewaltiges Wesen, das in den Ruinen der Glevum-Grube haust und seinen Namen seiner krankhaften Sammelwut nach kristallinen Fragmenten verdankt. Trotz seiner bestienhaften Erscheinung weisen Teile seines Körpers menschliche Anatomie auf – ein Hinweis darauf, dass es nicht immer ein Monster gewesen sein könnte.",
          TextMapId = "WikiText_30300401"
        },
        WikiText_30300402 = {
          ContentDE = "Die als Kristallophage bekannte Kreatur war einst ein junger Bergmann namens Hamel Dickinson, der vor vierzig Jahren als vermisst galt.\n Als junger Mann wagte sich Dickinson allein in die Minen, auf der Suche nach einem legendären Edelstein, mit dem er mit der Frau, die er liebte – Hilin – durchbrennen wollte. Tief in den Stollen jedoch verlor er den Verstand und verwandelte sich schließlich in ein Monster.\n Getrieben, vielleicht, von der nachwirkenden Kraft seiner Besessenheit, häufte die Kreatur auch lange nach ihrer Verwandlung weiterhin funkelnde Steine an, als sehne sie sich noch immer danach, sie seiner Geliebten darzubringen.",
          TextMapId = "WikiText_30300402"
        },
        WikiText_30300501 = {
          ContentDE = "Daimonen sind begabte Charon, bei denen einzigartige Kräfte erwachen. Diese Fähigkeiten – in Form und Stärke sehr unterschiedlich – stehen häufig in Verbindung mit der jeweiligen Blutlinie. Im hyperboreischen Imperium gelten solche Kräfte als bösartig und werden gemeinhin als „Magie“ gebrandmarkt.",
          TextMapId = "WikiText_30300501"
        },
        WikiText_30300601 = {
          ContentDE = "Eine seltene, ausschließlich bei den Charon auftretende Erkrankung, für die es im hyperboreischen Imperium kein Heilmittel gibt.\n Frühe Anzeichen der Verderbnis zeigen sich meist vor dem Erreichen des Erwachsenenalters. Betroffene entwickeln Male, die schweren Brandnarben ähneln, häufig begleitet von Sinnesverlust, aggressiven Ausbrüchen und geistiger Instabilität. Beim Erreichen des sogenannten „Erwachens“ verlieren die Erkrankten vollständig ihr Gedächtnis und ihre Emotionen und verwandeln sich schließlich in eine außergewöhnlich mächtige Variante der Filthoiden – Wesen von enormer Stärke und wahlloser Gewalt.\n Um die Ausbreitung solcher Bedrohungen zu verhindern, unterliegt jeder Charon-Bürger, der Anzeichen der Verderbnis zeigt, der sofortigen Exekution durch die Eskorte. Personen, die einen Verdorbenen verbergen oder unterstützen, gelten als mitschuldig an der Gefahr und werden mit derselben Strafe belegt.",
          TextMapId = "WikiText_30300601"
        },
        WikiText_30300701 = {
          ContentDE = "Die zahlenmäßig größte Gruppe gewöhnlicher Menschen auf dem gesamten Kontinent Atlasia.\n Der Begriff Solarian wurde ursprünglich geprägt, um gewöhnliche Menschen im gesellschaftlichen Diskurs von den Charon zu unterscheiden. Mit der Zeit setzte er sich als allgemein akzeptierte Bezeichnung für diese Bevölkerungsgruppe durch. Das Wort Sola stammt aus einer alten atlasischen Sprache und bedeutet „Sonne“.\n Bis heute lehnen einige radikale solarianische Suprematisten den Begriff vollständig ab und argumentieren, dass „wahre Menschen“ keiner Bezeichnung bedürften, die sie auf eine Stufe mit anderen Rassen stelle.",
          TextMapId = "WikiText_30300701"
        },
        WikiText_30300801 = {
          ContentDE = "Unter dem Volk als „Lord Argent“ bekannt, ist Taihao die verehrte Gottheit Huaxus – die lebendige Verkörperung des Gesetzes des Himmels und des Willens der Neun Kapitel.",
          TextMapId = "WikiText_30300801"
        },
        WikiText_30300901 = {
          ContentDE = "Wächter und Vollstrecker Huaxus, handelnd nach dem Willen der Neun Kapitel. Ein göttliches Wesen mit dem Kopf eines Wolfes, einem bestialischen Leib, weißem Fell und goldenen Hörnern.\n Werden die Neun Kapitel gebrochen, erscheint Bi’an, um Gericht zu halten und den dauerhaften Frieden des Reiches zu sichern.",
          TextMapId = "WikiText_30300901"
        },
        WikiText_30300902 = {
          ContentDE = "Bi’an entstehen durch die Transformation beinahe erwachsener Loongscions.\n Einige Gelehrte vermuten, dass Bi’an dieselbe Wesensnatur wie Filthoiden besitzen. Ihre Entstehung gilt als Ergebnis eines Verderbnisprozesses, der durch die Neun Kapitel beeinflusst wird. Der genaue Mechanismus ist jedoch unklar.",
          TextMapId = "WikiText_30300902"
        },
        WikiText_30301001 = {
          ContentDE = "In der Gestalt den Bi’an ähnlich, jedoch tiefschwarz gefärbt. Diese Wesen sind jüngst nahe Nebelkai aufgetaucht und stellen chaotische Abirrungen dar, hervorgebracht von der Plage von Zhuyin und außerhalb der Kontrolle der Neun Kapitel.\n Sie greifen Reisende in der Wildnis unterschiedslos an und gefährden die öffentliche Sicherheit erheblich. Bemerkenswert ist, dass der Angriff auf ein Zobel-Bi'an keine Bestrafung durch die Neun Kapitel nach sich zieht.",
          TextMapId = "WikiText_30301001"
        },
        WikiText_30301101 = {
          ContentDE = "Eine bösartige Gottheit aus Huaxus uralten Legenden, Rivale Taihaos, nun jenseits von Nebelkai versiegelt. Ihre wahnsinnige Macht ist jedoch nach außen gedrungen und hat die Plage von Zhuyin hervorgebracht.\n Vor einem Jahrhundert erwachte Zhuyin erstmals und konnte nur durch eine gewaltige gemeinsame Anstrengung niedergerungen werden. Nun ist es ein zweites Mal erwacht.",
          TextMapId = "WikiText_30301101"
        },
        WikiText_30301102 = {
          ContentDE = "Eine der zwei verehrten Gottheiten, die gemeinsam mit Taihao bei der Gründung der Neun Kapitel von Dafeng Huaxu beschützten. Taihao herrschte über das Gesetz, während Zhuyin über den Geist wachte.",
          TextMapId = "WikiText_30301102"
        },
        WikiText_30301103 = {
          ContentDE = "Nach der Schlacht von Shuli vor Jahrhunderten wurde Zhuyin aus den Neun Kapiteln verstoßen, und sein Vermächtnis als verehrte Gottheit geriet allmählich in Vergessenheit.",
          TextMapId = "WikiText_30301103"
        },
        WikiText_30301201 = {
          ContentDE = "Wishen sind besondere Wesen, die aus den sterbenden Reuegefühlen von Individuen in Huaxu entstanden sind, beeinflusst vom allgegenwärtigen Weihrauch in der Luft.\n Sie verlieren in der Regel den Großteil ihrer Erinnerungen und zeigen eingeschränkte Sprach- sowie kognitive Fähigkeiten.\n Für gewöhnliche Menschen sind sie unsichtbar und können nur von Kindern oder Personen mit besonderer Energie wahrgenommen werden. Obwohl sie nicht direkt mit der physischen Welt interagieren können, vermögen sie es, kleine Objekte subtil zu beeinflussen. In ganz Huaxu existieren in vielfältiger Form volkstümliche Überlieferungen über Wishen.",
          TextMapId = "WikiText_30301201"
        },
        WikiText_30301202 = {
          ContentDE = "Wishen werden von ihren verbleibenden Reuegefühlen getragen und lösen sich auf, sobald diese überwunden sind.",
          TextMapId = "WikiText_30301202"
        },
        WikiText_30400101 = {
          ContentDE = "Ein wiederkehrender Traum, den {nickname} seit seiner Kindheit hat. Darin fällt endlos weißer Sand vom Himmel und legt sich wie ein fahler Schleier über den Himmel. Dort, wo Sand und Firmament aufeinandertreffen, erscheint eine einsame Gestalt, deren Umrisse jedoch verborgen bleiben.",
          TextMapId = "WikiText_30400101"
        },
        WikiText_30400201 = {
          ContentDE = "Eine verborgene Macht, die in {nickname} während {性别:seines|ihres} Kampfes gegen Sibylle Mason erwachte, gelenkt von der Stimme der Gestalt aus {性别:seinem|ihrem} Traum.\n Im Augenblick ihres ersten Erwachens wurden {nickname} und Berenica eins – ihre Stärke wurde durch die Kraft von {nickname}s Willen erheblich gesteigert.",
          TextMapId = "WikiText_30400201"
        },
        WikiText_30400202 = {
          ContentDE = "Im Kern ist Resonanz eine Kraft der Einstimmung. Wer sie meistert, kann durch bloße Willenskraft die eigene Energie kanalisieren, um die Magie naher Daimonen oder Filthoiden zu verstärken. In seltenen und außergewöhnlichen Fällen ist der Träger dieser Macht sogar in der Lage, sich vorübergehend mit einer anderen Person zu vereinen und vollständige Kontrolle über deren Bewegungen und Fähigkeiten zu erlangen.",
          TextMapId = "WikiText_30400202"
        },
        WikiText_30400203 = {
          ContentDE = "Vor Jahrzehnten löste eine Person, die fähig war, Resonanz zu führen, im gesamten Imperium weitreichende Unruhen aus. Schließlich wurde sie durch arboreale Kreuzigung hingerichtet – die höchste Form der Todesstrafe in Hyperborea.",
          TextMapId = "WikiText_30400203"
        },
        WikiText_30400301 = {
          ContentDE = "Das höchste Gesetz, das ganz Huaxu regiert.\n Alle innerhalb seiner Grenzen müssen seinen Geboten folgen, andernfalls droht Strafe – vollstreckt durch Bi’an oder die Magistrate von Yingtian. Über das Verbot von Taten wie Mord und Raub hinaus vermag dieses Gesetz auch Filthoiden innerhalb seines Herrschaftsbereichs zu unterdrücken und ihnen ihre Raserei zu nehmen.\n Die vom Volk verehrte Gottheit Taihao ist die lebendige Verkörperung seines Willens.",
          TextMapId = "WikiText_30400301"
        },
        WikiText_30400302 = {
          ContentDE = "Die Regeln der Neun Kapitel sind auch als die Neun Ermahnungen bekannt. Ihr Inhalt lautet:\n \n Die große Tugend des Himmels trägt den Namen Leben; zu verletzen oder zu töten – das darf nicht geschehen.\n Ein Mensch wird an der Stärke seines Wortes gemessen; Treue zu brechen oder ein Gelübde zu verraten – dies darf nicht geschehen.\n Lasst Wahrheit offenbar werden und Falschheit vergehen; die Vielen zu täuschen und irrezuführen – dies darf nicht geschehen.\n \n Beherrsche dich selbst in Demut, binde dein Handeln an Bescheidenheit; dich in Hochmut und Tyrannei zu ergehen – dies darf nicht geschehen.\n Ehre die Würdigen, erweise Höflichkeit, und lass Ordnung das Maß der Sitte sein; zügellose Maßlosigkeit und hemmungslosen Exzess zu zeigen – dies darf nicht geschehen.\n Lass Mitgefühl und Gerechtigkeit deinen Geist und jede Tat leiten; die Schwachen mit Gewalt zu unterdrücken – dies darf nicht geschehen.\n \n Halte dein Herz rein, dein Verhalten gezügelt, und Rechtschaffenheit sei das Zeichen deiner Integrität; das Gesetz aus Gier oder Grausamkeit zu beugen – dies darf nicht geschehen.\n Lass Klarheit dein unverrückbarer Maßstab sein bei der Unterscheidung von Recht und Unrecht; Wahrheit und Lüge zu vermengen – dies darf nicht geschehen.\n Begegne dem Gebot des Himmels mit ehrfürchtigem Sinn und feierlichem Herzen; gegen die heilige Ordnung aufzubegehren – dies darf nicht geschehen.",
          TextMapId = "WikiText_30400302"
        },
        WikiText_30400303 = {
          ContentDE = "Obwohl die Neun Kapitel zur Verbrechensbekämpfung geschaffen wurden, eröffnen ihre starren Durchsetzungskriterien Schlupflöcher, die manche auszunutzen wissen.\n So betrog etwa ein Schwarzmarkthändler den Vater eines jungen Mädchens, indem er einen Vertrag manipulierte – ein Vergehen, das von den Neun Kapiteln aufgrund ihrer unflexiblen Urteilslogik nicht verhindert wurde.",
          TextMapId = "WikiText_30400303"
        },
        WikiText_30400401 = {
          ContentDE = "Eine Katastrophe, die Huaxu heimsuchte, ausgehend von der Gritblight-Ebene und vor allem Nebelkai traf. Ihre Ausbreitung kappte Handelsrouten und verursachte schwere Störungen des täglichen Lebens.\n Die Geißel manifestiert sich hauptsächlich in zwei Formen: dem Zobel-Bi'an und der Gritblight.",
          TextMapId = "WikiText_30400401"
        },
        WikiText_30400501 = {
          ContentDE = "Ihre Kraft entspringt unmittelbar den Neun Kapiteln von Dafeng.",
          TextMapId = "WikiText_30400501"
        },
        WikiText_30400502 = {
          ContentDE = "Die Kunst der Vergänglichkeit wirkt, indem sie die eigene Lebenskraft des Zhuyou als Medium nutzt, um Unreinheiten aus dem Körper des Patienten zu vertreiben. Häufige Anwendung stellt eine erhebliche körperliche Belastung für die Anwenderin dar.",
          TextMapId = "WikiText_30400502"
        },
        WikiText_30400601 = {
          ContentDE = "Eine hypothetische Entität der Naturphilosophie. Huaxu-Gelehrte glauben, dass die Luft von einer farb- und geruchlosen Substanz durchdrungen ist, die allen Dingen Energie verleiht. Wird sie durch Weihrauch aktiviert, dient diese Substanz als Medium, durch das die Neun Kapitel wirken. Gritblight gilt als die greifbare Form des verdichteten Taixu – eine physische Manifestation seiner Existenz.",
          TextMapId = "WikiText_30400601"
        },
        WikiText_30400701 = {
          ContentDE = "Geheimnisvolle Runen, die überall in Huaxu treiben und aus der Kondensation überschüssigen Taixu in der Luft entstehen.",
          TextMapId = "WikiText_30400701"
        },
        WikiText_30400801 = {
          ContentDE = "Eine anomale Dimension, die entstand, als die Yu-Quelle durch die Plage von Zhuyin verunreinigt wurde. Innerhalb dieses Raumes vergessen Seelen nach und nach alle weltlichen Bindungen und gehen schließlich für alle Ewigkeit verloren.",
          TextMapId = "WikiText_30400801"
        },
        WikiText_40100101 = {
          ContentDE = "Die verfallenen Ruinen eines alten elysischen Tempels, errichtet auf den Hügeln der Purgatorio-Insel. Der Göttin des Vollmonds und des Schicksals geweiht, diente er einst als hochverehrte Pilgerstätte.\n Vor einem Jahrtausend, während der Großen Migration, wurde er von Wellen des Bildersturms verwüstet und ist seither nie wieder restauriert worden.",
          TextMapId = "WikiText_40100101"
        },
        WikiText_40100201 = {
          ContentDE = "Eines der folgenreichsten Ereignisse der frühen hyperboreischen Geschichte.\n Laut den offiziellen Aufzeichnungen des Imperiums drang gegen Ende der Großen Migration vor tausend Jahren eine Gruppe von Migranten unter der Führung von Dis Galea – dem späteren Kaiser Dis Ⅰ – nach Norden in die südlichen Tundren des Vidofnir-Gebirges vor, das heute zur Region Cocytus gehört. Dort kam es immer wieder zu Zusammenstößen mit den örtlichen Charon-Stämmen. In dem Bemühen um Frieden schloss der großmütige Dis Galea ein Abkommen mit den Charon: Am Klagenden Sees sollte ein Fest zur Feier des Friedensbeginns abgehalten werden. Doch das Treffen entpuppte sich als blutige Falle. Unter dem Deckmantel des Wohlwollens verübten die Charon noch in derselben Nacht ein Massaker. Nahezu alle Solarian kamen ums Leben. Nur Dis entkam – gerettet durch das letzte Opfer seines Bruders Soranus Galea.\n Nach der „Nacht des Klagenden Sees“ bestattete Dis Soranus schweren Herzens und zog sich in die südlichen Ebenen Hyperboreas zurück. In den folgenden zehn Jahren baute er seine Streitkräfte neu auf. Mit überwältigender zahlenmäßiger Überlegenheit und geschärfter Taktik schlug er die raubenden Charon zurück und errang zahllose Siege über die mächtigen Verdorbenen. Durch Feuer, Blut und Tränen einte er die Ebenen, und wandte sich dann erneut nach Norden. Dis marschierte ein zweites Mal zum Klagender See, zerschlug die Stämme, die ihn verraten hatten, und errichtete an dessen Ufern die Festung Icelake – den Vorläufer der späteren Stadt Icelake. Dort wurde er im Jahr 20 des Neuen Kalenders als Dis Ⅰ gekrönt, und das Hyperboreische Imperium war geboren.\n Doch angesichts seiner geschworenen Feinde entschied sich Dis Ⅰ weder für Rache noch für Vergeltung. Er wählte den Frieden und die Vergebung. Mit dem Edikt von Icelake erklärte er die Charon zu gleichwertigen Kindern Hyperboreas und band sie unter das Banner des Imperiums. Zum Gedenken an den Friedensstifter und Gründer ihrer Heimat versammeln sich die Bürger von Icelake jedes Jahr am Tag der Verkündung des Edikts, um den Silberkerzen-Karneval zu feiern – ein Fest des Friedens und der Einheit.",
          TextMapId = "WikiText_40100201"
        },
        WikiText_40100301 = {
          ContentDE = "Ein Bürgerkrieg, der vor Jahrhunderten zwischen der Xuanheng-Sekte und der Jishu-Sekte in Krähenlied-Hohl nahe Nebelkai ausgetragen wurde.\n Der Konflikt veränderte Huaxu nachhaltig. Nach Shuli wurde die Durchsetzung der Neun Kapitel von Dafeng deutlich verschärft, die Jishu-Sekte verfiel, und die Kunst des Maschinenwerks wurde stark eingeschränkt. Die Schlacht gilt bis heute als kulturelles Sinnbild für das Unheil des Krieges in Huaxu.",
          TextMapId = "WikiText_40100301"
        },
        WikiText_40100401 = {
          ContentDE = "Die Große Seuche war eine verheerende Epidemie, die Nebelkai vor einem Jahrhundert heimsuchte und durch die erste Plage von Zhuyin ausgelöst wurde. Sie forderte zahllose Opfer und ebbte erst ab, nachdem Zhuyin selbst versiegelt worden war.",
          TextMapId = "WikiText_40100401"
        },
        WikiText_40200101 = {
          ContentDE = "In der Mythologie der Charon gilt das Nebelmeer als der Ursprung allen Lebens. Es heißt, der Heilige Baum habe in seinem Dunst Wurzeln geschlagen und sei in reinweißer Blüte erstrahlt, aus der Mutter Embla hervorging und die lebendige Welt erschuf.\n Die Charon glauben, dass alle verstorbenen Seelen letztlich ins Nebelmeer zurückkehren, und dass auch neues Leben aus seinen Tiefen hervorgeht.",
          TextMapId = "WikiText_40200101"
        },
        WikiText_40200201 = {
          ContentDE = "Die ursprünglichen Gottheiten im alten Glauben der Charon.\n In ihren Mythen wurde die Mutter Embla aus einer reinweißen Blüte des heiligen Himmelbaums geboren, sie erschuf alles – und von ihr kam Vater Ask. Gemeinsam zeugten sie die ersten der Charon.\n Später wurde der Träger der Macht des Todes ein Gefäß des Unheils. Am Ende war es er, der die Welt zugrunde richtete – die Katastrophe namens Ragnarok. Um ihre Kinder zu schützen, opferte sich Embla, die Hüterin der Macht des Lebens. Ihre Seele zerstreute sich im Meer und kehrte schließlich zum Nebelmeer zurück. Asks Körper wurde zum Land und seine erhobenen Arme zu den Bergen, die immer noch zu den Göttern reichen, die längst nicht mehr kommen.\n Eine andere Erzählung führt diesen Schöpfungsmythos weiter. In dieser Geschichte vergingen Embla und Ask nicht, sondern wurden in einer von der Katastrophe neu gestalteten Welt wiedergeboren. Sie würden ein weiteres Ende und eine weitere Wiedergeburt bringen und die Welt und alles Leben in einen endlosen Zyklus von Morgendämmerung und Abenddämmerung fangen.",
          TextMapId = "WikiText_40200201"
        },
        WikiText_40300101 = {
          ContentDE = "Ein kunstvoll gefertigtes, rasiermesserscharfes weißes Schwert im Besitz von {nickname}. Lange Zeit für eine gewöhnliche Waffe gehalten, ist es in Wahrheit der Schlüssel zu einem verborgenen Durchgang innerhalb des Tempels. Laut Berenica wurde das Schwert von jemandem zurückgelassen, der {nickname} einst sehr gut kannte.",
          TextMapId = "WikiText_40300101"
        },
        WikiText_40300201 = {
          ContentDE = "In einem verzweifelten Versuch, seine Tochter Hayley vor dem Ausbruch der Verderbnis zu bewahren, widmete Henrik sich der Entwicklung eines unterdrückenden Serums. Trotz all seiner Bemühungen konnte die Forschung ihre Verwandlung nicht aufhalten, und nach ihrem Tod wurde das Projekt aufgegeben.\n Jahre später nahm Henrik seine Studien wieder auf – diesmal mit dem Ziel, anderen betroffenen Kindern zu helfen. Mithilfe des seltenen Materials Kristallo von Stella gelang es ihm, einen Prototyp des Verderbnis-Unterdrückungsserums herzustellen. Die Formel blieb jedoch unerprobt, und ihre Wirkung war ungewiss.\n Psyche, eine Patientin unter seiner Obhut, meldete sich freiwillig als erstes Testsubjekt. Unerwartet beschleunigte das Serum den Fortschritt der Verderbnis und löste ein frühzeitiges Einsetzen aus, wodurch sie in einen gewalttätigen Zustand verfiel und Henrik verletzte.",
          TextMapId = "WikiText_40300201"
        },
        WikiText_40300301 = {
          ContentDE = "Eine geheime Initiative der Spathatoi, einer Abteilung der Königlichen Alchemie-Akademie von Hyperborea, die direkt von Großkommandantin Sibylle der 13. Legion beaufsichtigt wird. Das Experiment konzentriert sich auf „Nr. 0“. Zur Förderung des Projekts wurde Fulvis nach Flagson entsandt, um einen entscheidenden „Katalysator“ ausfindig zu machen – bislang jedoch ohne verwertbare Ergebnisse.",
          TextMapId = "WikiText_40300301"
        },
        WikiText_40300401 = {
          ContentDE = "Unter dem Vorwand militärischer Rekrutierung hat die 6. Legion Hyperboreas über lange Zeit hinweg körperlich robuste Charon in abgeschottete Ausbildungsprogramme aufgenommen, mit dem Versprechen, herausragende Leistungen könnten mit dem prestigeträchtigen Titel des Lorbeerkranz-Charons belohnt werden. In Wahrheit agierte die 6. Legion in Icelake in enger Kollusion mit der Spathatoi, wählte gezielt Kandidaten mit verborgenem Potenzial aus und unterzog sie heimlichen Augmentationsversuchen – Teil eines umfassenderen Programms zur Entwicklung bioingenieurter Waffen für den Krieg.",
          TextMapId = "WikiText_40300401"
        },
        WikiText_40300402 = {
          ContentDE = "Während der Untersuchung der Jagd auf Charon stieß Major Lynn auf Beweise für die geheimen Experimente der 6. Legion. Sie meldete ihre Erkenntnisse an Sibylle Mason, die Großkommandantin der 13. Legion, wurde jedoch angewiesen, jede weitere Nachforschung unverzüglich einzustellen.",
          TextMapId = "WikiText_40300402"
        },
        WikiText_40300501 = {
          ContentDE = "Eine in ganz Huaxu weit verbreitete Substanz, die aus bestimmten Zutaten nach einem sorgfältigen Verfahren hergestellt wird. Räuchergefäße brennen überall im Land und lassen ihren Duft beständig in der Luft verweilen. Viele Menschen tragen zudem persönliche Räuchersäckchen bei sich. Sie gilt als ein prägendes Merkmal Huaxus.",
          TextMapId = "WikiText_40300501"
        },
        WikiText_40300502 = {
          ContentDE = "Wenn Weihrauch gesegnet ist, kann er den Träger schützen oder Feinde für kurze Zeit abwehren. Ist seine Kraft erschöpft, muss der Träger einen Argent-Loong-Tempel aufsuchen, um den Segen zu erneuern – ein Vorgang, der als „Auffüllung“ bezeichnet wird.",
          TextMapId = "WikiText_40300502"
        },
        WikiText_40300503 = {
          ContentDE = "Weihrauch ist das entscheidende Medium, das die Neun Kapitel aufrechterhält. Der Einfluss des Gesetzes reicht nur so weit, wie sein Duft sich ausbreitet.\n Innerhalb Huaxus wird seine Kontinuität auf zwei Wegen gesichert: durch tägliche, freiwillige Opfergaben des Volkes sowie durch großangelegte, staatlich organisierte Zeremonien. Die allgegenwärtigen Brenner und Räucherbecken werden von der Xuanheng-Sekte betreut, damit der wohlriechende Rauch niemals erlischt.",
          TextMapId = "WikiText_40300503"
        },
        WikiText_40300601 = {
          ContentDE = "Ein von der Jishu-Sekte gefertigtes Gerät. Dieser Würfel mit eingebettetem Energiekern wurde vom Schwarzmarkt speziell für Zhiliu angefertigt, um Zhuyin-Schuppen zu bergen. Er vereint starke Adsorptionskraft mit vielfältigen Funktionen.",
          TextMapId = "WikiText_40300601"
        },
        WikiText_40300701 = {
          ContentDE = "Eine uralte mechanische Falle, die lange Zeit tief im Krähenlied-Hohl geruht hatte, wurde während der Jagdoperation von Herrn Qiu versehentlich ausgelöst.",
          TextMapId = "WikiText_40300701"
        },
        WikiText_40400101 = {
          ContentDE = "Eine traditionsreiche Operntruppe mit umfangreicher Tourneegeschichte in ganz Hyperborea. Die heutige Leiterin ist Frau Putsch; zu den Mitgliedern zählt die gefeierte Sopranistin Violetta. In den letzten Jahren hat die Truppe dauerhaft im Galea-Theater von Icelake Quartier bezogen – Gerüchten zufolge auf persönlichen Wunsch Violettas.",
          TextMapId = "WikiText_40400101"
        },
        WikiText_40400201 = {
          ContentDE = "Ein gefeiertes Opernwerk, inspiriert von einer Volkssage aus Icelake. Es erzählt die Geschichte einer Frostfee, die in einer verschneiten Festung lebt und Freundschaft mit einem Menschenmädchen und ihrem jüngeren Bruder schließt. Berühmt für seine lyrische Schönheit und seine tiefe Verbundenheit mit der winterlichen Landschaft Icelakes, gilt die Oper seit Langem als geliebter Klassiker – einst das am häufigsten aufgeführte Stück im Galea-Theater.",
          TextMapId = "WikiText_40400201"
        },
        WikiText_40400202 = {
          ContentDE = "Nach einer gewaltsamen Auseinandersetzung auf der Bühne des Galea-Theaters wurde die Produktion für zwei Jahre ausgesetzt.",
          TextMapId = "WikiText_40400202"
        },
        WikiText_40400203 = {
          ContentDE = "Hinter dem märchenhaften Zauber verbirgt sich ein tragisches Ende: Um die menschlichen Kinder zu schützen, verlässt die Frostfee ihre Burg und verwandelt sich freiwillig in ein Ungeheuer. Nachdem ihr Versprechen erfüllt ist, verfällt sie unter der gefrorenen Erde in einen ewigen Schlaf.",
          TextMapId = "WikiText_40400203"
        },
        WikiText_40500101 = {
          ContentDE = "Ein Anwesen im Besitz von Henrik, das seit Langem zum Verkauf steht, jedoch aufgrund seines kühlen und unkooperativen Auftretens nie einen Käufer fand. Heute dient es {nickname} als vorübergehende Zuflucht in Icelake.",
          TextMapId = "WikiText_40500101"
        },
        WikiText_40500102 = {
          ContentDE = "Gemäß Henriks Testament ging das Eigentum an dem Haus auf Frau Lina über, die daraufhin auf die Miete von {nickname} verzichtete und {性别:ihm|ihr} erlaubte, dort auf unbestimmte Zeit zu wohnen.",
          TextMapId = "WikiText_40500102"
        },
        WikiText_40500201 = {
          ContentDE = "Ein großes, ehrwürdiges Gasthaus im Norden von Icelake. Seine Tore sind der Öffentlichkeit seit Langem verschlossen.\n Obwohl es als Gasthaus bekannt ist, empfängt es Reisende kaum – wenn überhaupt je.\n Unter den Einheimischen kursieren Gerüchte über seltsame Gerüche, die aus den oberen Fenstern dringen, sowie über geisterhaftes Schluchzen, das nachts zu hören sei. Viele nennen es inzwischen ein Spukhaus.",
          TextMapId = "WikiText_40500201"
        },
        WikiText_40500202 = {
          ContentDE = "Alle Bewohner des Hauses sind Jugendliche unter zwanzig Jahren, persönlich von Henrik ausgewählt. Wer einmal aufgenommen wurde, verlässt das Haus nie wieder.",
          TextMapId = "WikiText_40500202"
        },
        WikiText_40500203 = {
          ContentDE = "Henriks Arbeitszimmer ist ein streng verbotener Bereich innerhalb des Gasthauses – niemand außer ihm darf es betreten. Den Großteil seiner Zeit verbringt er hinter der verschlossenen Tür mit privaten Forschungen. Die jungen Bewohner, allesamt von einer bestimmten Krankheit betroffen, zeigen dabei häufig unnatürliche Verhaltensweisen.",
          TextMapId = "WikiText_40500203"
        },
        WikiText_40500204 = {
          ContentDE = "In Wahrheit dient das Gasthaus als Hospiz für Kinder, bei denen frühe Anzeichen der Verderbnis auftreten. Nachdem Henrik seine Tochter Hayley an diese Krankheit verloren hatte, widmete er sich vollständig dem sogenannten Schlummerprojekt – einer stillen Mission, diese dem Untergang geweihten Kinder vor militärischen Exekutionsbefehlen zu schützen. Als Gästehaus getarnt, bietet das Hypnos’ Haus ihnen einen friedlichen Abschied – einen Ort, an dem sie diese grausame Welt so verlassen können, wie sie sie einst betreten haben: als Menschen, nicht als groteske Bestien.",
          TextMapId = "WikiText_40500204"
        },
        WikiText_40500301 = {
          ContentDE = "Die geschäftigste Taverne in Icelake: Die Asphodel heißt Gäste aller Art willkommen – von Adligen aus der Innenstadt bis hin zu Herumtreibern aus den Elendsvierteln. Unter ihnen befinden sich nicht wenige gefährliche Gestalten, und Auseinandersetzungen – ob verbal oder handfest – gehören fast zum Alltag. Dank der souveränen Taktik und Diplomatie der Chefin Camilla eskalieren solche Vorfälle jedoch nur selten zu ernsthaften Konflikten. In gewisser Weise ist die Asphodel damit der chaotischste und zugleich friedlichste Ort der ganzen Stadt.\n Neben Speisen und Getränken dient die Taverne auch als Treffpunkt für Phoxjäger. Sowohl Auftraggeber als auch Phoxjäger können hier Aufgaben ausschreiben oder annehmen, wobei Camilla als unparteiische Vermittlerin fungiert und Zahlung, Vertraulichkeit sowie die Sicherheit beider Seiten gewährleistet.\n Manche behaupten, die Taverne sei hinter den Kulissen auch in zwielichtige Geschäfte verwickelt. Doch da es dafür keinerlei handfeste Beweise gibt, bleibt dies bloßes Tavernengetuschel – kaum etwas, womit sich die Eskorte ernsthaft befassen würde.",
          TextMapId = "WikiText_40500301"
        },
        WikiText_40500401 = {
          ContentDE = "Phoxjäger sind ein eigenständiger Berufsstand, der seinen Ursprung in Icelake hat und grob mit Kopfgeldjägern vergleichbar ist. Entstanden sind sie, indem sie Aufträge zur Beschaffung von Phoxene annahmen – eine Praxis, aus der sich auch ihre Bezeichnung ableitet. Selbst nachdem der Phoxenehandel vom Imperium und den privilegierten Händlerklassen monopolisiert wurde, bestand der Beruf weiter und entwickelte sich nach und nach über seinen ursprünglichen Zweck hinaus. Heute übernehmen Phoxjäger nahezu jede Art von Auftrag, von belanglosen Botengängen bis hin zu tödlichen Missionen. Solange der Preis stimmt, findet sich stets jemand, der das Risiko eingeht.\n In Icelake versammeln sich Phoxjäger meist in der Asphodel, wo die Chefin Camilla als Vermittlerin zwischen Auftraggebern und Phoxjägern fungiert. Die Arbeit ist oft gefährlich, doch die hohe Bezahlung und der offene Zugang – unabhängig von Herkunft oder Status – machen sie besonders für viele Charon attraktiv.\n Da Phoxjäger ihre Auftraggeber kaum nach Stand oder Herkunft unterscheiden, wenden sich viele Charon aus den unteren Schichten, denen der Schutz über offizielle Stellen verwehrt bleibt, in Notlagen an sie. Mit der Zeit ist aus dieser informellen Gruppe eine Art Ersatz für die städtische Ordnungsmacht geworden und sie sorgt dort für ein Mindestmaß an Ordnung, wo die offizielle Autorität nicht mehr greift.",
          TextMapId = "WikiText_40500401"
        },
        WikiText_40500501 = {
          ContentDE = "Eine Serie von Morden, die sich in Icelake ereigneten. Der Täter schlug in den frühen Morgenstunden des 22. und 25. November zu und forderte das Leben von neunzehn Charon-Opfern. {nickname} war der einzige bekannte Überlebende.",
          TextMapId = "WikiText_40500501"
        },
        WikiText_40500502 = {
          ContentDE = "Augenzeugenberichten zufolge handelte es sich bei dem Täter um eine monströse Entität, die sich im Kanalisationssystem der Stadt verbarg.",
          TextMapId = "WikiText_40500502"
        },
        WikiText_40500503 = {
          ContentDE = "Offizierin Rhythm Fischer und die Nachtfahrer stellten die Entität im Untergrund. Obwohl es ihnen gelang, ihr schweren Schaden zuzufügen, waren sie nach einem Hinterhalt durch einen zweiten Angreifer zum Rückzug gezwungen.",
          TextMapId = "WikiText_40500503"
        },
        WikiText_40500504 = {
          ContentDE = "Nach seiner anfänglichen Flucht änderte der Täter sein Angriffsmuster. Er drang in die Innenstadt ein, tötete mehrere Sola-Bürger und hinterließ Graffiti mit anti-solarianischen Parolen. Diese Eskalation erregte die Aufmerksamkeit der obersten Führungsebenen Hyperboreas und führte zu einem direkten Eingreifen der 13. Legion.",
          TextMapId = "WikiText_40500504"
        },
        WikiText_40500505 = {
          ContentDE = "Später stellte sich heraus, dass es sich bei den beiden Angreifern um Versuchssubjekte eines verdeckten Experiments der 6. Legion handelte – Charon, die einer erzwungenen alchemistischen Augmentation unterzogen worden waren. In dem Versuch, die Wahrheit hinter diesen Experimenten ans Licht zu bringen, schloss sich einer von ihnen, der noch Fragmente von Vernunft bewahrte, den Verlassenen an und verübte gezielte Angriffe in der Innenstadt, um eine formelle Untersuchung durch die 13. Legion zu provozieren. Als er jedoch erkannte, dass die Legion beabsichtigte, die Wahrheit zu unterdrücken, wandte sich der Angreifer gegen seine eigenen Verbündeten und tötete die Handler der Verlassenen.",
          TextMapId = "WikiText_40500505"
        },
        WikiText_40500506 = {
          ContentDE = "Der Fall endete mit dem Tod eines der Angreifer und der Festnahme des anderen durch die 13. Legion. Aufgrund seiner Verbindung zu geheimen militärischen Operationen wurden die vollständigen Details des Vorfalls der Öffentlichkeit nie offengelegt.",
          TextMapId = "WikiText_40500506"
        },
        WikiText_40500601 = {
          ContentDE = "Eine seit langem bestehende Tradition in Icelake, die bis in die Gründungstage Hyperboreas zurückreicht. In der Nacht des Festes legen die Bürger Masken und Kostüme an und versammeln sich im kerzenbeleuchteten Galea-Theater, um Aufführungen zu genießen und bis zum Morgengrauen zu tanzen.\n In einer ansonsten starren und streng hierarchischen Stadt ist dies die eine Nacht, in der Identität und Herkunft vorübergehend in den Hintergrund treten – ein flüchtiges Gefühl von Freiheit, das wohl erklärt, warum dieses Fest trotz seines starken Kontrasts zur üblichen Atmosphäre Icelakes bis heute fortbesteht.",
          TextMapId = "WikiText_40500601"
        },
        WikiText_40500701 = {
          ContentDE = "Ein Begriff aus Huaxu für Händler, die im Fernhandel tätig sind. Der Name spiegelt ihre ursprüngliche Vision wider: voneinander getrennte Orte des Kontinents zu verbinden wie Sterne zu einem Sternbild.\n Als Meister der Navigation und des Handels verfügen die Sternenweber über die einzigartige Fähigkeit der himmlischen Wegfindung, die es ihnen erlaubt, selbst die gefährlichsten Seebedingungen zu überwinden. Ihre Reichweite erstreckt sich bis in die entlegensten Winkel Atlasias.",
          TextMapId = "WikiText_40500701"
        },
        WikiText_40500801 = {
          ContentDE = "Huaxus Bezeichnung für die Charon.\n Anders als im Hyperboreischen Imperium betrachtet das Volk Huaxus die Charon als eine glückverheißende Rasse, die das Land beschützt. Entsprechend sind die Loongscions in Huaxu eine hochverehrte Erscheinung.",
          TextMapId = "WikiText_40500801"
        },
        WikiText_40500901 = {
          ContentDE = "Große Steinstelen, in die die Gesetze der Neun Kapitel eingemeißelt sind. An prominenten Orten in ganz Huaxu errichtet, dienen sie allen als ständige Mahnung.",
          TextMapId = "WikiText_40500901"
        },
        WikiText_40500902 = {
          ContentDE = "{nickname} kann den Inhalt der Stelen unmittelbar wahrnehmen. Dies scheint mit der Kraft der Resonanz zusammenzuhängen.",
          TextMapId = "WikiText_40500902"
        },
        WikiText_40501001 = {
          ContentDE = "Vollstrecker innerhalb des Systems der Neun Kapitel, von höherem Rang als Bi’an. Auch sie gehen aus Loongscions hervor. Nach ähnlicher Argumentation wie bei den Bi’an nehmen Gelehrte an, dass die Magistrate von Yingtian dem entsprechen, was gemeinhin als „Daimon“ bezeichnet wird.",
          TextMapId = "WikiText_40501001"
        },
        WikiText_40501002 = {
          ContentDE = "Ihre Macht entspringt den Neun Kapiteln. Solange ihre Wirbelsäule keinen tödlichen Schaden erleidet, können sie Verletzungen allmählich heilen, indem sie Energie aus diesem höchsten Gesetz schöpfen.",
          TextMapId = "WikiText_40501002"
        },
        WikiText_40501101 = {
          ContentDE = "Diese Tempel sind Taihao geweiht und in ganz Huaxu zu finden. Der größte in Nebelkai befindet sich unmittelbar außerhalb von EverSpring.\n Hier lassen die Menschen ihre Weihrauchbeutel segnen und bringen dem Himmel ihre spirituelle Verehrung dar.",
          TextMapId = "WikiText_40501101"
        },
        WikiText_40501201 = {
          ContentDE = "Ein einzigartiger Beruf in Huaxu, vergleichbar mit Heilkundigen.\n Durch die Neun Kapitel von Dafeng mit heilender Magie begabt, genießen sie einen hohen gesellschaftlichen Status.\n Ihre Fähigkeiten sind erblich. Mit dem Aufstieg der Pharmakologie im vergangenen Jahrhundert ist ihre Kunst jedoch zunehmend in den Hintergrund getreten, sodass heute nur noch wenige Praktizierende existieren.",
          TextMapId = "WikiText_40501201"
        },
        WikiText_40501301 = {
          ContentDE = "Die angestammte Heilklinik der Familie Fu, eingebettet in Aprikosenhaine nördlich von Nebelkai. Ein Ort, an dem Menschen Linderung und Heilung suchen.",
          TextMapId = "WikiText_40501301"
        },
        WikiText_40600101 = {
          ContentDE = "Einst die größte Phoxenemine im nördlichen Hyperborea. Die Erzadern sind längst erschöpft, und obwohl mehrere nahegelegene Fabriken noch in Betrieb sind, wurde die Mine selbst aufgegeben. Ihre ausgehöhlten Tiefen dienen nun als Unterschlupf für Filthoiden.",
          TextMapId = "WikiText_40600101"
        },
        WikiText_40600201 = {
          ContentDE = "Das Galea-Theater, an der Schnittstelle zwischen Innen- und Außenstadt von Icelake gelegen, besteht seit Jahrhunderten und war Zeuge des Aufstiegs wie auch des Niedergangs der Stadt.\n Es ist bis heute der einzige Veranstaltungsort in der Außenstadt, an dem Adelige und Aristokraten noch regelmäßig anzutreffen sind.",
          TextMapId = "WikiText_40600201"
        },
        WikiText_40600301 = {
          ContentDE = "Ursprünglich eine selbstorganisierte Genossenschaft einiger Fischer, wuchs die Icelake-Fischerei mit dem Niedergang des lokalen Bergbaus und dem Aufschwung der Fischereiindustrie stark an. Später wurde sie unter staatliche Aufsicht gestellt und fungiert heute als offizielle städtische Behörde für das Fischereiwesen.",
          TextMapId = "WikiText_40600301"
        },
        WikiText_40600401 = {
          ContentDE = "Eine große Gilde mit Sitz in den Ebenen von Nebelkai. Sie fungiert als Handelsverband der Sternenweber und ist das größte kommerzielle Zentrum von Haojing. EverSpring untersteht dem Ministerium des Wohlstands, das Huaxus Finanz- und Handelsangelegenheiten überwacht.",
          TextMapId = "WikiText_40600401"
        },
        WikiText_40600501 = {
          ContentDE = "Eine angesehene, nichtstaatliche Gelehrtengesellschaft mit grenzüberschreitender Tätigkeit, die sich der Vision verschrieben hat, verlorene Relikte in die Welt zurückzuführen. Sie führt archäologische Projekte in ganz Atlasia durch, mit Schwerpunkt auf der Erforschung antiker Ruinen, der Bewahrung von Artefakten und der Aufdeckung historischer Wahrheiten. \n Die Gesellschaft nimmt Mittel aus unterschiedlichen Quellen an und war einst ein modisches Anliegen der Oberschicht – zu ihren Ehrenmitgliedern zählte sogar eine ehemalige hyperboreische Kaiserin.",
          TextMapId = "WikiText_40600501"
        },
        WikiText_40700101 = {
          ContentDE = "Die offizielle militärische Ausbildungseinrichtung des Hyperboreischen Imperiums. Sie ist für die Rekrutierung und Ausbildung des Personals der hyperboreischen Legion verantwortlich, einschließlich sowohl der Kampftruppen als auch der Logistikeinheiten.",
          TextMapId = "WikiText_40700101"
        },
        WikiText_40700201 = {
          ContentDE = "Die höchste Form der Todesstrafe im Hyperboreischen Imperium, vorbehalten für schwere politische Verbrechen wie Hochverrat oder Spionage. Der Verurteilte wird mit dornigen Ranken gefesselt und kopfüber vom Himmelbaum im Zentrum von Dismania aufgehängt, wo er durch Blutverlust dem Tod überlassen wird.",
          TextMapId = "WikiText_40700201"
        },
        WikiText_40700301 = {
          ContentDE = "Ein Ehrentitel, der vom Hyperboreischen Imperium an Charon verliehen wird, die außergewöhnliche Verdienste erbracht haben. Den Ausgezeichneten werden die gleichen bürgerlichen Rechte wie Sola-Bürgern gewährt.",
          TextMapId = "WikiText_40700301"
        },
        WikiText_40700401 = {
          ContentDE = "Das höchste Gesetz des Imperiums. Historischen Aufzeichnungen zufolge wurde der früheste Entwurf persönlich von Dis I., dem Gründungskaiser, verfasst.",
          TextMapId = "WikiText_40700401"
        },
        WikiText_40700501 = {
          ContentDE = "Ein einzigartiger offizieller Titel in Huaxu, der durch das Mandat des Himmels verliehen wird.\n Ein Loongscion, der von diesem Mandat begünstigt ist, kann in diesen Rang erhoben werden und erhält besondere Autorität sowie einen herausgehobenen Status zur Mitverwaltung der Staatsgeschäfte.",
          TextMapId = "WikiText_40700501"
        },
        WikiText_40700601 = {
          ContentDE = "Eine Schutzsekte Huaxus, gegründet von Yang, der Architektin der Neun Kapitel.\n Die Sekte entdeckte in der Antike als Erste die außergewöhnlichen Eigenschaften des Weihrauchs und bewahrte dessen Anwendung als geheimes Wissen. Heute leitet sie staatliche Weihrauchzeremonien und sorgt für Ordnung in den Argent-Loong-Tempeln. Eines der drei zentralen Verwaltungsorgane Huaxus, das Ministerium der Riten, untersteht ihrer direkten Kontrolle.",
          TextMapId = "WikiText_40700601"
        },
        WikiText_40700701 = {
          ContentDE = "Ein vorläufiges Dekret, das EverSpring nach dem Beginn der Ausbreitung der Plage von Zhuyin erließ. Es untersagt den kommerziellen Reiseverkehr durch bestimmte Gebiete mit dem alleinigen Ziel, die Sicherheit der Sternenweber zu gewährleisten.",
          TextMapId = "WikiText_40700701"
        },
        WikiText_40700801 = {
          ContentDE = "Einst eine Schutzsekte Huaxus, heute im Niedergang begriffen. Die Jishu-Sekte ist auf die Herstellung von Mechapuppen sowie von mit Phoxene angetriebenen Werkzeugen spezialisiert, die in den zivilen Bereichen Huaxus weit verbreitet sind. Eines der drei zentralen Verwaltungsorgane Huaxus, das Ministerium für öffentliche Arbeiten, unterstand früher ihrer Leitung.",
          TextMapId = "WikiText_40700801"
        },
        WikiText_40800101 = {
          ContentDE = "Eine abgeschiedene Insel in internationalen Gewässern, gelegen zwischen Hyperborea und Elysium. Einst war sie die Heimat von {nickname} und Berenica, die dort fernab von der Welt lebten.\n Vor langer Zeit errichteten die Elysier auf der Insel einen prächtigen Tempel, geweiht der Göttin des Vollmondes und des Schicksals. Während der Großen Migration vor beinahe einem Jahrtausend wurde das Bauwerk teilweise zerstört, woraufhin die Insel in Vergessenheit geriet.\n Vor etwa hundert Jahren erreichte eine Gruppe imperialer Fischer – auf der Flucht vor drückender Besteuerung – die Insel heimlich. Sie entschieden sich zu bleiben, siedelten sich an und gründeten das stille Dorf, das bis heute besteht.",
          TextMapId = "WikiText_40800101"
        },
        WikiText_40800201 = {
          ContentDE = "Eine der Provinzen des Hyperboreischen Imperiums, gelegen am nördlichsten Rand seines Territoriums. Etwa die Hälfte ihrer Landfläche wird von dem Vidofnir-Gebirge eingenommen.",
          TextMapId = "WikiText_40800201"
        },
        WikiText_40800301 = {
          ContentDE = "Die größte Stadt im Norden Hyperboreas. Südlich des Vidofnir-Gebirges gelegen, untersteht sie der Verwaltung der Provinz Cocytus. Ihren Namen verdankt die Stadt dem nahegelegenen Klagenden See, der aufgrund des rauen Klimas den Großteil des Jahres über zugefroren ist. Nur während der dreimonatigen „Tauperiode“ beginnt das Eis zu schmelzen.\n Gegründet während der Großen Migration von Dis I., dem ersten Herrscher des Imperiums, gehörte Icelake zu den frühesten Städten Hyperboreas. Über Jahrhunderte hinweg diente sie als Festungsstadt zur Sicherung der nördlichen Grenze des Imperiums.",
          TextMapId = "WikiText_40800301"
        }
      }
    end
  },
  {
    MinKey = "WikiText_40800302",
    MaxKey = "voice_ch_char_Dafu_vo_topic_03_4",
    Loader = function()
      return {
        WikiText_40800302 = {
          ContentDE = "Vor etwa 150 Jahren erlebte Icelake durch einen Aufschwung der alchemistischen Forschung und den Fortschritt der Phoxichor-Technologie eine Blütezeit. Der nahegelegene Himmelbaum reicherte die örtlichen Phoxichor-Adern an und trieb so eine rasante industrielle Entwicklung sowie die Ausdehnung der Stadt voran. Heute jedoch sind die Adern nahezu erschöpft: Der einstige Wohlstand ist verblasst, und die ehemals florierende Industrie befindet sich im Niedergang.",
          TextMapId = "WikiText_40800302"
        },
        WikiText_40800303 = {
          ContentDE = [[
Die Stadt ist in die Innenstadt und vier sie umgebende Distrikte gegliedert.
 Die Innenstadt, auch als Altstadt bekannt, beherbergt die Ratshalle, die Alchemie-Akademie und das Hauptquartier der Legion. Zugang und Wohnrecht sind streng reglementiert: Nur Adlige, hochrangige Beamte, wohlhabende Kaufleute sowie Personen in ihrem Dienst ist der Zutritt gestattet.]],
          TextMapId = "WikiText_40800303"
        },
        WikiText_40800304 = {
          ContentDE = "Die Elendsviertel der Stadt werden gemeinhin Mist Aken genannt – ein Ausdruck aus dem lokalen Dialekt, der „Nebelbezirk“ bedeutet. Das Gebiet liegt nahe den Abluftschächten der Kerninfrastruktur von Icelake und ist aufgrund der kontinuierlichen Emission von Abgasen dauerhaft in Dunst gehüllt. Obwohl die Umwelt erhebliche Gesundheitsrisiken birgt, haben die durch die Dämpfe verursachten leicht erhöhten Temperaturen Mist Aken paradoxerweise zu einem Zufluchtsort für körperlich schwache oder kälteempfindliche Charon gemacht. Trotz mangelhafter Strafverfolgung hat das weitgehende Fehlen des Einflusses der Solarian den Bezirk in mancher Hinsicht zum sichersten Ort für die Charon-Unterschicht in Icelake werden lassen.",
          TextMapId = "WikiText_40800304"
        },
        WikiText_40800305 = {
          ContentDE = "Das Kanalisationsnetz der Stadt ist weitläufig und labyrinthartig angelegt; zahlreiche Abschnitte wurden von der Aeolipile zu militärischen Einrichtungen umfunktioniert. Zweck und Funktion vieler dieser Installationen unterliegen weiterhin der Geheimhaltung.",
          TextMapId = "WikiText_40800305"
        },
        WikiText_40800401 = {
          ContentDE = "Die Hauptstadt des Hyperboreischen Imperiums.",
          TextMapId = "WikiText_40800401"
        },
        WikiText_40800501 = {
          ContentDE = "Die südlichste Provinz des Hyperboreischen Imperiums, angrenzend sowohl an die Elysische Kirche als auch an den Freistaat Aethyrie.",
          TextMapId = "WikiText_40800501"
        },
        WikiText_40800601 = {
          ContentDE = "Eine bedeutende Stadt im Süden des Imperiums, die der Provinz Flagson untersteht.",
          TextMapId = "WikiText_40800601"
        },
        WikiText_40800701 = {
          ContentDE = "Eine strategisch wichtige Festung des Hyperboreischen Imperiums, gelegen auf den Hochlanden oberhalb des Agat-Tals. Einst von den Verlassenen erobert, wurde sie später in einer militärischen Operation von den imperialen Streitkräften zurückgewonnen.",
          TextMapId = "WikiText_40800701"
        },
        WikiText_40800801 = {
          ContentDE = "Eine der wohlhabendsten Straßen der imperialen Hauptstadt Dismania. Gesäumt von den erlesensten Restaurants und Vergnügungsstätten der Stadt, erstrahlen ihre Lichter bis tief in die Nacht hinein.",
          TextMapId = "WikiText_40800801"
        },
        WikiText_40800901 = {
          ContentDE = "Ein Fluss, der durch das Herz von Dismania fließt. Einst eine bedeutende Verkehrsader, gilt er heute als beliebtes landschaftliches Wahrzeichen. Während der Regenzeit soll das leise Prasseln der Tropfen auf seiner Oberfläche sanften Flüstertönen gleichen – eine Eigenschaft, die ihm seinen poetischen Namen verlieh.",
          TextMapId = "WikiText_40800901"
        },
        WikiText_40801001 = {
          ContentDE = "Ein Staat im fernen Osten des Kontinents Atlasia, geeint durch die Verehrung des „Himmels“.\n Sein gesamtes Territorium wird durch das höchste Naturgesetz regiert, die Neun Kapitel von Dafeng, und der Lord Argent, Taihao, gilt als lebendige Verkörperung dieses Gesetzes. Hier dient Weihrauch als zentrales Medium, durch das die Menschen mit Taihao kommunizieren.\n Huaxu ist ein Reich, das sich dem Zusammenleben und dem Frieden verschrieben hat – ein scharfer Kontrast zum Hyperboreischen Imperium.",
          TextMapId = "WikiText_40801001"
        },
        WikiText_40801002 = {
          ContentDE = "Huaxu ist als das „Reich des Friedens“ berühmt. Innerhalb seiner Grenzen ist jede Form direkter körperlicher Gewalt gegen einen anderen Menschen streng verboten.",
          TextMapId = "WikiText_40801002"
        },
        WikiText_40801101 = {
          ContentDE = "Ein bedeutender Hafen im Süden Huaxus, wo Flüsse ins Meer münden. In der Nähe der alten Hauptstadt Haojing gelegen, ist er für sein mildes Klima und seine malerischen Ausblicke bekannt. Als Handelsdrehscheibe dient er als wichtigstes Eingangstor für Fremde, die Huaxu besuchen.",
          TextMapId = "WikiText_40801101"
        },
        WikiText_40801201 = {
          ContentDE = "Der Schwarzmarkt von Nebelkai, gelegen an der westlichen Küste – ein Schiffsfriedhof an der Grenze zur Gritblight-Ebene.\n Wagemutige Fischer aus Huaxu, die durch Schmuggel schnellen Reichtum suchen, stechen von hier aus in See und wagen sich auf gefährliche, geheime Routen in andere Regionen. Verborgene Strömungen lassen ihre Schiffe häufig zerschellen und spülen die Wracks an Land. Mit der Zeit entstand so der Schiffsfriedhof.\n Die natürliche Abschirmung und Abgeschiedenheit des Ortes zog opportunistische Händler an und formte einen grauen Marktbazar.",
          TextMapId = "WikiText_40801201"
        },
        WikiText_40801301 = {
          ContentDE = "Der Wohnsitz der Wishen. Die Yu-Quelle ist eine zentrale Seeinsel in Nebelkai, die bereits in der Antike als „die Schwelle zwischen dieser Welt und der nächsten“ bezeichnet wurde. Der Zutritt erfordert eine persönliche Einladung eines Wishen.",
          TextMapId = "WikiText_40801301"
        },
        WikiText_40801401 = {
          ContentDE = "Das uralte Schlachtfeld der Schlacht von Shuli, nordwestlich von Nebelkai gelegen, als einsame, vom Meer umgebene Insel.\n Einst ein zentrales Forschungsgebiet der Jishu-Sekte, wurden die meisten Konstrukte im Krieg zerstört. Einige sind jedoch bis heute voll funktionsfähig und verteidigen das Gebiet gegen Eindringlinge. Das verlassene Areal wurde später zu einem Zufluchtsort für Vögel, insbesondere Krähen, deren ständige Präsenz dem Ort seinen Namen verlieh.",
          TextMapId = "WikiText_40801401"
        },
        WikiText_40801501 = {
          ContentDE = "Ein von den Vorfahren errichteter Altar zur Vertreibung Zhuyins, der inmitten aufgewühlter See steht und aus der Ferne auf die Gritblight-Ebene blickt. Zhiliu plant, an diesem Ort die erneute Versiegelung Zhuyins zu vollziehen.",
          TextMapId = "WikiText_40801501"
        },
        Wiki_RewardList_Content = {
